window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_013"]={"n":"郭之奇","dyn":"明","poems":[{"t":"八月初四日纪事二首 其一","f":"七言律诗","c":["十载艰虞为主恩，居夷避世两堪论。","一时平地氛尘满，几叠幽山雾雨翻。","晓涧哀泉添热血，暮烟衰草送归魂。","到头苦节今方尽，莫向秋风洒泪痕。"]},{"t":"八月初四日纪事二首 其二","f":"七言律诗","c":["成仁取义忆前贤，异代同心几自鞭。","血比苌弘新化碧，魂依望帝久为鹃。","曾无尺寸酬高厚，惟有孤丹照简篇。","万卷诗书随一炬，千秋霜管俟他年。"]},{"t":"王师以季秋晦拔高明冀露布遂达行畿十绝 其七","f":"七言绝句","c":["千年雪耻事何如，十载人寰气颇舒。","已向羊城收狡窟，更从龙塞觅狼居。"]},{"t":"宛在堂中即事 其一","f":"古风","c":["丘壑方求位置，烟霞遂结居诸。","莫云此日关闭，茅径今朝手锄。"]},{"t":"宛在堂中即事 其二","f":"古风","c":["有意林泉自得，忘机鱼鸟相和。","八千里外藏迹，一勺堂中啸歌。"]},{"t":"宛在堂中即事 其三","f":"古风","c":["回首风尘暂息，考槃寤寐相甘。","试看云物如昨，始信劳人太憨。"]},{"t":"宛在堂中即事 其四","f":"古风","c":["东山随地堪作，人境结庐未喧。","苔径孤宜折屐，荆篱自止高轩。"]},{"t":"宛在堂中即事 其五","f":"古风","c":["数卷图书作主，三春花鸟为邻。","其馀无复长物，此内况容俗人。"]},{"t":"宛在堂中即事二十首 其六","f":"古风","c":["在水之中构室，开窗于此高眠。","何知汉与魏晋，自谓无忧葛天。"]},{"t":"宛在堂中即事 其七","f":"古风","c":["千林秋色回薄，四壁寒声悄然。","晨起登楼眺远，苍苍满目飞烟。"]},{"t":"宛在堂中即事 其八","f":"古风","c":["寒月空庭夜影，落梅满砌霜华。","岭南白雪稀少，欲问阳春此花。"]},{"t":"宛在堂中即事 其九","f":"古风","c":["秦地渔津日杳，漆园蝶梦时生。","非关与世殊俗，聊亦从吾素盟。"]},{"t":"宛在堂中即事 其十","f":"古风","c":["盆花次第依令，园果后先得时。","物物深情可见，年年好景须思。"]},{"t":"宛在堂中即事 其十一","f":"古风","c":["晓树临风骤舞，昏潮带月潜来。","忘言独对终日，静掩柴扉不开。"]},{"t":"宛在堂中即事 其十二","f":"古风","c":["酒熟惟思座上，花开移置阶前。","有时少长咸集，几度幽人未眠。"]},{"t":"宛在堂中即事 其十三","f":"古风","c":["日落榕阴翠匝，风摇兰径芳微。","梦蝴枕上初觉，啼鸟枝头未归。"]},{"t":"宛在堂中即事 其十四","f":"古风","c":["雨过忽变芳草，潮退时翻落花。","清景当前屡易，浮生此际何涯。"]},{"t":"宛在堂中即事 其十五","f":"古风","c":["习静因知得力，逃禅本觉无心。","朔望一变潮汐，今古随流浅深。"]},{"t":"宛在堂中即事 其十六","f":"古风","c":["髀肉经时易满，剑光每夜难韬。","独惭纸上青汗，空付床头白醪。"]},{"t":"宛在堂中即事 其十七","f":"古风","c":["执戟多年倦客，步兵累岁閒身。","草玄独俟知己，眼白相看世人。"]},{"t":"宛在堂中即事 其十八","f":"古风","c":["何须问众清浊，且自观心逸劳。","在我应从古制，于人合让时豪。"]},{"t":"宛在堂中即事二十首 其十九","f":"古风","c":["屈指粤东名丛，曲江南海瑶山。","斯文未丧今日，后死谁人可班？"]},{"t":"宛在堂中即事 其二十","f":"古风","c":["一往深情诵读，半生乐事诗书。","承明著作还彼，百代风骚待予。"]},{"t":"游滁山二十咏 其一 闰正前望冯邺仙大正邀游醉翁亭","f":"七言绝句","c":["十载游心抱白云，醉翁亭记醒中文。","分明庆历当时事，五百年馀独付君。"]},{"t":"游滁山二十咏 其二 有易醉翁亭为解酲阁者书以解㗅","f":"七言绝句","c":["醉醒惟许二能翁，兴废难移百代风。","若道水山无定属，今之健者岂惟公。"]},{"t":"游滁山二十咏 其三 大正既改立文忠专祠而酿泉六一俱以次复其故迹","f":"七言绝句","c":["留得丰山故主人，诸贤后死始堪怜。","当年醉意今如在，但掬清泉似饮醇。"]},{"t":"游滁山二十咏 其四 欧门桥却却望","f":"七言绝句","c":["峰回路转尽繁阴，独立萧然见古心。","为问诸宾从太守，何如禽鸟乐山林。"]},{"t":"游滁山二十咏 其五 醉翁手植梅","f":"七言绝句","c":["不愧梅花是此人，环山得一永为邻。","冰心独壮千秋雪，老干还滋万古春。"]},{"t":"游滁山二十咏 其六 酿泉","f":"七言绝句","c":["潺潺泻出两峰间，刮尽云根破石悭。","香冽寻尝归众口，清辉独洗醉翁颜。"]},{"t":"游滁山二十咏 其七 饮六一泉偶触欧文如泉之语","f":"七言绝句","c":["千年唐宋文章价，江海潮如此亦然。","淘泻心胸存底物，盈科万古视原泉。"]},{"t":"游滁山二十咏 其八 黄维烈囧丞以望日邀游百子潭","f":"七言绝句","c":["水山幽至便通灵，云壑虚生动窈冥。","一自天言河汉落，龙渊千载尚留形。"]},{"t":"游滁山二十咏 其九 薄暮阻雨谒阳明祠小坐","f":"七言绝句","c":["雨作山游兴以心，良知一炬照云林。","忽然夜半求真觉，独有春山动古吟。"]},{"t":"游滁山二十咏 其十 十六日维烈见招于署东见环山台","f":"七言绝句","c":["春薄难分千树色，台幽独剩数梅新。","林泉付与公馀乐，鱼鸟繇来择地亲。"]},{"t":"游滁山二十咏 其十一 十八日游丰乐亭","f":"七言绝句","c":["丰山幽谷共清泉，千载惟馀永叔篇。","遮莫山灵容刻露，几多残碣费磨刬。"]},{"t":"游滁山二十咏 其十二 醒心亭","f":"七言绝句","c":["醉时乐事醒时心，异代空将耳目寻。","惟有山泉供俯仰，幽芳作意劝登临。"]},{"t":"游滁山二十咏 其十三 十九日游琅琊寺","f":"七言绝句","c":["光烟一缕导游心，回马盘纡出秀深。","庶子泉流寒石动，玉皇殿倚碧霄临。"]},{"t":"游滁山二十咏 其十四 二十日游幽栖寺","f":"七言绝句","c":["着意探山山见情，无心出谷谷相鸣。","独惭车马喧幽寺，可有文章答友声。"]},{"t":"游滁山二十咏 其十五 繇寺后上接引佛殿","f":"七言绝句","c":["危阶根向青冥底，古刹烟浮淡薄中。","鸟聚龙参真法界，泉飞竹舞下虚空。"]},{"t":"游滁山二十咏 其十六 二十一日游重熙洞","f":"七言绝句","c":["冥漠中窥小有天，蛟螭徙窟让游鞯。","奇山信有玲珑骨，不遇奇人腹自坚。"]},{"t":"游滁山二十咏 其十七 出洞扪萝而上为旷览亭亭虽废而远眺独宜","f":"七言绝句","c":["千里川原似一毡，胸中丘壑转悠然。","及兹心目方无障，何处云峰欲比肩。"]},{"t":"游滁山二十咏 其十八 薄暮至蟠龙山绝顶漫望","f":"七言绝句","c":["蟠龙见首百峰收，神物依人出旷搜。","日落春风鳞甲动，云归夜壑爪牙浮。"]},{"t":"游滁山二十咏 其十九 二十二日再游醉翁亭","f":"七言绝句","c":["山从游熟转相深，十日钩玄满素心。","赢得诸峰难偃蹇，春云无数绕衣簪。"]},{"t":"游滁山二十咏 其二十 春寒是日和暖特甚丰山似喜人再至也","f":"七言绝句","c":["风光初与醉游颜，半是春情半是山。","颇怪林泉如故识，自今清兴每来还。"]},{"t":"三士道人自赞","f":"古风","c":["诗骚作性，兰雪居胸。","神希太始，气轹王公。","束发筮仕，南北西东。","三仕三已，国尔忘躬。","天光云影，得丧穷通。","老依玄老，空此百空。","遭逢一经，身许丹青。","忧时遁俗，意洁情馨。","翁马恒失，庄蝶未醒。","甘苦异节，壮老殊形。","收而远志，归我澹宁。","古之遗直，今之沉冥。"]},{"t":"八章 其三 瀑布","f":"古风","c":["湖山相联，云汉中悬。","湖山相得，星河下食。","溯流在央，莫褰衣裳。","从水一方，中心委徨。","大之岩谷，小之石木。","悠悠藻洒，望北飞瀑。"]},{"t":"挂席过鄱阳 癸酉北征之作","f":"五言古诗","c":["挂席过鄱阳，匡庐压湖内。","舟行二十日，一与名山对。","弥旬风雨调，及此霁光贷。","陵峦宿浮阴，绝顶舒叆叇。","豁然峙澄流，近遥有馀态。","出自珠玑口，苍然青壁块。","倏忽暂逢迎，历历诸峰剀。","插石拂层穹，积林吞众薆。","紫氛生其上，将无白日碍。","下飞瀑布泉，潈射奔空溃。","洒落云天珠，势向扁舟碎。","举头一挹之，烟颜坐可靧。","而我览胜怀，初符宿所爱。","敢云默祝开，晴明我适逮。","虽云望中游，眼到身应在。","云间意自清，尘外胸无退。","灵秀远相披，况与明湖载。","因知造物奇，以湖作山配。","二三百里中，依依如襟佩。","横侧一舟行，千岭争向背。","日暮征帆遥，杳然波上黛。"]},{"t":"憩庐山东林寺和王阳明先生壁间韵","f":"七言古诗","c":["百里山行迷碧草，息心对山觉山好。","六朝僧去忽千霜，三秋招隐惟五老。","一峰初上晓松哀，瀑布声闻客绪开。","舍车纵步过东寺，山僧谓我结莲来。","莲社年来孰为首，我亦渊明性耽酒。","颓颜独倩菊英滋，酣情易令苍山朽。","祇今望阙复趋庭，云舍南溟动远汀。","他时散发罗浮上，对望仙庐九叠青。"]},{"t":"过鄱湖望庐山因作湖山吟时庚辰春王十一日也","f":"七言古诗","c":["自有庐山岁几千，鄱湖相对是何年。","自有湖山初见我，一十四载九洄沿。","每从南极瞻五老，及到西江望比肩。","芙蓉削出珠玑口，银河倒泻香炉烟。","九叠苍屏空杳杳，千寻瀑布亦溅溅。","阴阳此际藏真宰，流峙分形俱后天。","天生名山必有配，高广依稀二者传。","非山莫与湖吐噏，非湖孰任山蜿蜒。","雨后洪泉飞洒落，秋来惊浪恣腾骞。","澄流舒卷如涘滴，芳麓沉浮但浣湔。","不向湖情窥浩漠，安知山德备泓渊。","湖山阅人亦有数，何人独领湖山全。","百里舟行异横侧，多年望眼破拘挛。","空灵一气开昏晓，幽光百道变黄玄。","随意犹能招俯仰，息心或可尽中边。","及此方求江汉始，因之欲向斗星连。","耳目今朝如是耳，湖山万古自悠然。"]},{"t":"和张曲江湖口望庐山瀑布泉","f":"五言律诗","c":["洪泉飞九叠，万壑动群氛。","势落悬峰日，光摇出岫云。","晦明殊所见，近远各为闻。","顿令萦心目，孤情冷复氲。"]},{"t":"和自彭蠡湖初入江","f":"五言律诗","c":["湖尽匡山际，江通汉水浮。","朝烟生夹岫，夜月识扁舟。","远望多为感，乡心少不愁。","自怜身似苇，朝夕与波求。"]},{"t":"自吴城至马当湖江八景 其三 瀑布 在匡庐","f":"七言律诗","c":["苍屏九叠尽飞荣，风雨千岩欲怒鸣。","泉石初开天籁发，水山相杂大文生。","每乘清气阴阳御，渐出光华人世迎。","不是银河天际落，峰头那得挂长庚。"]},{"t":"庐山道中憩东林寺询寺僧以远公旧事","f":"七言律诗","c":["四望苍屏尽渺然，松开忽见紫炉烟。","怪来九叠祥光出，独向东林瑞像前。","竺影难留图里迹，素沙犹自雨中研。","几回频就山僧问，谁忆当年论五篇。"]},{"t":"对庐山默约","f":"七言律诗","c":["白云作意令山深，平卷诸峰上客襟。","欲因康乐寻幽兴，顿拨渊明入社心。","薪火相传无异昔，愿文初发已从今。","若待辞荣来此地，千年空属远公岑。"]},{"t":"语庐山","f":"五言绝句","c":["终南成诟厉，所处失其亲。","遥揖山灵语，慎居捷径人。"]},{"t":"望庐山和苏韵","f":"七言绝句","c":["相对无缘认岭峰，入看只与白云同。","江舟竟日分横侧，真面遥临一水中。"]},{"t":"既而湖山暮接清风拂月复成其一","f":"七言绝句","c":["庐山如屏湖如镜，白云其容月其性。","湖偏宜月山宜云，风以为媒初相娉。"]},{"t":"因念昔者寺僧乞诗子瞻留一绝曰帝遣银河一派垂古来惟有谪仙词飞流溅沫知多少不与徐凝洗恶诗今之题庐山者益多谨依韵述之以告诸词客","f":"七言绝句","c":["庐山误出此篇垂，多少徐人欲李辞。","今日徐人才更倍，谪仙跽请主僧诗。"]},{"t":"道经庐山憩东林寺僧人索句","f":"七言绝句","c":["五老峰深近远迷，六朝灯在色空倪。","林僧索我庐山句，不尽游踪未敢题。"]},{"t":"车中望最高峰","f":"七言绝句","c":["征车偃蹇出松林，望入云丛最顶岑。","为问三千三百六，可容一步一孤吟。"]},{"t":"鄱湖晓色","f":"七言绝句","c":["点点云山在水旁，清沙碧渚侵晨光。","西峰落月衔烟树，影到波心万顷苍。"]},{"t":"过庐山绝句","f":"七言绝句","c":["欲识庐山真面难，先从芳麓见髀髋。","五老云中银汉落，香炉雪后紫烟寒。"]},{"t":"榕城八景 其一 环城榕色","f":"七言律诗","c":["乔木森森望郁苍，相传岭国古榕乡。","四时霜盖烟疏密，一片云丛绿混茫。","道左何年歌杕杜，州南此日诵甘棠。","天为炎土垂休息，故使馀阴百里凉。"]},{"t":"榕城八景 其二 绕窖棉阴","f":"七言律诗","c":["玉川如带绕城阴，入眼丛青翠影侵。","已淈污泥从水出，遥参碧汉倩云禁。","连翩各有扶疏质，独立犹馀萧飒心。","不信松寒非可并，多年海国挺孤森。"]},{"t":"榕城八景 其三 紫陌春晴","f":"七言律诗","c":["春光早向紫峰生，渐出峰容与世迎。","古黛凝云初映晓，新苔转日久曛晴。","啼莺城北衔幽至，舞燕溪南逐翠行。","传语东风无造次，时留烟景作山情。"]},{"t":"榕城八景 其四 黄岐晚翠","f":"七言律诗","c":["城头北望晚山逢，久对悠然净俗胸。","泉石情因深色见，烟霞癖与素心封。","积云每见堆双洞，新月时来照一峰。","十里幽光难可即，千秋苍质自为容。"]},{"t":"榕城八景 其五 二溪明月","f":"七言律诗","c":["双溪垂带曳榕城，最爱光潮涌晚生。","半落市埃分皓白，平开天镜下孤清。","遥山助色烟云扫，近野浮空藻荇迎。","长忆玄晖如练语，更添月意作江情。"]},{"t":"榕城八景 其六 双洞疏烟","f":"七言律诗","c":["烟霞有意日相求，双洞林光竞远投。","青霭春来如迸发，白云秋去尚群游。","郁纡遥结山灵秘，冥寞中开佛象幽。","试看今朝松竹影，方知千载色空留。"]},{"t":"榕城八景 其七 元塔登高","f":"七言律诗","c":["龟山宝塔字涵元，灵杰相因表独尊。","欲锁螭宫雄海柱，先驱鳌背壮天根。","南来百水俱朝会，北拱诸峰各骏奔。","若问参云尚有级，人文地气此初掀。"]},{"t":"榕城八景 其八 鳌桥钓浪","f":"七言律诗","c":["溪城如岛水环之，西驾东流此一丝。","万里海风浮汉影，百重山色压虹眉。","于秋倍觉潮声壮，有月常窥钓影垂。","每听沧浪歌曲罢，眼中清浊意中知。"]},{"t":"百山歌","f":"五言古诗","c":["山途历四省，踰山步百邦。","山从地分域，地因山别疆。","穿山繇山径，依山止山乡。","山蔬备晚食，山鸡促晓行。","行行周山绕，宛在山中央。","山心含故意，入山独彷徨。","迤逦擐山足，跌踼陟山嶈。","山岚蒙山暖，山树拂山凉。","山容撤山景，山气发山光。","山日浮幌荡，山峰破混茫。","山风吐山响，山云焕山妆。","山中静藏月，山外远连江。","山峡流清潎，山谷激飙飏。","山泉幽以泶，山林静而芳。","山陵断还续，山蹊纡复障。","山舟横山渡，山榾引山梁。","屴崱连山脉，㠎嶪郁山冈。","山居宅山曲，山家隐山傍。","山城山作邑，山民桀如狼。","山田多硗埆，山村掩寂荒。","山中何所有，山坂富牛羊。","山童啸山歌，两两在山畼。","秋深山薄绿，冬至山敛黄。","离叶散山翠，振条落山苍。","山花孤承露，山卉半染霜。","山松开山籁，山桂郁山香。","山篱垂山菊，山竹披山篁。","山骨劳巧匠，山鬼筑夜墙。","山门溜夹水，山观寂飞窗。","雨濛山先翳，天霩山自旸。","山庵如鸡栖，山路多羊肠。","崒嵂崇山髻，嶕峣结山鬃。","山石参山势，山滩竞山强。","环山多郁垒，梯山就崆㟅。","祇随山俯仰，莫计山短长。","近山历可数，远山叠可望。","期着东山屐，先拟北山章。","全挹西山爽，还归南山阳。","久从山朝暮，微识山行藏。","赋成百山语，歌与百山商。"]},{"t":"司徒林忠宣公赞","f":"古风","c":["五岭之南，百粤之东。","卓生伟人，林左司农。","谦卑以牧，允出自中。","直大而方，即赋乃躬。","脩髯广额，曰貌有颙。","我闻在昔，温厉安恭。","求诸今日，庶乎见公。","揆兹素履，表厥遗丰。","两仕为令，乐只何融。","四垣既历，正色何恭。","廿载家食，敦睦何雍。","形虽三变，道本无穷。","潜见飞跃，公其犹龙。","六卿晚陟，寅协载同。","帝嘉乃德，老成直忠。","归真反朴，急流维风。","云胡能此，至至终终。","呜乎太山云出，天下雨濛。","朝既嘉赖，乡复被蒙。","休休仪表，烱烱德容。","仪写人目，德留人衷。","衣裳我觏，佩玉其瑢。","赞以赞德，匪像是供。","兴歌赤舄，徒仰乌弓。","永言法则，世也其宗。"]},{"t":"九歌 其一 出门","f":"楚辞体","c":["春王正兮予征，驾言北兮神京。","晨风开兮宿雨，惆怅啼兮曙莺。","罗亲友兮周堂，启先祠兮告行。","顾庐园兮有日，忽相远兮愁生。","此相远兮纫臆，矧骨肉兮为情。","惟牵衣兮是刻，有姊弟兮怦怦。","长者前兮致语，少者旁兮涕盈。","终不能兮无别，二人慰兮偕程。","马萧萧兮车辚，真出门兮已成。","揖黄山兮玉水，不吾负兮初盟。","望南州兮芳速，纷百草兮缤迎。","绿茵兮红盖，桃李帷兮柳旌。","朝发兮榕浦，夕跻兮凤城。","遂从舟兮鳄渚，月皎皎兮既明。"]},{"t":"九歌 其二 惜别","f":"楚辞体","c":["春色兮风吹，春情兮水澌。","杳烟容兮氲霭，逝将汝兮天涯。","色无地兮不随，情以人兮见离。","赖祖筵兮斗酒，隐离心兮寸丝。","何征舠兮发发，斲洄波兮使愁知。","驱青莎兮白石，暂友分兮亲辞。","邅吾舟兮率浒，觌前车兮载脂。","明知别兮忍不言，及言别兮失其词。","抚稚子兮揖岩，慈母曰犹来兮父曰勉之。","指长安兮见日，睨此地兮云垂。","云垂兮今朝，长安近兮此地遥。"]},{"t":"九歌 其三 回首","f":"楚辞体","c":["青山兮尽日，晓夕成兮潮汀。","出门异兮风俗，所可同兮山青。","试骋目兮千里，杳冥漠兮林坰。","前峰递兮遥黛，夹道来兮近馨。","腾予策兮芳径，偃予车兮翠扃。","与烟鸟兮栖迹，朝松扉兮夜桂驿。","惟万木兮纷披，气高浮兮自泽。","破东日兮分苍，敛西霞兮继碧。","或黯淡兮异容，云片片兮巾舄。","冈峦合兮阴易生，溪谷深兮风雷窄。","雨后山兮更清，时变化兮惟百。","此其入眼兮如此，若言其愁人者兮不可绎。","溯登历兮指弹，分闽山兮千盘。","但驰心兮有格，云何步兮跚跚。","仰揭孽兮连峰之怪石，俯奔崩兮泻麓之哀湍。","下断桥兮树杪，横野渡兮根蟠。","忽瞻望兮屺岵，长胁息兮气乾。","尚慎旃兮行役，无自苦兮多端。","望此身兮山中人，强自排兮与愁瞒。","故山一天兮不可即，汀山有素兮聊与之安。","人亦有言兮山路险难，吾今矢歌兮薄自宽。","闻古人兮陟升皇而临睨，谁能无回首兮三叹。"]},{"t":"九歌 其四 下滩","f":"楚辞体","c":["招招兮舟子，语予兮津是。","江国兮上游，万里流兮从此。","怀粻糗兮涉之，有伯兄兮偕在水。","揖诸山兮叩舷，及春涛兮方瀰。","下章水兮无穷，念烟波兮今始。","朝石齿兮暮沙眉，与凫鸥兮问栖止。","栖止兮悠悠，所与同兮芳洲。","洲何有兮鱼火，时灭明兮钓舟。","鱼何为兮石际，人何为兮水陬。","叹所贪兮不同，各于物兮有求。","感我思兮瞿瞿，思卬友兮俟前途。","就虔江兮赊月色，买春酒兮与朋俱。","三杯耳热兮仰天呼，万里沧洲兮不近吾。","羌东风兮吹鼓，闻吾言兮神灵雨。","云青青兮帷峰，波跃跃兮腾浦。","顾瓶罍兮满空，尽水山兮吞吐。","愿长醉兮无醒，恣一叶兮转萍。","惟元侯兮秉钺，麾五两兮相迎。","五两兮飘飘，飞龙兮翘翘。","躐奔湍兮自适，凭急濑兮不可摇。","抱日流兮泱漭，穿月波兮逍遥。","纷参差兮偃仰，遂习惯兮晨宵。","汨流程兮有旬夕，乃滩穷兮五云驿。","所与舟相敌兮朔风骄，停友兄之舲兮使前格。","我亦歌兮且谣，视诸君兮为迫。"]},{"t":"九歌 其五 感昔","f":"楚辞体","c":["遣思兮晴春，怡情兮夜月。","问春月兮几何，曾雨风兮频龁。","风及朝兮山鸣，雨连夕兮波蹶。","飞玉峡兮泫淋，下金川兮冯㶿。","已入眼兮凄然，矧予肠兮多愲。","抚时地兮低徊，念伊人兮存没。","一悼临江座师张紫波，过其地而有感也。","一悼公车自从叔，于庚午冬是日是地相遇。","挹洄水兮书哀，隐诸怀兮悾惚。","憺吾舟兮容容，望西江兮浩勃。","出钟陵兮故都，缆滕阁兮旧阙。","西山雨兮南浦云，思古人兮坐超浡。","彼一时兮此一时，今与昔兮波中汩。","杳予胸兮曷穷，亦长流兮无竭。","但有思兮在心，随所地兮惊骨。","夜来梦兮魂飞，烟涛恶兮难越。","晨枫振兮萧萧，晓莺啼兮矻矻。","欲轻此愁声兮不闻，故来予枕上兮迷忽。"]},{"t":"九歌 其六 泛望","f":"楚辞体","c":["于戏兮旷哉，彭湖兮飞渡来。","朝南浦兮云棹，夕吴城兮月桅。","击余汰兮烟阔，扬吾舲兮波开。","波开兮未极，高帆举兮瞬息。","风从水兮为鳞，舟在山兮振翼。","望百里兮匡庐，坐超忽兮横侧。","分晴明兮众形，递遥迩兮诸色。","虽变化兮多端，犹卷舒兮无匿。","謇将揖兮披衷，尚微杳兮难即。","终有言欲告兮不能不前，亦惟感晴春兮非其易得。","恐阴曀兮中生，蔽光颜兮外蚀。","或风雷兮怒凭，驱木石兮崩仄。","或雨雾兮偏蒙，长荆榛兮荟薿。","人曰此兮天之变时，余实忧兮山之累德。","岂若兹兮霁初容，峙明湖兮不可惑。","横千顷兮黛波，与清风兮琢磨。","渺波臣兮一叶，维七载兮五过。","顾寸心兮有日，溯流从兮水之阿。","怀余情兮未发，焉能忍兮无吪。","恃中忱兮谅直，想山意兮渊和。","遂倚窗兮至夕，舟既远兮为歌。","念青帝之司峰兮亦无多，将鸣鹈之度岭兮奈时何。"]},{"t":"九歌 其七 雨江","f":"楚辞体","c":["挂烟帆兮九江，沿落日兮孤艭。","飘五刃兮返集，凑千舲兮聚哤。","下人声兮汰响，出云气兮桅杠。","朝举首兮高原，暖枫陂兮杏村。","与风情兮既习，落春色兮无言。","因吾舟兮晨夕，漠相对兮销魂。","销魂兮谁说，正清明兮雨节。","湿栖鸟兮尚无飞，止居人兮亦关闭。","谁能客兮久悲离，若以羁兮初怨别。","分明此地兮可心折，不但天涯兮有绪结。","分明此时兮自劳人，不但游子兮有愁新。","蹇方怀兮寸接，诸繁会兮千稔。","欲栖栖兮此迷，欲竞进兮前怯。","渺渔人兮告余，曰无往兮安居。","如此风波兮不可趄，慎渊默兮戒呼嘘。","孰中忱兮与答，勉扁舟兮飒飒。","击危舷兮浪横，循欹席兮波踏。","山卼臲兮终安，流奔崩兮既纳。","矢朝宗兮一心，曷长阻兮呜唈。","岂不迟滞兮江之滨，亦江情兮为我陈。","历阴霁兮诸变亲，习流洄兮是知津。","于捷迂兮今何有，定夷险兮视兹身。"]},{"t":"九歌 其八 烟缆","f":"楚辞体","c":["虫声兮荇喓，蛙首兮蘋翘。","日愁余兮章水，今侬语兮吴桡。","缆江山兮寸缠，藏风雨兮方瓢。","溯深春兮柳泽，入远思兮花陌。","知烟容兮自来，遣波致兮安适。","忽反顾兮失其端，收浩胸兮入静看。","羡青云兮鸟举，瞻紫雾兮龙蟠。","意中事兮临眺，驾言出兮登盘。","二水三山兮曷其有极，胜多时促兮游亦无宽。","寻雨花兮遗迹，陟旋玉兮象坛。","古帝祠兮云罩，今麟阁兮风摊。","但驰怀兮志肃，恐兴溯兮情寒。","亦余心兮不敢安，何今昔兮尽于观。","目忽下兮人烟团，身在高兮山绪乾。","回昏舆兮循月峦，足游气兮指星竿。","劳樽酒兮候潮钻，抱春梦兮不知残。"]},{"t":"九歌 其九 远目","f":"楚辞体","c":["望紫阙兮春风，知瀛洲兮草绿，愁绿芳兮近缩。","日莫黯兮黄昏，时莫凄兮春蹙。","地莫悲兮岐途，人莫苦兮远目。"]},{"t":"愁三水","f":"楚辞体","c":["金陵兮望终，尚眇眇兮难通。","波缭转兮相缔，风参差兮末穷。","倚潺湲兮聘目，船容与兮西东。","江去去兮未随，山蹇蹇兮入胸。","乱帆影兮沓絓，忽南北兮迷从。","愁来兮生望，望逾远兮云逢。","积霮䨴兮阴昼，烟复继兮蒙蒙。","吹余气兮决去，揖东君兮陈衷。","客不堪兮再阻，反谓余兮容容。","羌遂逝兮西瞑，徒俛首兮问躬。","已劳心兮既久，何斯须兮有忡。","横四海兮自许，曾溯流兮可壅。","投词兮尔约，一捐玦兮此中。"]},{"t":"望三山","f":"楚辞体","c":["若有人兮溯江干，阻长流兮心恻酸。","舟三易兮旬四，春冉冉兮冬殚。","何终风兮号怒，既北击兮东抟。","曷飘飞兮杲杲，蔽若木兮跚跚。","空馀晖兮波接，波蹀躞兮夕澜。","方浟涣兮激涘，忽沮洳兮潮钻。","同濊汤兮不息，吞吐久兮微安。","舟子呼兮棹发，展余愁兮气宽。","迟一苇兮所恣，眇三山兮入看。","云蹇产兮俱岫，露厌浥兮其漙。","嘒彼星兮三五，履我发兮月初冠。","惊雁行兮未息，见牛喘兮啴啴。","曾相随兮会少，甫一见兮欲残。","始帝都兮生色，开天镜兮莫奸。","浩淼莽兮如练，叠琇瑩兮相攒。","烛东南兮佳气出，影近远兮人烟团。","明百流之朝宗兮一志，见千峰之伏阙兮多端。","固江山为有道兮葱郁，信龙虎所繇来兮踞蟠。","岂波臣之骏奔兮敢后，维下风之羽翼兮实难。"]},{"t":"春日行","f":"古风","c":["春日春江春气翔，有客宛在水中央。","东村歌笑喧儿女，西岸雪艳逞梅香。","不知春色何处动，但闻春至绕春肠。","因启纱窗来晓望，飘飘兀自北风凉。","应为乾坤除枯萎，洒扫山川俟春光，从此窅冥开至阳。","太平年，景物昌。","清时朝野尽皇唐，普天之下乐无方。","虽为客，莫思乡。","我生遭明盛，一日须千觞。","江头有酒莫辞醉，醉后歌讴有道长。"]},{"t":"长相思 其一","f":"古风","c":["长相思，在长江。","云端有女拥朱幢，玉手相招不肯降。","下方无缘通情愫，稽首再拜立纱窗。","我有白璧价无双，愿因长风献尊前。","中途犹恐黑云逢，阊阖之门未应闭，扁舟何事阻奔泷。","长相思，水淙淙。"]},{"t":"长相思 其二","f":"古风","c":["长相思，水之湄。","西江晚涛恶风吹，梦魂怕险不敢移。","当初谁使轻离别，祇今遥遥天一涯。","寒灯久坐亦何为，肠断千回肝百分，恨来笔端怨入眉。","怨恨悠悠冬春易，人乐新年客愁知。","长相思，春复悲。"]},{"t":"胡无人","f":"古风","c":["犬羊狼戾肆骄矜，旄头光影四飞腾。","须臾万甲窥青海，唐突千骑环白登。","皇风广漠包胡越，恩许酋奴朝闉阙。","丑类终难文德敷，阶舞羽干阃授钺。","天兵如日胡如霜，疾趋阳岭还定襄。","还定襄，渭耻雪，渐次收边复扫穴。","樊侯横十万，卫国率三千。","胡无人，敢逆天。"]},{"t":"前有樽酒行二首 其一","f":"古风","c":["娟娟山日拂鲜苔，冉冉江风过落梅。","梅落苔鲜两相催，美人欲来竟不来。","且须顾影自倾杯，醉舞中流夕阳回。","夕阳回，狂波阻。","前峰一带寂无人，春光非余孰怜汝。"]},{"t":"前有樽酒行二首 其二","f":"古风","c":["丝丝春草各春辉，含情滋露上枝肥。","晴烟初试东风暖，暮霭轻沾西日晖。","江头来碧色，苍翠披客衣。","披客衣，进客觞，他时对酒莫相忘。"]},{"t":"邯郸才人嫁为厮养卒妇二首 其一","f":"五言古诗","c":["小小邯郸宫，春春崇台柳。","常忧恩宠疏，不如民间妇。","谁知辞玉阶，朱颜镜中丑。","舞衣叠空厢，日夕从箕帚。","中夜起长吁，捧心增愧忸。"]},{"t":"邯郸才人嫁为厮养卒妇二首 其二","f":"五言古诗","c":["自从金屋贮，自言独恩幸。","衾裯尚兴嗟，歌舞还羞骋。","扬蛾绝三千，不顾长门冷。","谁信中道迁，骄妒难久永。","裳衣呼驾予，流落操臼井。","日向耕织谋，何处风流整。","转喉孰怜音，临妆独矜影。","声容坐没销，宠贵两无逞。","抚此丑陋姿，憔悴方自省。","流泪向终宵，魂梦飞金屏。","始念君王恩，贱妾诚徼倖。"]},{"t":"春闺八首 其二","f":"五言古诗","c":["晨起幽香送，晓风谢落梅。","羞与愁人对，寂寂向青苔。","好留明春色，含意待君来。"]},{"t":"春闺八首 其三","f":"五言古诗","c":["流莺花下啭，罗帏始春声。","妾痴从莺语，莺娇向妾鸣。","莫待春光老，为侬啼玉京。"]},{"t":"春闺八首 其四","f":"五言古诗","c":["晴日寒烟敛，霜轻华露滋。","池塘伤心碧，春来芳色垂。","妾身不如草，君去玉颜移。"]},{"t":"春闺八首 其五","f":"五言律诗","c":["飞蓬辞膏沐，无复向妆谋。","卉木犹春好，妾鬓独惊秋。","鬒云终何似，已当吟白头。","谁怜拥髻泣，愁绝自登楼。"]},{"t":"春闺八首 其六","f":"五言律诗","c":["捲帘开玉匣，庭影百花流。","低徊怜新饰，红紫杂妆浮。","那得双蛾黛，一回万里眸。","朱颜君错过，枉自觅封侯。"]},{"t":"春闺八首 其七","f":"五言律诗","c":["朝来三青鸟，为报远相思。","开缄碧纱牖，东风拂恨吹。","良人红尘陌，犹言怅天涯。","可怜深闺里，长日守春缡。"]},{"t":"春闺八首 其八","f":"五言律诗","c":["闻道幽燕地，春寒雪犹花。","灯前捣衣寄，要襋冷霜华。","明朝辞素手，迢递向天涯。","传语好人服，无令黄里嗟。"]},{"t":"古歌","f":"古风","c":["古今荡荡入相思，古不休，今不休。","我生其时，何日自繇，转眼白头。","节序肯饶人，云物何悠悠。","秋虫暮入耳，霜鸿朝入视。","蹀躞步郊原，愁坐不能起。"]},{"t":"悲歌","f":"古风","c":["欲歌恐泪先放，欲望恐泪先垂。","风吹日微，百草变衰。","所思寸云生，所见千林满。","举手折千林，尽作一寸短。"]},{"t":"战城南","f":"古风","c":["战城南，死河北，河鱼上食乌意逼。","为鱼谓乌，莫竞微躯。","城东新战斗，尸尸枕藉尽肥腴。","飞骑出没，残兵计谋。","敌踪今暂远，功赏可尸求。","尸莫守，泣冤燐，闭腐口。","愿乌相食先自首，首蒙贼名安可朽。","生负国恩，死为人冒功。","兵言何伤，尸心不同。"]},{"t":"代淮南王","f":"古风","c":["淮南王，立小山，八公相见尽童颜。","不愿大藩愿大年，八公右左语丹玄。","语丹玄，指仙经。","天地大文不可明，阴阳百六妒虚清。","紫房彩女色如神，朝朝暮暮倚君身。","倚君身，结君臂。","为云为水，从君至西。","日难升，秋难夏，金风飒飒吹长夜。"]},{"t":"西门行","f":"古风","c":["出西门，望秋声。","绕树驱蝉出，蝉困初醒。","呼蝉语支离，鼓翅迎安能。","寂愁久相对，舍汝复行行。","穿窈谷，出深松。","长歔下夕阳，肃肃起天风。","振衣千仞石，挥鞭九叠峰。","顾视人间世，闻见殊不同。","不为世人烦苦逼，谁鼓逸足游上清。","不为世人烦苦逼，谁鼓逸足游上清。","天半飞天籁，心耳愧初生。","人间何所有，苍蝇响重轻。"]},{"t":"东门行","f":"古风","c":["出东门，见如云。","步入门，妾待君。","君心如有存，细察君意如有分。","还言相告语，世上自纷纷。","此人一颦一笑，别后多时尚氤氲。","尚氤氲，兰蕙出交襟，宛转流黄百合薰。","有心无心，赵舞燕吟，千人百人道出群。","有心无心，赵舞燕吟，千人百人道出群。","人人口牙芬，人所言，或欺君。"]},{"t":"拟行路难三首 其一","f":"古风","c":["落涧辞峰未随溪，奔壑顾山难行。","子辞家去，寻烟野宿，自饥寒行。","子行日远，道逢落涧坐长叹。","车为不转辕，马为踯躅向郊原。","人自轻离何足道，秋风车马畏黄昏。"]},{"t":"拟行路难三首 其二","f":"古风","c":["胡马望风嘶，越禽向日心依恋。","我今出门乍辞家，他乡风物非习见。","不畏他乡遥，常畏他人相轻贱。","千山峻绝自登攀，万水烟波绝绻缱。","思我钱帛来逢迎，偶逢失意俱中变。","昨夜归梦向家人，梦短愁多难语遍。"]},{"t":"拟行路难三首 其三","f":"古风","c":["一山一水又一乡，风风雨雨最凄凉。","水山终始但车舟，风雨凭淩失春秋。","昨宵简历数秋光，九月下旬为降霜。","杨柳多时欲萎落，莎鸡在户已深藏。","行子中道见时物，清朝如何不彷徨。","彷徨还自念，念我容颜独秋当。","深愁素髭欺客至，难将短鬓较途长。","征衣自加还自惜，忽闻暮响何茫茫。","想有羁人同旅怨，故令清砧厉空房。","或因明月生离思，复令幽机覆流黄。","流黄满疋向月清，佳人刀尺就机鸣。","思君腰带如畴昔，但妾愁多未能成。","听此令人伤远神，征夫相值愿传声。"]},{"t":"有所思","f":"古风","c":["有所思，寒不知冬，暑不知夏。","旦不知昼，昏不知夜。","闻人悦春光，起视春光断柔肠。","闻人爱秋清，坐守秋清出愁情。","来日悠悠去日多，花开怯对落如何。","风雨驱花异夕朝，朝夕衔思赴远遥。","朝思在山神巍峨，暮断在水梦风波。","飞鸟当前见人心，不传思人往来音。","毋乃心心不相识，能鸟知之朝唧唧。","人因谓我无思远，口欲相置心难挽。","春蚕成茧还吐丝，丝短丝长织女知。"]},{"t":"上邪","f":"楚辞体","c":["上邪，心相悦兮相知，指天戒别离。","日朝沉，月不为偶，春斗西横箕北走，云风朽，乃与君分首。"]},{"t":"续晋白纻舞歌诗","f":"七言古诗","c":["舞衣乍着双罗飘，却步帘屏近且遥。","呈躯欻举意盈饶，翔止低昂颜矜骄。","疾徐生节鸣佩瑶，宛转长褕称身腰。","进从飞鸟翼回飙，退旋秋水袜轻漂。","明明如月向风摇，下上流华云所招。","云风忽止倚羞娇，半发朱唇兰气敲。","回眸挥手助笙箫，掠鬓将前众企翘。","四座光临不敢嚣，随其所见目成挑。","掌上当年疑汉妖，白纻歌章有晋谣。","凡百君子乐清朝，观舞能言友宾恌。"]},{"t":"古诗二首 其一","f":"古风","c":["人寿非金石，何以结天年。","我身非珠玉，何以结世缘。","优哉游哉，与我周旋。","人不我欢，我亦天全。"]},{"t":"古诗二首 其二","f":"古风","c":["戚戚图终古，终古不私戴。","枯树泣秋风，秋风不少爱。","优哉游哉，时其不再。","与世推移，观生进退。"]},{"t":"八章 其一 朱矶","f":"古风","c":["湖沙漠漠，非人所乐。","坤德相愁，呼山出脚。","土石开夷，牛羊可托。","一二樵渔，鸠群聚息。","蒙谷飞泉，云光洒落。","朝夕油油，自我布濩。","字以朱矶，宝兹民瘼。"]},{"t":"八章 其二 星墩","f":"古风","c":["飞金逐玉，爰失其足。","澹澹冥湖，逝肯来浴。","在水在天，日光共瞩。","曷不乘浮，畏彼槎触。"]},{"t":"八章 其四 虾蟆石","f":"古风","c":["视水临形，审志却停。","鱼龙迷惑，风雨冥冥。","千年坐立，不顽不灵。"]},{"t":"八章 其五 大姑鞋","f":"古风","c":["我闻在昔，随刊日迈。","不胈不毛，维禹亦惫。","爰有明神，阴从协劢。","既位江湖，无远弗届。","弃屦中流，防风却拜。","定履千年，今人曰篑。","吁嗟今人，少见多怪。"]},{"t":"八章 其六 石钟","f":"古风","c":["动静相持，元声以时。","微风击拊，迭奏争奇。","和之一之，乐其可知。","高山漠漠，流水瀰瀰。"]},{"t":"八章 其七 小姑钗","f":"古风","c":["矻矻中阿，独立无颇。","出水峨峨，其仪孔多。","追嗣流光，以琢以磨。","容被草木，鬒发斜拖。","皇皇翠碧，离陆相和。","胡帝胡天，此山此河。","人亦有言，姑钗则那。","虽则姑钗，未可婆娑。","匪春不黛，匪秋不波。","匪云不艳，匪雨不酡。","行朝行暮，亦莫敢过。"]},{"t":"八章 其八 马当山","f":"楚辞体","c":["湖软江雄，追飞自东。","天龙下制，岁久难同。","因思马力，俾山立功。","锡形汗潴，秋骊春骢。","饮之满腹，策之驱风。","羁络烟水，吸吐蜺虹。","千里伏枥，万载行空。","维江与汉，会势其中。","崩腾迅激，将为马穷。","吁嗟马兮，惟力之冯。","既食人禄，遑恤我躬。","吁嗟马兮，惟力之终。"]},{"t":"八月四章","f":"楚辞体","c":["八月秋风，在河在嵩。","我思之人，天中水中。","之人未从，我心忡忡。","彼何人兮，秋其可同。","秋风既清，苇秀绩成。","我思之人，如裳如缨。","缁衣未迎，授衣有惊。","岂曰无衣，与女同籯。","秋风既肃，壶断枣剥。","我思之人，如胸如腹。","之人未谷，逝敢谋独。","岂曰无谋，惟心惟目。","秋风吹兮，秋日微兮。","苍苍蒹葭，白露肥兮。","我心伤悲，旦夕飞兮。","蒹葭在水，秋未违兮。","伊人在水，秋未归兮。"]},{"t":"鹿鸣三章","f":"古风","c":["呦呦鹿鸣，天中有声。","诸宾百执，以及群英。","君子之吉，其光孔明。","人之好我，示我邦桢。","成人小子，誉髦斯平。","邦桢既获，我将我迎。","载玄载黄，篚筐是盛。","威仪百出，雅什三赓。","礼乐相食，诗章有名。","伐鼓坎坎，酒满歌行。","鼓瑟吹笙，至于卒成。","鹿鸣呦呦，天中有游。","芃芃棫朴，有乔有樛。","未见君子，载沉载浮。","苍苍在水，及彼葭秋。","凄凄露白，浥彼河洲。","刍荛遗之，君子求之。","薄言伐之，薄言揫之。","渒彼方舟，洄之游之。","载于王国，薪之槱之。","惟薪惟槱，君子之求。","君子有酒，嘉宾是酬。","呦呦鸣鹿，天中有族。","多士跄跄，诸宾穆穆。","凡我君子，并受王福。","载命而来，求人以复。","厥初求人，时维造育。","百年维树，三载维畜。","山川授灵，鬼神告牍。","自外及中，罔不夜夙。","有德成人，匪余敢独。","人之好我，旨酒甘蓄。","多士诸宾，暨其有禄。"]},{"t":"言旋","f":"古风","c":["征车言旋，黄花在馆。","天末一兄，同羁相暖。","闻问人文，及途安坦。","陈杯发颜，深宵尘散。"]},{"t":"家谋","f":"古风","c":["既劳王役，徐定家谋。","翼翼归燕，望南语秋。","萧萧征马，遇云衔愁。","延目南云，庶及春舟。"]},{"t":"寒菊四章","f":"古风","c":["凄葭一方，寒菊相俟。","何以酬兹，晨阶夕几。","欣慨其间，心目依倚。","未敢从人，重觞泛此。","人之初筵，浮英宜咥。","人之载号，幽性宜疾。","人亦有言，斯维隐逸。","独立秋风，斑斑文质。","我爱陶潜，菊之胜友。","饥坐东篱，无钱得酒。","白衣不来，金英堪糗。","高怀逸咨，相彰益寿。","岂其高怀，惟陶之辙。","岂其逸恣，惟菊之悦。","寄情则然，实爱秋洁。","载寒载阳，孤梅来雪。"]},{"t":"世心","f":"古风","c":["无怀时远，世心日波。","怀山襄岛，万石嵚峨。","相济胡少，相溺胡多。","诗云深浅，易象冯河。","我生天末，如江有沱。","手无舟揖，若巨川何。","庶思考槃，于涧于阿。","乐兹渊止，枕漱而歌。"]},{"t":"众口","f":"古风","c":["结绳时远，众口喁噞。","载声于腕，墨深管铦。","陷文不顾，甘谀乐疢，讳疾忘砭。","谁能响迩，或恐扬燖。","宜彼金人，铭背三缄。"]},{"t":"追昔","f":"古风","c":["嗛嗛为膏，亦愧颐朵。","戋戋微名，亦劳轗轲。","追昔念为，历世真左。","谓影如形，望人于我。","茫茫众生，不皆祝蠃。","参差岐途，毫釐福祸。","时密性疏，道迂行惰。","异气同居，焉不受簸。","屈志交游，姑获面可。","譬彼方舟，未知楫柁。","问讯风波，安救覆坠。","永言念兹，惕然中火。"]},{"t":"勖今","f":"古风","c":["外物欣己，亦念吾庐。","徂春及冬，庭扉自如。","栖无风雨，出亦马车。","见华则悦，先贤戒子。","战胜何日，逝敢踌躇。","既观天与，复溯人初。","繇路居宅，孰为毁誉。","功崇惟积，业坠惟疏。","其日其月，岁不我徐。","谁能壮老，独费居诸。","幸甚勖今，勉足澄馀。","无怠无偷，仅不生虚。"]},{"t":"汉谣四首 其一","f":"古风","c":["祖龙璧归，秦鹿奔棘。","沐猴锦衣，楚骓泣北。","吁嗟赤蛇，居马上得。"]},{"t":"汉谣四首 其二","f":"古风","c":["采龙既成，生彘可食。","沟鸿反飞，江乌队翊。","吁嗟兔死，不令狗匿。"]},{"t":"汉谣四首 其三","f":"古风","c":["商山四鸿，同哺雉鷇。","姁翼既成，彘首宜秃。","吁嗟鸩杯，反令雏哭。"]},{"t":"汉谣四首 其四","f":"古风","c":["雉则彘人，煇耳剔目。","大则崇王，橶腋反触。","吁嗟苍龙，久据梦腹。"]},{"t":"追和张曲江感遇诗步韵四首 其一","f":"五言律诗","c":["俨若先贤对，悠然江夜清。","故因流水意，忽动高山情。","乡国垂光气，史籍熠玄精。","素怀私淑志，抚此尚愚诚。"]},{"t":"追和张曲江感遇诗步韵四首 其二","f":"五言古诗","c":["美人宅遐方，未繇承恩顾。","常忧颜色衰，时将萱草树。","自沐君王宠，翻深入宫惧。","矧复炫好修，能无群小恶。","所以琴瑟欢，千古欣相慕。"]},{"t":"追和张曲江感遇诗步韵四首 其三","f":"五言古诗","c":["立贤贵无方，以方贤不得。","谁识岭南英，皇图赖羽翼。","风度唐独推，文学今无色。","五百馀岁间，巍然二斗极。","如余生非远，胡为空太息。"]},{"t":"追和张曲江感遇诗步韵四首 其四","f":"五言古诗","c":["大鹏飞九万，鹪鹩巢一枝。","所以古名世，发愤视其为。","矧兹壮行日，云何不信斯。","龙见先试跃，位立求可知。","审此后先一，宁悲南北岐。"]},{"t":"尚古六首 其一 屈同姓","f":"五言古诗","c":["三闾楚同姓，去楚将焉趋。","女媭何婵媛，申申日以呼。","长沙同调客，亦曰夫子辜。","百年恻井食，当日忍糟餔。","岂无婉娩术，溘死不忍徒。","哀哉将为类，陶陶遂永徂。","宁愿身后人，怀怀代相图。"]},{"t":"尚古六首 其二 贾少年","f":"五言古诗","c":["雒阳年少人，立谈长太息。","天子议公卿，诸老逊英识。","更定不少宽，绛灌驱之亟。","有君如汉文，怀才良堪恻。","当年稍优游，大臣可浸潗。","后之君子曰，将以此为术。","娩默槃崇高，养錞百无失。"]},{"t":"尚古六首 其三 供奉靴彭泽带","f":"五言律诗","c":["供奉殿上靴，能驱力士辱。","彭泽腰间带，不为督邮束。","拂衣归去来，时异神相瞩。","高风邈何存，青莲与黄菊。"]},{"t":"尚古六首 其四 柳下女子卿妇","f":"五言古诗","c":["柳下坐怀夜，子卿操节时。","谁明邻女事，翻多胡妇疑。","至人坚白处，其中良可思。","三黜不恭态，非女孰相知。","万死一生日，非妇孰相持。","千年心迹见，女烈妇犹奇。"]},{"t":"尚古六首 四公子不可一观 其五","f":"五言古诗","c":["强秦方虎视，豕羊关外侯。","当时四公子，无忌独有忧。","相从夷门监，解赵使秦羞。","胜也敢言事，徒以豪举收。","春申土木人，文亦鸡狗流。","局蹐四关道，日为三窟谋。","馀子既碌碌，哀哉魏自掊。","信陵亦甘弃，终于酒色休。"]},{"t":"尚古六首 其六 天下士门下客不可同语","f":"五言律诗","c":["鲁连围城内，何求平原君。","秦将既引却，千金等浮云。","冯驩弹铗罢，一鱼便欣欣。","祇堪营兔窟，鸡狗日为群。"]},{"t":"闻陈集生学士编选粤东诗文赋寄","f":"五言古诗","c":["岭海文在兹，天意求其主。","广渤荡玄波，离奇难一罟。","代有挺出姿，丘梁绝世睹。","而况别岛间，埋没谁能数。","北学渺遐方，才或因地估。","待人激其颓，宗盟孤于缕。","所恃流风存，光运难终腐。","振起关敝衰，不但一吹鼓。","于君勇为承，弱澜横初柱。","缥缈论思馀，乡国新黻黼。","冥搜穆无垠，远近在仰俯。","罔象意中驱，当前照合浦。","巨眼全收今，远胸力驾古。","如铜君为炉，如木君为斧。","鍊锻各成精，从绳咸依矩。","所以列缺鞭，衔灵辉东土。","矧余道左心，多年歌杕杜。","准拟向南溟，千里观鹏怒。","虚步蹑扶摇，因风动翮羽。","与君翔八荒，肯曰巴里取。","及此垂衣朝，文明相咻喣。","大雅有同心，以友或可辅。"]},{"t":"为王季重题读书佳山水","f":"五言古诗","c":["天地本多情，造化氤氲席。","畴窥不测藏，勺水与卷石。","虽分流峙形，繇来同一脉。","逶迤吴越间，幽奇为开辟。","爰有硕人居，友之成三益。","踏破虚空界，乃结清真宅。","玄流洗文心，云岸披图籍。","有邻应不孤，身名复何惜。","长啸三十秋，广漠甘幽适。","偶因出世想，即以凡心谪。","傲睨长安邸，犹然烟霞僻。","但了三千缘，岂因五斗易。","感彼劳生者，怛悴时局蹐。","未离尘嚣好，彼此交为射。","谁能契冥通，动静随所择。","吾欲从之游，地阻神无隔。","缅矣八遐心，山水知远客。","为君赋考槃，持归问岩泽。"]},{"t":"姚孟长学士谬相奖掖感而有言","f":"五言律诗","c":["亦知四海悠，踽踽一身寄。","欣然获所宗，远大而相位。","审余愚也直，知君誉必试。","此意自千秋，藏心曷穷至。"]},{"t":"己巳南归晚舆见初月口占","f":"五言古诗","c":["行行三齐地，归路不辞长。","夕阳低还照，初月飞混茫。","浮峰千丈白，疏林远可望。","天开山气静，云隐野情荒。","凄风空淅淅，不解客子肠。"]},{"t":"东平州途中遇雨复晴","f":"五言古诗","c":["飘风自南发，幌荡云飞扬。","惊沙迷古道，昏冉乱征裳。","殷其山起震，霢霂微雨瀼。","百亩翻麰穗，千篱蔚麻桑。","枫林添暗绿，柳色洒新黄。","行客无乐事，得此濯烦肠。","愿言炎埃静，不辞湿行装。","云何司夏者，反若靳清凉。","吾今在汶上，杲杲日已旸。"]},{"t":"栖白门寄怀方肃之徐九一","f":"五言古诗","c":["泛迹栖吴门，卷情恻秋意。","寂寞空庭风，展我怀朋志。","良朋天一方，孤怀何所似。","眷彼孤栖鸟，日暮失俦类。","敛翼不复飞，疏林独憔悴。","感此集千端，所思不能置。","兴言今日别，回首昔日聚。","偲蔼一堂中，莫逆而相视。","友益既成三，同心更无二。","徐子誇七斗，追琢敦远器。","方髯富五车，巍然植高帜。","如余本庸疏，时亦从旁议。","乃知同道谋，以得断金利。","相望意犹隆，岂但情之毖。","惟期吾党心，共承斯文寄。","君耽白玉堂，我披泉石位。","玉堂生虚清，泉石多幽异。","万里亦比肩，如何怅两地。","旷怀在古今，驰神有寤寐。","毋或金玉尔，好音时相嗣。"]},{"t":"静夜久坐寄宋尔孚辜端敬","f":"五言古诗","c":["夜沉敛客绪，息意冥所思。","皓月时流照，江水清且瀰。","参差檐外影，兴言故人居。","故人今燕北，连镳暂相随。","聚首亦何几，各有民社司。","宋子敦其性，辜君迈厥施。","恢恢皆远器，伯仲可同追。","久探此心一，应知不世移。","世情竞纷纠，慎处乃得宜。","刚柔裁之心，进退观于时。","余亦耽虚白，所砥日孜孜。","相望非近小，贡言多切偲。","孤尚如不失，千秋有共期。"]},{"t":"秋日过维扬朱章华年友泊此未归相逢命酒舟中","f":"五言古诗","c":["已别还疑聚，惊时各意疏。","邗江杯酒夜，秋色月桥初。","诸怀同拨置，归意静相摅。","扁舟远尘杂，雨过新魄舒。","波澄素影落，漏永夜情虚。","欢来君应尽，愁去我犹馀。","未忍轻分手，临流独唏嘘。"]},{"t":"偕王芳洲朱章华二年友同集冒宗起处余以不胜酒力先回","f":"五言古诗","c":["朋情欣远聚，酒意向秋添。","谈锋宾主敌，胜友东南兼。","金风吹绿蚁，颓玉压晶盐。","次公难多酌，童羖易生嫌。","恐贻监史耻，伐德时相砭。"]},{"t":"舟中夜眺","f":"五言古诗","c":["晨风改炎节，宵月绘秋图。","云随风共驶，波与月相驱。","疏树凝暮霭，倒影入澄湖。","流光浮幌荡，空色肃清癯。","乃知秋作气，凄冽出景孤。","望望游氛霁，意展神为俱。","当兹众籁寂，聊复得真吾。"]},{"t":"寄怀李大生","f":"五言古诗","c":["地迩人犹遐，形分神无障。","宿昔恺敦情，伊我同微尚。","杯酒数晨夕，倾沥一披向。","不孤应有邻，进取思直上。","世网岂能羁，俗情何足量。","乐兹气谊真，乃知宇宙旷。","时平欣道泰，官閒密交况。","胡然岐路悲，惊闻阳关唱。","探怀共唏嘘，索居独惆怅。","野分使星临，云飞游子望。","君行春卉萋，我来秋涛壮。","栖栖欲倦游，岁月不相让。","暂息尘嚣驰，聊获形骸放。","秋意适歌啸，江光随莽浪。","溯流淮海间，薄停归帆舫。","伊人水之湄，跂予河犹广。","蒙密启夕氲，怛忉劳远将。","展志驰往篇，缄心询近状。","玄素有同昭，孤抗难独偿。","词竟巳缅衷，魂梦为俱往。"]},{"t":"贵溪舟中阻滞漫成","f":"五言古诗","c":["长途已迷远，此地复相禁。","殷勤贵溪宰，归程巧酌斟。","令我舍周道，转从岐路寻。","我行安仁界，时披竹松林。","松风幽以杳，竹径猗且森。","恍惚开天籁，悠脉起秋心。","多历广闻见，兼可适孤吟。","兹意良复厚，所赐岂不深。"]},{"t":"道中逢雨再成其一","f":"五言古诗","c":["无端解妒雨，弥道布天阴。","长途征衣敝，那堪重湿襟。","岂亦知官冷，相将冷意侵。","相侵何足道，随尔吾难禁。","犹有青山里，空谷喜余音。"]},{"t":"东乡道中","f":"五言古诗","c":["泫淋密三朝，朝朝率西浒。","幽壑染黄精，流尽千山乳。","遥注碧苍上，一吞复一吐。","无空不起云，无地不连雨。","夹林响飕飗，百树皆仰俯。","柳懒浑欲眠，竹醉犹解舞。","倦客易惊心，敝舆招风侮。","目断岭南峰，迷离莫可数。","情知日月慆，可奈雨风拒。","空馀夙夜心，瞻望陟屺岵。"]},{"t":"春日山居即事十首 其一","f":"五言律诗","c":["山居犹然昨，岭外亦能春。","梅魂侵瘦骨，繁虑积时新。","晓睡非贪梦，驰逐恐伤神。","多少关情事，为付眼前因。"]},{"t":"春日山居即事十首 其二","f":"五言律诗","c":["一自游燕倦，尘风日月征。","炎凉怪经眼，寒温解撄情。","已知鼠腹俭，胡然蜗角争。","慎兹藏朴素，巧拙非所衡。"]},{"t":"春日山居即事十首 其三","f":"五言律诗","c":["少小骨成傲，既壮不能迁。","神取千秋达，气收天下贤。","已惭多羁系，况忍学周旋。","智非山膏下，胡为自寇煎。"]},{"t":"春日山居即事十首 其四","f":"五言律诗","c":["所少素心侣，索居意转长。","独爱雪堂客，千秋生气翔。","掀髯浮霄汉，俯视尘土行。","吾欲从之游，故为俗子量。"]},{"t":"春日山居即事十首 其五","f":"五言律诗","c":["前贤曾提耳，邀我游太冥。","日休与日拙，孰醉而孰醒。","苦认魂为梦，咸迷影即形。","曷不观空色，虚缄冲漠扃。"]},{"t":"春日山居即事十首 其六","f":"五言律诗","c":["纷纷尝我者，其中败几层。","一事微欺性，百为总皆崩。","周官慎伪载，大易戒羞承。","所以渊明子，不复较斗升。"]},{"t":"春日山居即事十首 其七","f":"五言律诗","c":["只今图幽适，贞怀勉绳操。","窈室环流水，清漱有馀陶。","仰观太空静，始觉浮云劳。","阅世敢云久，聊复纵翔翱。"]},{"t":"春日山居即事十首 其八","f":"五言律诗","c":["独与清宵对，水木向余深。","孤窗横汉色，环树密云林。","有怀徒耿耿，泫然一沾襟。","此生百年事，何甘岁时侵。"]},{"t":"春日山居即事十首 其九","f":"五言律诗","c":["潇然大宇内，孤认海为家。","烂熳悲身世，劳生谁作涯。","惟有清夜息，远发赤城霞。","影滞神终往，披肝揽月华。"]},{"t":"春日山居即事十首 其十","f":"五言律诗","c":["焚心多琐屑，难破是情悭。","还顾恋恋处，名根不可删。","何堪世缘杂，况值天步艰。","未了丈夫局，终愧老香山。"]},{"t":"送谢韶石廉宪北上","f":"五言古诗","c":["吁嗟民散久，教戎始惟君。","四骐飞紫雾，五岭动氤氲。","呼吸移星斗，啸诧起风云。","千山扫岚色，远海静波文。","既振秋风肃，还煦春泽芸。","我归自东土，身历信所闻。","久怀勤仰止，乍喜挹清芬。","识荆虽私好，借寇有同殷。","其如帝心在，沙漠伫奇勋。","行矣播英烈，壮志我平分。","出处应可共，肝胆有馀欣。","岂徒歌汉广，凄断楚关曛。"]},{"t":"送冯尔韬明府报最","f":"五言古诗","c":["惟别见交情，而今以貌标。","古人意中期，伊何外所矫。","少小怀素心，壮游独踽佻。","肝胆乍披君，此义日相皦。","审君悉愚诚，微尚无弗昭。","恺沐仁风驰，应惭莫之佋。","逐寇扫千妖，赈饥生万殍。","凡此持两端，口碑人意表。","余也日追随，鲜敢非公扰。","言笑借诗文，酣呼穆清醥。","有时共唏嘘，忧时同悄悄。","每忆雨风夕，连吟促鸡晓。","俄然成此别，缅绪曷能藐。","此别况复秋，祖道寒烟绕。","霓骖遂莫攀，日与帝乡绕。","颜色榕江留，归梦湖心杳。","征云逐长安，皇路日缥缈。","行矣慎纶经，勋节咸兹肇。","赠君徒以言，羞为今人眺。","空馀千古心，离月今宵皎。"]},{"t":"送吴斯椒明府报最","f":"五言古诗","c":["世辙久称劳，斯人为共挽。","所赖素心朋，同与驱重远。","投分审关缘，交君遂云晚。","盟性入千秋，惟君司其键。","还忆燕都游，须眉淡复婉。","一自宰吾乡，清风日以焜。","时闻单父琴，邻邦尚宛宛。","独笑懒如余，咫尺艰往返。","盈盈水中央，莫能一朝噂。","不恃形骸略，几于肝胆遁。","乃当报政期，欲别缅中悃。","行矣逐霜车，咨谋告君本。","明知举最后，东平劝思阮。","眷恋故人情，因之沥所恳。","相期匪躬故，祖道歌蹇蹇。"]},{"t":"追用刘司马阁试诗韵","f":"五言古诗","c":["不因胡儿骄，何人思颇牧。","烈士守寸丹，肝胆肯庸碌。","许国亦无多，刚肠不任束。","慨然请长缨，矢以忠怀逐。","宛转泪挥军，须臾脑涂足。","一朝酬主恩，四海环相哭。","月自玉关悠，风向剑门谡。","为照不磨心，还吹未瞑目。","男儿志裹尸，安能死岩谷。"]},{"t":"秋去有感","f":"五言古诗","c":["隐几知所萌，观生视此息。","因兹昼夜情，惭彼菌蛄识。","上古有春秋，今人日老洫。","笃时兴众哀，闻籁感诸惑。","吹万虽不同，错行安可极。","眼前今古消，身外暑寒织。","惜阴徒有怀，回天苦无力。","空馀往日悲，时乎不再得。"]},{"t":"咏望月禁“光芒、明皎、清辉、华皓、晶瑩、洁白、朗耀、照临、圆满”等字","f":"五言古诗","c":["瑶宫太阴元，启镜当天门。","大地呈诸象，星辰落素痕。","初出情犹敛，映日如浑浑。","须臾飞碧艳，舒心遍乾坤。","妆成锦霞拥，魄动彩云翻。","因风若有语，对人寂无言。","溶溶此宵永，娟娟万古存。","素质原不染，浮翳岂能昏。","未解趋炎态，偏惟濯秋魂。","应知怜孤客，而我不敢论。"]},{"t":"寒雁","f":"五言古诗","c":["夕氲穷天蔽，寒雁纵声高。","肃阵恐风乱，喈喈觅其曹。","闻汝伊何适，飘疾复咿嘈。","岂同岁暮悲，寥唳共呼号。","回翔若语我，閒愁不相捞。","天地同化尽，岁月自徂滔。","云外无缯缴，空中远尘嚣。","严霜可濯羽，飞霞可泽毛。","但使性能悦，胡为心独劳。","翛然辞我去，恍惚声闻皋。","感此俯而思，诸怀悉屏韬。","始知天渊内，飞跃有馀豪。","劳生人自戚，忘机物自陶。","何日乘风举，广漠恣翔翱。"]},{"t":"鸠","f":"五言古诗","c":["漫以鸠得名，僝功于何表。","居巢既拙疏，鸣逝终佻巧。","倖沐阳春恩，馀粒恣朝饱。","意满邀千禽，怪呼乱夕晓。","无端向余舟，哑哑梦中揽。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其一 抱玉","f":"五言古诗","c":["抱玉自南来，弭节旋捐玦。","扰扰竟何成，理弱媒终拙。","喔咿不可为，突梯性所劣。","迟暮固堪忧，竞进仍非屑。","徒兴岐路悲，急还穷途辙。","执戟亦以疲，不如独关闭。","哀哉楚山愚，涕尽继之血。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其二 遇巷","f":"五言古诗","c":["遇巷竟何术，鸣嘤未有声。","捷径非我道，户说不可行。","杂糅世应久，姱好宁与争。","纷纷懘葪者，细故非所惊。","览初终莫悔，前修既已盟。","万里日来反，游泛亦余情。","还忆乘槎处，留石问君平。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其三 摽梅","f":"五言古诗","c":["冉冉遂春三，悽然摽梅七。","怀此霜雪情，壹志依阳日。","固芳亦有年，圆果始昭质。","每陋桃李颜，妖艳为世匹。","得真惟有松，可师独称橘。","同依南国生，受命本于一。","胡甘调鼎资，置彼倾筐实。","缅矣缭中情，求兹果何吉。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其四 孤松","f":"五言古诗","c":["我徂及隆冬，挺矗一孤松。","今归春晼晚，百卉竞芳容。","断肠桃李花，处处伤心逢。","缤菲宁不艳，零落早相从。","凯风催菡萏，秋水欲芙蓉。","时物纷相逼，驰莽竟何终。","悠悠来永叹，含情向谁封。","终羡后凋质，偃蜷出寒峰。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其五 游昆","f":"五言古诗","c":["将游昆瑶圃，紫海暂周旋。","泥水误污素，涤浣向虞渊。","朝发方及夕，倚闾忽经年。","念此心怆恻，华池未可前。","长揖诸仙众，归卧白云边。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其六 从策","f":"五言古诗","c":["时从詹尹策，龟短谢不能。","中宵日耿耿，百虑几环膺。","终难鸡鹜竞，欣依黄鹄腾。","一举纡曲尽，再睹圜方徵。","翻然忽自哂，反顾得其恒。","定志惟兹履，顺常岂无朋。","鞿羁亦何悔，乐此不为惩。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其七 幽兰","f":"五言古诗","c":["高帆曳云霄，悠悠万里目。","春情落逝川，惊湍一何速。","叠嶂郁莽榛，幽兰闭窈谷。","本为明王生，萎芜坐春覆。","春风杳莫攀，香馨为谁馥。","感此泪沾衣，沿芳一相匊。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其八 长剑","f":"五言古诗","c":["长剑倚天外，汗漫碧云屏。","时逢六月息，海运徙南溟。","邀我扶摇往，濯拭向清泠。","仙人驱羽驾，左右夹明星。","拂扬观且叹，解佩勒丹铭。","回语朱颜女，素手匣金铏。","下寰惊电雪，光质慎为扃。","稽首传至诀，韬锋入紫冥。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其九 几先","f":"五言古诗","c":["顿网不招龙，振网不招凤。","二灵失几先，将与蚁鹜弄。","神物贵卷舒，缩潜固其用。","千仞既飘飘，九渊或可共。","非古观化人，孰能洗心从。"]},{"t":"庚午冬虏儆烽传溯流金陵约同假曹方姚陈诸子北上俱以散馆尚遥深居念独行不可于辛未春遵洄而南而家扁舟不能自聊作纪怀诗十首 其十 远游","f":"五言古诗","c":["大隐逊滑雄，远游悲时迫。","东北乃迷从，下上日蹁躄。","天阍启阖阊，问予欲何适。","自陈粗浊资，埃棼故营魄。","轻举乍离群，御风期上策。","帝遣丰隆先，云乘纷驰蓦。","旷历旬始都，遍揖诸仙客。","仙客齐相询，下土今焉宅。","噫嘻品庶同，事事不异昔。","已贵弗思贵，人役俱耻役。","所忧踽凉独，行行俱诘詻。","稽首祈真言，长跽请丹册。","粲然宝诀传，曰道不可迹。","漠漠休而魂，至清不汝格。","闻命忽形忘，壹气神巳辟。","驷虬征无上，总辔览靡隙。","逍遥泰始中，何者能吾易。"]},{"t":"江伯问答","f":"古风","c":["来帆千影乱，扁舟一缆孤。","极目烟波阻，飒飒怯微躯。","投词致终风，终风莫我?。","倦客愁回首，静与江伯图。","客本岭外至，生平绝援扶。","闻子贞独往，相从入帝都。","云何不努力，阳侯忽改趋。","蛟龙迷海道，鱼鳖肆陂湖。","亦甘我迟钝，反令彼揶揄。","江伯浩长叹，鼓涛哂客愚。","人自巧拙异，天岂南北殊。","拙者安澜守，巧者挟风驱。","余亦万里流，朝宗不厌迂。","今古同兹辙，百折未少懦。","相彼飘飘者，激聒自号呼。","跨驰虽竞捷，泥沙或须臾。","顷刻天开霁，何处置眉须。","吾自行吾法，仍复得真吾。","眼前迟速事，窅焉入有无。","客能永言斯，贞此俟前途。","悠然行无事，澄心与客俱。"]},{"t":"泊南康观放水灯","f":"五言古诗","c":["湖天同疋练，澄色远相串。","孤城倚山巅，倒影于斯见。","扁舟晚泊之，夜眺生孤羡。","雨馀暮微烟，风恬波无溅。","须臾荡浮辉，隐映分流转。","艳拟百花红，妆为玉镜传。","又如晚日霞，馀彩云中变。","远望复纷纷，忽疑星片片。","飞芒碧空际，来往天河穿。","久坐起沉吟，身未浮槎践。","依尔一叶中，胡乃眼前眩。","因念春光至，抑亦湖得先。","万点簇新华，交与水天绚。","喜杀诸童奚，聚喧俱忘倦。","齐言进香人，水灯施湖面。","掀髯一推窗，索然无复恋。"]},{"t":"池州阻风二首 其一","f":"五言古诗","c":["长江连远海，万里易生风。","扁舟三十日，旬时九相逢。","击楫徒兴感，溯流安可从。","吴云漠咫尺，凭凭且难通。","极目燕天北，杳矣碧霄同。","浮槎何日至，搔首问苍穹。"]},{"t":"池州阻风二首 其二","f":"五言古诗","c":["天风九万里，直下大江东。","海波十千丈，倒流蓬壶宫。","长鲸翻白屋，挟此远生雄。","鬐鬣蒸云雾，怪怒起蛟龙。","巨鳌惊缩首，恍惚三山帆。","而况扁舟者，绵力欲与冯。","箜篌不堪听，痴杀渡河翁。"]},{"t":"铜陵阻风二首 其一","f":"五言古诗","c":["东风何谑敖，白日不能柔。","阳乌失驻足，庵忽欲西流。","迥车莫可挂，应使六龙羞。","龙羞引蛟泣，浩荡一江忧。","泪涌洪波出，涕涟白沤浮。","倦客敢言事，同兴万古愁。"]},{"t":"铜陵阻风二首 其二","f":"五言古诗","c":["晓风自东发，吹折扶桑樛。","六龙未及载，一叶飘中流。","横江不可受，洪澜为之勾。","赫光淩万顷，淜湃激扁舟。","我欲裹粮上，苦为江伯留。","此物夸然大，匏落无所收。","海若御风至，闻言笑不休。","连呼巨鳌出，戴往天池浮。"]},{"t":"望积雪漫怀二首 其一","f":"五言古诗","c":["昨夜东风嚇，江花浮皓魄。","晨越披衣眺，回飙荡扫辟。","周道不可见，独馀寒山积。","幽涧冽孤清，碧峰澹虚莫。","艳质远尘纷，冰心聊自惜。","岂不向朱门，庭多车马迹。","泥泞滓素贞，驱除难假借。","所以守深藏，独往辞炎赫。","终当随阳春，飞洒玉阶白。","一点下殿衣，明王欣瑞泽。"]},{"t":"望积雪漫怀二首 其二","f":"五言古诗","c":["春山积素姿，飘渺云峰凸。","近攀末繇阶，远望何清冽。","本同雨露需，若与烟霞结。","高处相六寰，凛为不可涅。","回观阛阓中，累累咸销灭。","当其亲华筵，歌舞竞相悦。","无奈炎烟飞，中道成弃诀。","惟兹所托宜，赖以全孤洁。","有似素心人，无取虚名窃。","蝉蜕尘世表，澹荡独关闭。"]},{"t":"姚永言自维扬至过访","f":"五言古诗","c":["思远环千愫，陡晤复茫然。","离情缅初聚，历乱向春先。","年来馀兹刻，此会良艰缘。","厌作寒温讯，同时肝胆前。","缕覼仍增黯，心难遽口宣。","为期竟日绪，檐雨促君旋。"]},{"t":"次日访永言于报恩寺中呼酒谈诗","f":"五言古诗","c":["良朋驱言驾，敢自怯舆风。","柳絮循郊色，先以慰别悰。","远落市嚣外，曰君古寺东。","入门君适出，盆花为客供。","久坐需之至，须眉跃相从。","呼酒三杯后，诗篇百首同。","翠竹生禅籁，文心于焉穷。","忙能探兹候，始信志所公。","繇来肝共沥，只此亦无封。","悠然俟晚磬，缅绪觉难终。","抵舍严更寂，黯默别为衷。"]},{"t":"崩岸","f":"五言古诗","c":["崩岸怯随波，惊涛日就涌。","所居远其安，千年劳奔汹。","绿草亦何辜，漂流频接踵。","沓浪竞突吞，难恃春风宠。","披靡蹙洄舠，短樯慄以悚。","寸进从弱丝，迟迟相立拱。","递来不一形，化变于焉总。","中有至理存，鬼神不敢奉。","博厚深地力，于兹觇厥勇。","变乃得其常，不泄先不壅。","聚散漠无端，通气为任重。","微分广大情，位此当倥偬。","是亦坎坤门，示我于静动。"]},{"t":"初生月","f":"五言古诗","c":["月于江易清，光习与流喜。","矧兹混初生，万象瑩其始。","窈魄散微痕，丹霞摄之起。","晢晢众煌星，分辉如其使。","苍山亦助情，隐黛环积水。","传意睆长干，近远各无滓。","轻华到平沙，宛转碧波倚。","以风引下上，淼茫从所指。","冰魂若有借，微明斯焉瀰。","于微探空色，明固不任侈。","静夜落诸喧，四虚归一视。","樯影次以收，澹澹水天止。"]},{"t":"月落","f":"五言古诗","c":["月薄不自持，逶迤欲西蹀。","泓流蓄轻辉，魄则远山箧。","千峰递收形，馀霞变云鬣。","柔风自东来，还吹春树叶。","青烟发空茫，翛然一江接。","当此众情虚，恰与素心怗。","望望作玄观，众妙落千楫。","天汉肃以高，微痕摇波摺。"]},{"t":"枕上过彭泽起视则惊涛过颡舟与江下上矣","f":"五言古诗","c":["江知我欲去，寄情为我徵。","风知舟欲速，噫气为舟凭。","不以风搏江，谁与江力輘。","不以舟御风，安极舟任胜。","江风不肯降，舟故勇为承。","中有游泛客，一叶恣奔崩。","云天合空碧，危涛欲上凭。","千山纷如蹶，银屋蔽叠层。","势吞小姑入，马当不敢应。","隐跃长鲸舞，呼吸百川腾。","舟人俱造次，奚奴颠沛仍。","雅宜谢公量，啸歌不改恒。","犹作苏子字，舍笔别无能。","情居夷险外，波沸心自澄。","万里丈夫浪，一楫巨川乘。","天之示我者，怒流为益增。","眷彼扶摇翮，九万正翻淩。","胡甘耳目陋，不及鲲与鹏。","去去南溟近，渤海待余兴。","追轶临峤作，四友未许矜。"]},{"t":"因读谢李过湖之作不觉怃然","f":"五言古诗","c":["李生思羽化，谢公秘精魂。","哀哉复今昔，此意竟难存。","眷彼空波照，宛转自天门。","临流诸青嶂，含情各无言。","无言或至理，其中不可论。","溟滓方包括，此亦一微痕。","而况蜉蝣者，闻见恣嚣烦。","游览增永慨，风雅亦帨繁。","奈何七尺躯，欲以下上扪。","置置勿复道，宴坐随夜昏。","湖宽月堪贮，山閒云自根。","一楫破空濛，已觉此位尊。","湖山随去去，云月终我奔。"]},{"t":"月行","f":"五言古诗","c":["晴霞分瞑色，馀彩曳千桅。","清波濯明沙，皓月正徘徊。","风轻帆力倦，篙从绿水开。","月光随篙碎，零乱雪山梅。","忘却子猷棹，山阴访戴来。"]},{"t":"对渔者","f":"五言律诗","c":["施罛不得鱼，明月罛中走。","对月不得酒，扁舟月中守。","恼乱月中人，相从渔者偶。","子归结网来，我将谋诸妇。"]},{"t":"明月五更船","f":"五言律诗","c":["桃华三月水，明月五更船。","迟缆丝晨照，衔山未忍还。","近岸幽扉对，绿林闭晓烟。","流莺枝上语，无端出可怜。"]},{"t":"中夜声色","f":"五言律诗","c":["回合依山树，舒迟来水风。","山断云能续，水去月无终。","蛙鸣隔岸野，狗吠密林中。","渔舟夜不系，随流跃明空。"]},{"t":"晚泊与山对卧","f":"五言律诗","c":["急濑转迟涡，乱山容独泊。","唧啾动岭深，熠熠施树薄。","衾抱夜流奔，梦从山鬼谑。","不知西月低，斜照胸中落。"]},{"t":"雨后望山上白云","f":"五言古诗","c":["雨过山自容，白云于焉助。","明没秘中峰，引入青冥去。","玉女窥窗下，隐隐驷虬御。","蜷局碧苍间，清风时飞翥。","窈谷恣周流，幽泉翛察著。","岩灵驰缤纷，俛仰环所居。","登览未许同，娭光微相觑。","绵杳挹素华，烟颜坐以除。"]},{"t":"阴眺","f":"五言律诗","c":["天意微欲落，山情漠与参。","繁云低岫白，青霭入溪蓝。","漾楫幽峰麓，波翻绿影涵。","窈森别有界，委蛇纵所探。"]},{"t":"襟风","f":"五言律诗","c":["阴生风有候，徐徐分远山。","春情驱之出，天籁不可关。","参差千树叶，晻霭百云弯。","但望神已怿，披襟况洗颜。"]},{"t":"从凉","f":"五言律诗","c":["求凉从晚得，气以慕春柔。","濯嚣谁为政，催诗别有邮。","浴风宜童冠，枕漱随石流。","归思激长啸，响发碧溪浏。"]},{"t":"渔樵","f":"五言古诗","c":["水活施众濊，川动束薪流。","樵人斤斧舍，渔人罩汕周。","及兹方涣涣，合沓竞所抔。","恼乱渔人语，此利固渔收。","陂泽从有畔，云何出位谋。","樵者还相谓，于子本无掊。","山林莫余爱，子亦缘木求。","微闻斯言辨，永叹淳风偷。","滔滔天地内，纷总何胶尤。","垄登不足道，俎越亦忘羞。","空悲伐檀者，置彼河干休。"]},{"t":"过皂口舟为巨石顶碎赖前舟回救得脱诗以纪厄","f":"五言古诗","c":["水意分下上，故以诸滩级。","积雨巨其澜，错石伏波蛰。","千叶溯蹶奔，参差介于粒。","泱若动我前，方与奇观揖。","造次生怪呼，飞湍顶舟立。","百篙难一施，循循如有絷。","惊视激流侵，汹涌足中入。","礧礧巨石胶，以舟作之笠。","舟人竞愕眩，传号去舟急。","漂零借一刀，危魂聊粗翕。","三叹此洄从，艰险何多集。","岂为破釜沉，抑师下水袭。","浩浩发长歌，羞作儿女歙。","恐惧吾所甘，愁闻舟子泣。"]},{"t":"过赣关","f":"五言古诗","c":["夹峦奔百川，岩壑欹相釱。","萦盘趁舟来，此地微豁泰。","水乡裾麓阴，山城襟流濑。","长桥闭两关，千桅凑一带。","商贾自乐公，滴涓轮汪濊。","远方沐宽仁，朝家明无外。","禦暴别有心，区区宁计会。","相彼形势冲，四藩此为最。","祇今潢池兵，纠纷绿林旆。","比年图扑灭，兵威未全赖。","井邑岁萧条，狂奴时狡狯。","守土空瞿瞿，居行同永慨。","余亦远游人，局蹐如之奈。","极目舟车途，肠断岭云霭。"]},{"t":"梦醒","f":"五言古诗","c":["倦愁生百睡，懒散付扁舲。","肱枕浮云意，几嘘槁木形。","晚凉徐起望，瞑色已前汀。","落照递还碧，远山次敛青。","无数啼鸟乱，一带幽花零。","没尽永昼日，梦游乍遣醒。"]},{"t":"深睡","f":"五言古诗","c":["雨来深睡添，风过激涛泻。","无计遣程悠，只此销愁惹。","北窗未有期，扁舟聊焉且。","欹枕恣流中，鼓腹随康野。","青山结善邻，云霄庇广厦。","寤寐矢弗谖，昼夜真不舍。","劳生叹奔驰，兹缘良艰假。","时从一体变，方知万事扯。","恍惚妙玄门，于徐饶至冶。","种种百年尘，于斯归砾瓦。","一卧破三春，安知春欲夏。","日月尚非忧，而况浮云者。","所求思为无，先觉心欲寡。","千代羲皇上，百代蒙漆下。","漠漠许神交，栩栩一臂把。","葛天有遗民，惟我或是也。"]},{"t":"舟倦连日得诸山周旋晚泊斯隈口占二十韵酬之","f":"五言古诗","c":["千山不肯豁，环谷锁微烟。","况经久隘雨，正此暮春天。","积叠分流壑，我舟从之沿。","中央一明镜，左右双翠钿。","前抱疑无路，转襟别泻川。","递来互伸缩，奔往欲蹁跹。","未甘洄波漏，犹借石根连。","翻惧汹涛齧，驱彼莽榛编。","笼树施缭绕，沉霭合迍邅。","稍稍通微径，孤村倚麓偏。","牧樵时踯躅，惊起白云眠。","持筐饶野妇，结伴接山巅。","长嫂勤采采，掇捋幽峰前。","小姑嫚嬉戏，羞客掩林边。","薄暮各归去，无人鸟初还。","睍睆竞音好，颉颃并羽翾。","芳草终有怨，閒花谁复怜。","缘溪正堪数，渐泊亦为缘。","无情交如此，莫逆心或然。","识面从兹日，相对忆今年。"]},{"t":"自汀州下小刀溯流","f":"五言古诗","c":["一舟较掌宽，掀翻付濑速。","盈雨溢浩滩，竞涛漏深谷。","俯瞰蟠石根，直串嵌岩麓。","颡过在山行，气转厚坤轴。","怒峡霹雷生，舞壑潜蛟肃。","前有锁浪峰，上有号涧木。","喷薄吹片苇，交会来顷倏。","巨垒惊象瞿，平沙乱鱼腹。","委宛飞流梭，贯穿经崖岫。","短楫捷有神，长年暗理舳。","右左割巃嵷，谈笑开纠蓼。","接瞬历纡盘，聚峦齐莽逐。","卧对疑胸浮，起坐怪踵蹴。","沓来遇袖襟，涌去奔心目。","不知急澜凭，但觉往舟伏。","旦昏几何时，千山破含蓄。","朝暾下辉波，晚霞碎沉碌。","错认银河天，前川挂布瀑。","俯仰滔没中，渺哉天地粟。","造物若相驱，为我省烦促。"]},{"t":"游松光岩得斝字","f":"五言古诗","c":["携手入青山，输情凭绿斝。","自赧酒肠轻，浩落因友藉。","松岩旧所耽，趁此暮春暇。","参差迷岫云，近远纷相迓。","朝雨蓄微泉，石湿未全泻。","屐齿滑苔痕，扪萝微可借。","攀扶向石床，指点从僧舍。","步驰杂啸歌，清赏谁能罢。","兴言今古殊，仰俯倏焉乍。","童冠沂雩中，少长崇山下。","所欣情事如，肯认风光亚。","成诗问几人，归咏各无差。","主有未尽欢，余曰未卜夜。","浩然千载思，留兹一刻价。","收拾春宵馀，持以返造化。"]},{"t":"寄怀方肃之","f":"五言古诗","c":["家本青山旁，白云守孤尚。","清时容懒疏，自甘形骸放。","云何轻故山，烽火来虏状。","翘首拊髀思，忧心随荡漾。","击楫溯中流，风烟传涤荡。","欣闻一怒安，俯惭万里浪。","驰针遍所亲，进退依君访。","君方闭户深，驱车莫与伉。","已阻弹冠情，翻惊捷足谤。","家园喜无关，沿洄轻扁舫。","鸥玩复经年，鸿来闰冬望。","新诗溢毫芒，夙盟坚腑脏。","岭梅想劳思，江月悠以怆。","两地出谷心，一天清梦偿。","不畏功名迟，但惜居诸旷。","生逢舜禹君，致身谁能让。","刍荛意可资，葵藿性不忘。","还叹岭海踪，引援无他长。","冷局人赘疣，有怀终肮脏。","赖子声名蜚，雁行推倜傥。","棱棱重词宗，染翰首为唱。","转睫计秋风，遥遥冰雪壮。","预期先尺书，因之沥所向。","屈指聚欢时，郁陶一舒畅。"]},{"t":"是早发鲟鱼苦雨三叹","f":"五言古诗","c":["萧凄昏旦彻，羁魂习无吪。","明发桡声动，望眼出支沱。","东风吹日气，闪忽下江波。","挂席循风意，欹危逐流颇。","转盻空矇接，朝晖或有罗。","舟入云中去，人疑天上过。","青山四俯仰，绿岸两蹉跎。","山花不自繇，宛转醉颜傞。","岸草澌纷下，鼓浪赴奔涡。","而我扁舟者，对之黯怀多。","因念春事足，霏霏意若何。","冱寒伤豆麦，不但客情磨。","客情为霮䨴，邈邈想春和。","淋漓春易伏，还惊节序梭。","飞扬从极浦，浩荡自为歌。","恐复嗔江伯，题诗不敢呵。"]},{"t":"过彭泽口号","f":"五言律诗","c":["苍茫鼓泽口，陶公今在么。","解带三朝事，清风万古多。","我来空怀曩，归去词可歌。","长叹流洄客，七载五相过。"]},{"t":"三十日立夏","f":"五言古诗","c":["春力不夏胜，夏力不春淩。","荐夏于天后，与春遂同升。","馀此一日位，授受何绳绳。","得序悠然退，自奉反无凭。","所立将为嗣，责卸非其称。","相彼朱明质，宣严日以承。","遂使氤氲泽，转见解阜能。","成兹作讹职，而得东南朋。","长物者夏功，于春本无矜。","得人者春德，于夏亦无增。","平开任让局，不第水火乘。","时情怀知己，真如有待兴。","迈往虽冲赫，炎光不遽蒸。","竭代终何见，乍从永昼徵。","长羸效厥司，南薰日腾腾。","始信转候力，俄遣惊时膺。","错行视兹节，感变获其恒。"]},{"t":"宿州道中微雨望前山行云","f":"五言古诗","c":["竟日断青山，云根于何植。","弥空绝飞云，雨意于何测。","旷野落平荒，纵有难遽识。","情炎拂夏威，遂与征途逼。","怀此周道阴，翻怪山情匿。","晨驱宿途中，忽动前山色。","合沓萃冥苍，行岫俄先得。","凉薰反其吹，霢霂旋飞北。","飘闪下日晖，光尘次以克。","坐使烟颜除，旦昏收爽息。","百里分近遥，迷茫昏黛即。","始信肤寸功，卓哉孤嶂力。","奇峰何足誇，君看垂天翼。"]},{"t":"过细柳营","f":"五言古诗","c":["柳弱阵则坚，军容见诸此。","转令弱者坚，将略因可视。","孙武鼓妇人，水火咸可使。","淮阴将多多，还能驱背水。","治军亦何常，一风拂柳耳。","俄作步伐观，所向必齐止。","俄作临敌思，所前必披靡。","令寂闻行声，进退随麾指。","宛彼大块吹，枯荣肃以起。","云雷动其驰，一气奔远迩。","所重心力同，不但军礼始。","军礼传于今，谁非介胄拟。","权贵慑其心，何必誇天子。","风鹤预闻声，全壁安足恃。","卓哉坚卧人，当年别有以。","试观棘灞中，纷纷儿戏是。"]},{"t":"滁州道中吊古 甲戌使荆藩之作","f":"五言古诗","c":["客路如寻幽，晓夕苍山下。","出没原岫间，景物时堪写。","纵瞩遂忘疲，阴容忽中洒。","历历眼前峰，奔青下绿野。","俯视但淼茫，墟里孤烟寡。","日暮禽鸟喧，归飞乱揪槚。","临风怀昔贤，羁情易因惹。","当日旧亭台，孰为主宾假。","冈陵有变迁，况于览胜者。","浮沉千古事，客泪难多泻。","自顾远游身，悠悠驱我马。","祇忆醉翁言，环滁皆山也。"]},{"t":"满拟既望至楚蕲日为南薰所苦因呼月临江望云语山皆不我顾也对影歌谣凄然述之","f":"五言古诗","c":["去帆争疾鸟，来缆似疲驽。","飘风何谑浪，日与滞舟俱。","明月自东来，诉风向月呼。","月骄不语客，停照拂江隅。","江流赴海急，翻挟南薰趋。","回首玄峰北，长叫促云驱。","云倦不风敌，中发尚踌躇。","独献青山色，偃蹇绘幽图。","云山既无素，江月复非徒。","持此百羁身，一苇自揶揄。","痴来欲问影，愁倦不知吾。","每向清宵半，人静我依舻。","吴峰空目断，楚水入看无。","不畏归途阻，但惜时光徂。","秋声乍夜出，近远落悲梧。","望望伤魂处，历乱汉川菰。"]},{"t":"舟暮对秋山有感","f":"五言古诗","c":["清溪含素秋，荡漾令人愁。","如何碧山色，萧条对此流。","霜叶飞斜照，疏烟萦晚洲。","坐对兰馨远，兼叹桂枝樛。","沿芳空有怨，攀援未能留。","伤心榛棘满，丛薄共回揫。","虽分苍与翠，莽没非所求。","日暮不自聊，蟪蛄鸣啾啾。"]},{"t":"春雨如膏乃过多反不见其可喜竟日闭户相守不敢憎也而诗以商之","f":"五言古诗","c":["青阳开动初，膏雨发荣继。","光含品象熙，润及根荄细。","晨夕满盈馀，濊泽翻疑滞。","沉烟挟戾阴，春软遂莫制。","过泄滋物心，未知息时计。","易竞草木情，节令同摇曳。","淫溢东风颜，汩没随人世。","舞鸟轻落花，残芳积幽砌。","清溪泻碧苔，奔潮无静势。","独有闭关人，守足怯涂泥。","览察冥所思，闻见纷相逝。"]},{"t":"汀山车中却寄汪皖公明府","f":"五言古诗","c":["里公必谀令，毋论贤否伦。","谀言不从心，有识所不珍。","当事责名誉，舆歌杂赝真。","五岭南天外，吏治总声循。","潮广复千里，于揭尤海滨。","今之为都者，谁可甘朴淳。","频年山海孽，欲尽蚩蚩民。","皮肉供兵火，沟壑半吟呻。","嗟哉刍牧少，翻令司牧嗔。","十里闻蟪蛄，千家见鹄鹑。","不谓六月霜，忽动九重春。","吁帝哀茕独，得公果仁人。","视伤疮痏日，思艰共苦辛。","抚摩足元气，藏喻一恕身。","及兹多故日，方知静者神。","休然至治理，简默所繇臻。","邑亦遂无事，今昔可具陈。","而我于役竣，适公下车晨。","七月观风草，心口各有因。","即今王程步，饥渴动征轮。","回首岐峰北，弦歌想日新。","眷言还相勖，庶以慰情亲。"]},{"t":"溯流夏月日值江风皆北舟滞有述","f":"五言古诗","c":["来帆竞千叶，奔涛纵反翩。","扁舟争一缆，积岸令周旋。","细察流洄理，迟速未宜然。","或曰因水性，不如假风权。","繇来观望者，谁可少机缘。","于子信独往，何从涉利川。","顾余亦中省，频岁习波烟。","海运观九万，考时非后先。","宁知解愠日，而得其凉天。","玄冥司夏月，南薰遂莫专。","漫叹淹留客，偶逢时令迁。","平生多亟失，只此亦邅延。","物数苟如斯，敢不益贞坚。"]},{"t":"舟夜弹琴","f":"五言古诗","c":["舟宿寄幽林，难了清夜心。","冥神外喧寂，发我静中音。","遂然林月开，灭烛令光临。","沉徽作细响，轻风助微吟。","曲罢归烟水，浦溆各凄深。"]},{"t":"孟夏湖舟晓望追和张曲江彭蠡湖上作","f":"五言古诗","c":["清晨观湖理，洪流何泱泆。","中望合遥烟，就光惟晓日。","汇纳百川情，溟泓得休逸。","连势没诸山，坐见蒙泉一。","行云觅故居，从澜无定术。","独许匡庐峰，配临千仞出。","高广盖相宜，渊天可微悉。","传语众丘陵，波涛各共恤。"]},{"t":"世道","f":"五言古诗","c":["世道人所为，深思劳一己。","今及古往来，智与愚终始。","湍湍心性源，情欲日就滓。","混沌既波漩，旦下江河水。","反古生今世，习好皆骳骫。","今智恶其凿，今愚则诈尔。","相笑复相哀，前后空相指。","纷纷逐世群，决流东西使。","代有救世贤，不过汪波砥。","莫诧采薇高，莫嗤叩角鄙。","未分终古忧，何以殊彼此。","所叹往者人，滔滔悲皆是。","复念后者人，汩汩将安止。","介身处其中，孤行何足恃。","内省独深思，思心曷能已。"]},{"t":"民风","f":"五言古诗","c":["中天而疆理，一道惟省方。","区土而习俗，群生必异乡。","悠悠天地情，上下日旁皇。","类气一以殊，渺如阴与阳。","华夷分厚薄，边腹亦低昂。","东西日出入，南北风柔刚。","天乃示民别，地因遂物长。","山川不相及，闻见各相妨。","凭私因怙执，伐异至胥戕。","郁郁牵文物，戛戛赴戈铓。","治忽介眉睫，千古共痍疮。","孜孜造化心，代乃降惟皇。","不惜一人勤，以作万邦望。","劳劳分燥湿，勉勉别井疆。","光天及海表，风动日休扬。","大哉君子德，吹万乃无旁。","云何叔季日，扰扰民与王。","偃草终何术，雌雄各自强。","吁嗟虞夏没，念此空茫茫。"]},{"t":"时运","f":"五言古诗","c":["日月既迁人，人自为今昔。","漠漠千古悲，忽向微躬责。","抱情游八方，岁时无暖席。","朝折若木枝，暮总扶桑策。","上下六龙车，低徊白驹隙。","置身浮云上，时世终相掷。","苟无维挽权，驱驰亦何益。","夙闻达者言，人生天地客。","所贵道弗违，毋使情多格。","稚老若循环，阴阳可交泽。","和神春夏门，敛气秋冬宅。","推忧还终古，冥澹守精魄。"]},{"t":"我怀","f":"五言古诗","c":["忆昔小学岁，涉猎经史通。","垂髫应茂选，总角饩庠宫。","矢志天人策，称心词赋雄。","弱冠登贤籍，春秋动云风。","自知方幼学，欣获窥秘中。","罄折披良友，卓荦向群公。","孜孜明今古，矻矻考污隆。","忽忘身贫贱，谓可致微躬。","藜灯空六载，宣室渺宸枫。","一朝辞砖影，香署日匆匆。","不悲声名闇，方惊夙夜衷。","伊余闻在昔，趋时道不同。","离群应见异，迷宠自当穷。","深怀进退谷，恃此寸心冯。","逢人虽局蹐，省志自冲融。","所求惟反鹄，谁敢复书空。","忽念铅刀割，还收折臂功。","谅生明盛日，庶不重昏终。"]},{"t":"感物","f":"五言古诗","c":["有鸟自南来，情质与众殊。","毛羽心矜贵，栖啄意閒都。","众鸟笑其异，去之令之孤。","蒿目层霄上，欣随黄鹄徂。","中道黑云蔽，黄鹄不之俱。","零落长风下，窜伏依泥涂。","回视归巢燕，恋主色敷腴。","微观鸠鸴态，决起竞揶揄。","延颈致鸠燕，自处诚区区。","雄鸡昔断尾，冀以全微躯。","鸾凤生今世，苞彩尚可虞。","闻弦虽欲坠，铩羽未全输。","幸脱人机蔚，敢辞已交瘏。","戢飞今自敛，独立旧难扶。","终思云外鹄，偶忆水中凫。","不碍鹍鹏翼，鹍鹏莫怒呼。","不争鸡鹜食，鸡鹜莫交瘉。","纷纷枳棘内，矢怀绝觊觎。","观时愧不早，翔集幸终图。"]},{"t":"秋日燕邸咏怀十诗各系以题 其一 思古","f":"五言古诗","c":["乙亥岁云秋，京华节奔走。","习静思古人，渐觉诸缘丑。","扰扰学名争，一事无能取。","持此食衣馀，何禆智与寿。","耳目本聪明，俗心自尘垢。","而有憧憧交，旦昼驱之走。","托权于世人，强身其左右。","世情相爱少，抱拙况非友。","不忖一物孤，犹云命不受。","尝观鼓物情，其初宁薄厚。","濡动责雨风，栽倾固不偶。","所以古至人，道力深所有。","贵我答天心，天亦为先后。","至今读其书，居然性灵久。","及兹未远涂，前修作内守。","今人亦不争，古人亦不朽。"]},{"t":"秋日燕邸咏怀十诗各系以题 其二 称心","f":"五言古诗","c":["怀抱未能深，招摇犹在眼。","荣辱相因依，喜怒亦无限。","任其淩轹情，矜人皤与睅。","何关寂寞羞，毋乃盛雄赧。","称心而思之，不如俱削刬。","掩迹仍塞涂，日向诸缘简。","非以自欣愉，亦求稀竦戁。","老吃畏事言，君子传瑟僩。","三复古人箴，斯理良堪撰。"]},{"t":"秋日燕邸咏怀十诗各系以题 其三 闭门","f":"五言古诗","c":["心迹两无营，独坐何萧散。","门外少高车，清晨容栉盥。","徐徐正冠襟，缓步宜孤馆。","虽然束带稀，秋风戒裼袒。","閒人亦有课，吾性本多懒。","草玄友杨雄，运甓师陶侃。","禽鸟来空庭，时复为恳款。","空庭出层霄，随意烟云满。","置身清寂中，人世谁长短。","于我求达生，梯荣当立断。","万事难并欢，昔闻今岂诞。","闭门远风波，世道能坦坦。"]},{"t":"秋日燕邸咏怀十诗各系以题 其四 卜邻","f":"五言古诗","c":["泉石辍初游，京华复偃蹇。","故人减畴昔，相聚倍缱绻。","旅居易卜邻，言谈庶不远。","咫尺通寝兴，披衣互相饭。","所言惟丘壑，一志嘉肥遁。","将结故山庐，白首终往返。","乐此素心人，欣欣日可晚。"]},{"t":"秋日燕邸咏怀十诗各系以题 其五 云日","f":"五言古诗","c":["虚室有閒阶，云日相深浅。","推棂受光浮，倚榻注景转。","极兹瞬息情，节序互迎饯。","默默感商飔，群动俱相勉。","百草畏芳移，诸禽欣毛毨。","我亦时物中，未为天地选。","浮生欲三十，千虑难一展。","樽酒与瓶粟，费世虽不腆。","明明古今事，已让诸人践。","盈卷积玄文，虚言何足办。","屈伸大块间，如蚕方在茧。","经纶不自繇，胸丝日几辫。"]},{"t":"秋日燕邸咏怀十诗各系以题 其六 兰蕙","f":"五言古诗","c":["兰蕙感秋风，馀芳人所采。","蔓草不择时，日劳盈车载。","分其贵贱姿，不为爱憎改。","草木妒兰生，兰因惧草浼。","滋锄失其宜，空谷徒相待。","独坐有幽人，起对孤情倍。","日暮叹芳微，千载琴歌在。"]},{"t":"秋日燕邸咏怀十诗各系以题 其七 观蚁","f":"五言古诗","c":["吾观蚁微物，其智有足称。","出穴缘阶级，戢戢后先升。","分馀互友告，取道不长胜。","世人遗其善，竞以逐膻憎。","宋子虽救厄，知己归隰朋。","悠悠念群动，大小俱可徵。","云鸟时微灭，野马日凭淩。","即事求端绪，无为费目凝。"]},{"t":"秋日燕邸咏怀十诗各系以题 其八 观凤","f":"五言古诗","c":["吾观凤览德，所至待时鸣。","高冈向杰出，梧竹合其清。","能言不枭竞，独立洁孤情。","世人图易得，鲜复希哕声。","所以深苞彩，夷然葆至精。","繇来千仞表，下鸟谁能争。"]},{"t":"秋日燕邸咏怀十诗各系以题 其九 晓叹","f":"五言古诗","c":["所思亦难尽，及晓叹何深。","无根而愁种，飘然乃秋心。","微凉生虚牖，一叶下危襟。","云风俱不息，凄响落浮阴。","庭树先为感，萧瑟渐千林。","以兹荣瘁理，动我今古吟。","四时相摇落，一室比登临。","怀人芳草怨，招隐桂丛寻。","何繇悲气遣，古愁不生今。"]},{"t":"秋日燕邸咏怀十诗各系以题 其十 元化","f":"五言古诗","c":["元化亦多年，圣愚相介佋。","天地未及区，冯生交杂嬲。","不有持运人，愦愦失昏晓。","万欲雕至精，一事谁能了。","羲皇遂巳徂，虞夏遂已邈。","治忽不关民，所关民寿夭。","大乱蛮夷猾，次则奸贼扰。","春秋称近古，荆戎亦纷缭。","千年汉及宋，纯化未全肇。","其馀闰统分，寄权皆浅少。","君雄相啖食，异类居中矫。","风云无气色，江河同滔淼。","大哉开天主，方将日月皎。","历历数乾坤，独此圣功表。","绳绳及今日，咸若偕鱼鸟。","纤鳞仰波馀，弱翮随飙杪。","寤寐慰升沉，歌风庶可绍。"]},{"t":"首夏","f":"五言古诗","c":["晨夕习幽栖，首夏变云物。","幽栖历见闻，云物有伸屈。","芳草尚春馀，光烟遗髣髴。","移榻就前窗，预待凉薰欻。","愉悦通昔怀，世心难相怫。","高卧见羲皇，曲肱睨簪绂。","兴言千载人，一室何沕沕。","圣逸虽不同，所乐同披拂。","庶几斯乐存，时开终古郁。"]},{"t":"喜伯兄至都","f":"五言古诗","c":["羁心积午睡，梦言有咨嗟。","忽惊童仆语，乃谓长兄车。","披衣及庭户，迎面拂风沙。","巳闻平安悉，徐讯川陆遐。","陈杯发远颜，安榻向馀花。","馀花来舞鸟，交交答棣华。","物情欢同气，和悦似相加。","忘疲重昏饭，容膝共为家。","虽非故园聚，暂此慰天涯。"]},{"t":"苦夏移寓东粤别馆庭木颇森剪繁引荫","f":"五言古诗","c":["浮栖忘择荫，长夏始相侵。","惭愧幽蓬性，频岁失园林。","倾心营一枝，解此颜与襟。","眷彼枌榆馆，庭宇乃萧森。","环阶苔色映，当牖竹光临。","尘暑堪微远，市嚣亦少沉。","羁情易为惬，徘徊遂与耽。","剪莱安客座，援柳加檐阴。","即事因奴力，苟忘称旅心。","所怀聊为美，歌啸已清深。","何以酬斯夕，星轩发静琴。"]},{"t":"开卷有述","f":"五言古诗","c":["上古有作圣，中古有述贤。","于穆含真秘，倾储责传宣。","恭惟作述者，恐惧尚维玄。","有智不敢爱，有言不敢偏。","圣劳贤已瘁，大小互相鞭。","怀挟今昔意，日思造物权。","旁皇求后死，叹息付简编。","简编及秦火，神奇出遗烟。","区区诸老生，记诵亦可怜。","吁嗟千馀载，光运乃当前。","伏惟我生晚，谁能愚自专。","是以繇窥管，求之我生先。","遵涂独好古，与物共尊天。","怀哉天与古，相从日喟然。"]},{"t":"良乡道中","f":"五言古诗","c":["涩路如披棘，停车自咡嚅。","王事趣之去，原隰一征夫。","途光荒夕照，所见但飞鸟。","飞鸟鸣不已，客意愈踌躇。","秣马昏林下，孤村半有无。","啼獋攀前辙，奔狼迫后驱。","呼仆环刀剑，弓衣学短襦。","自顾非行伍，束身似全诬。","特以居行少，无人道我迂。","私闻童仆语，作此诚区区。","本为观文往，何乃武容粗。","无多剑与矢，缓急安可需。","汝辈安知此，我意岂全躯。","先生威天下，新制重矢弧。","积叠三军众，存名亦执殳。","将求缓急用，于此未全殊。","今古戈矛客，请率以癯儒。","慎旃无复道，寄身在远途。"]},{"t":"拟勤王","f":"五言古诗","c":["戎衣试长短，战马问瘦肥。","朝驰羽檄至，暮拂剑光飞。","恭承明主诏，行伍有光辉。","亲随十千众，性命总相依。","怀恩俱不浅，报国敢从违。","挥戈从此去，所向必重围。","矢心坚士气，先发锐兵机。","一鼓清郊野，百战绝奴归。","群酋纷狼藉，抱鞍泣落晖。","立使胡气尽，大展庙堂威。","功成与诸将，终令识名希。"]},{"t":"拟安边","f":"五言古诗","c":["汉武开西南，宋高弃东北。","或以强衅边，或以弱丑国。","合商今古筹，无如屯守得。","三时壁野清，千里燧燐织。","耕战不相违，兵农各自食。","近远输粟行，休暇治军实。","但令士卒心，尝如胡马逼。","虏伏无可窥，虏进安可弋。","或明师帅权，或尽守土职。","犁扫非无术，未贵杀伤克。","天子不自将，小丑亦亡匿。","安攘信何奇，朝阃共心力。"]},{"t":"拟灭虏","f":"五言古诗","c":["生平叹沟壑，梦寐倚疆场。","读书羞宋史，异代计胡亡。","长犁思塞北，尺组待名王。","一朝专阃寄，十万许横行。","策马凶门出，挥旌大漠傍。","晓传飞将入，密指战追方。","胡骑本风雨，其技弓矢长。","结束防驰突，分合杀其强。","时将土克水，忽如日荡霜。","呼吸生奇正，指挥出变尝。","朝夕更貔虎，庭穴尽犬羊。","执讯归廊庙，悬竿示羯羌。","所矜非杀戮，雪志在凶残。","乘我国家运，重贻百代光。"]},{"t":"延津道中望太行","f":"五言古诗","c":["出门见太行，峰峦无终已。","征途作游情，置身如万里。","晓寂岩岫閒，心清林木倚。","所未历其巅，云霞出意底。","因有色声迎，悠然感目耳。","山灵愿幽人，相对非无以。","忘言可竟日，欲暮凉风起。"]},{"t":"淇县晓发","f":"五言古诗","c":["月在征车发，秋深但叶飞。","白云山际出，孤光上客衣。","敛袖来清影，近远未相违。","辞郭郊情旷，寻烟古道微。","林疏迎露薄，草却避霜威。","悬知草木意，有待必朝晞。","未及东方旭，苍茫斗晓晖。","物情欣始得，所见尽依依。","夙夜何人者，瞿瞿久渴饥。","感物矜时节，翻憎耳目机。"]},{"t":"中元夕郑扶烟年盟见访治酌命琴谈一二物外事既别扶烟以诗至步韵率答","f":"五言古诗","c":["三载停诗事，君至发琴言。","酌酒迟君语，明月自东轩。","庭空秋影落，烟液渐无存。","沦阴霄气入，初露濯黄昏。","伊我同孤尚，此际可微论。","谈心一友足，虚劳满座樽。"]},{"t":"东溪小筑循城东而结门门虽设而常关也","f":"五言古诗","c":["结构依城邑，木石难幽閒。","故使心地远，毋为车马攀。","所谓伊人在，溯流霜露间。","逶迤玩回转，列植倚潺湲。","羃翠开庭户，抽烟出市阛。","未及楼台位，上下挕水山。","云泉相启阖，薜萝若在颜。","不足外人道，萧然独闭关。"]},{"t":"门以内溪为之界不可不桥桥加以亭岐山隐现眺望宜焉","f":"五言古诗","c":["一溪初入处，白云补空明。","中有丘壑性，烟霞忽已盈。","佳期如可骋，筑室水中迎。","荷盖依木末，桃津隔世程。","远望来荒忽，馀心出杜蘅。","索胜思前步，贪幽聊止情。","孺歌呼小听，客笑待三成。","料理古人意，临流百虑清。","滴沥风林响，还依晚涧萦。","退寻川上理，何必远畦瀛。"]},{"t":"未及桥之左有径绕焉列棉十馀株杂以新卉幽者寻之楼台之致出矣","f":"五言古诗","c":["闭关灭闻见，三径自凄深。","翛然成独往，日涉处孤心。","或有性情友，风味共栖寻。","见山遂遥叹，岩壑乃相临。","灵秀非关远，潜幽出故林。","咫尺存真寄，同异任苔岑。"]},{"t":"枕流为楼隔水尽林阴也林尽而睥睨出过此则千树森然翠烟靡届矣","f":"五言古诗","c":["虚牖凭高发，下有碧溪承。","临深非所意，枕流获古称。","每当潮势长，安处若舟乘。","清景移昏旦，波光视升恒。","映此疏林美，蕴色浑凝冰。","倏忽传空翠，近远碧烟层。","春心宜映发，秋容转骄矜。","请看云物际，旷怀必可兴。"]},{"t":"楼之外为台黄岐当其右紫陌环其左致有爽气则西颢居前也","f":"五言古诗","c":["与楼相下上，并立而矜秋。","岐陌如环拱，岩烟则远投。","自非飞鸟翼，孰与云光酬。","云光飘暮色，独对乃悠悠。","市嚣虽不染，缅绪已难收。","何意登眺处，各有古今愁。","临风望不极，明月倚东浮。","清景来人世，初晖自我楼。","既照火魂久，方开物象幽。","百际俱以寂，前思讵可留。"]},{"t":"楼台之下有室盖主人挟图籍与居之所也","f":"五言古诗","c":["至哉虚白位，朴素此中居。","蓄积终古事，顾慕以诗书。","图箓供幽讨，心理同卷舒。","庶几寝食益，杳杳性情馀。","有时泯省想，嗒丧抑天嘘。","起对夕阳末，行吟见星初。","永怀不可既，于此亦何如。"]},{"t":"室之外为堂堂不能不客故宽广依制","f":"五言古诗","c":["一枝才知止，大厦亦居安。","虽同燕雀意，自许硕人宽。","寡营疏礼法，即事戒哗欢。","欲倒门前屣，思妨座上冠。","所求披衣者，鲜令主眉攒。","戏谑无拘士，伛偻避达官。","庶以将迎废，相依弦酒欢。","虚牖来閒旷，清墀任盘桓。","人生歌啸地，慎作高明观。"]},{"t":"堂乃有庭盆花次第循阶墀而布列以愉宾朋以媚幽独也","f":"五言古诗","c":["云日流光处，相与命为庭。","疏翳存佳卉，怀幽结草亭。","群菲虽并列，兰蕙独依棂。","光风时一转，怀抱入芳馨。","虚泛循阶立，心迹两俱冥。"]},{"t":"其中有园园无定所林木所居之地则名之","f":"五言古诗","c":["顷者欲卜筑，恐妨云树稠。","缘溪花药处，清影碧波流。","故林何苍郁，新卉助深幽。","秋叶护黄落，春枝作艳柔。","雨馀烟翠滴，潮满绿芳浮。","水木互交气，鱼鸟亦相求。","晨昏肆愉悦，光风为我留。"]},{"t":"楼之右有古棉木独挺立而秀出主人爱其不群为其筑池蓄水以居之","f":"五言古诗","c":["嘉木号水棉，秀出何翩翩。","连柯霄汉表，托根惟清泉。","结色无冬春，或比后凋年。","邑人爱宜水，环植就蜿蜒。","遂与藩篱等，公然伯仲肩。","岂不怀孤往，独立众所捐。","而我卜林塘，于此乃深怜。","凿牖通嘘咈，筑流护幽妍。","要使扶疏质，今能雨露全。","方池虽无广，千载益贞坚。"]},{"t":"颜延之五君咏不列山王予谓钻李子可黜也人伦之鉴何玷酒圣哉诗以补之","f":"五言律诗","c":["山公日启事，未废酣啸时。","流品分清浊，以酒圣贤之。","饮醇俱闭口，通识若分眉。","潇潇竹林子，物外表深知。"]},{"t":"督闽学辞朝","f":"五言古诗","c":["遂辞金马阙，远向钓龙台。","拜稽重俯伏，自叹臣不才。","谬入承明席，未逢宣室开。","放逐从郎署，隐忍受驽骀。","淟颜称司属，率意忘疑猜。","簿书虽琐屑，礼乐尚恢恢。","在公念寅直，退食屡徘徊。","庶补微臣过，依稀万国来。","釐剔蒙皇奖，痴劳不自哀。","所信惟官守，何知有仕媒。","十载长安道，鲜睹侯门儓。","但羞楚艾服，岂惜汉薪堆。","祇今承简册，往作铸人锤。","如臣谋已拙，于人何所裁。","以兹久怵惕，兼怀别帝陔。","耿耿孤丹矢，从此日钦哉。"]},{"t":"繇万安上滩赖风力日有半遂至赣州","f":"古风","c":["千山何磈礧，万水难冰涣。","水山俱不息，急濑喧昏旦。","清浅五云波，淩临因石悍。","遂使章贡开，嵚崎从漫漶。","渺哉一苇心，寸尺相衡捍。","弱缆溯奔湍，孤怀就历乱。","岂意北来风，能转南山矸。","芳麓俄沉浮，哀壑倏穿贯。","接瞬几何时，坐失诸滩半。","逶迤出轻?，沿渚回低岸。","川光上巉壁，云影下幽澜。","滩流次第安，客愁因以散。"]},{"t":"老农叹 有引","f":"七言古诗","c":["道旁老农植杖歔，向人欲语气踌躇。","自言胼胝三十载，频岁家无担石储。","旧时八口依耒耜，男田女馌列编闾。","十年兵火无耕地，几处村烟失故居。","幼儿弃去长充役，徵徭备糗刻难徐。","独留零丁乾骨髓，忍死犹恋旧犁锄。","去冬将牛贷邻种，春来代畜勉终畬。","酒肉三时无童饷，黍鸡昨夜接来胥。","已知新税当黾急，更道前逋不少纾。","晨兴疾步驱前陌，计亩输公粒无馀。","自怜筋力今疲竭，将来片土究为墟。","闻说九重哀蔀屋，胡然三尺重徵糈。","又传明诏多蠲恤，云何督责今如初。","以兹吞声仍久立，含酸一讯北来车。"]},{"t":"三三偕伴游松光岩得簇字","f":"七言古诗","c":["料理春事复三三，急趁春游偕五六。","迟春无计溯流从，春流汩将逝者趣。","极目青山四望浮，遮莫其中春意蔟。","以意为游何如身，提携诸伴于焉逐。","陇途迂折微雨沾，行履欹危迟且局。","迤逦平原荒草铺，青茵纵步驱前麓。","醉竹频从衣裾牵，落花谁怜屐齿蹴。","盘涡转侧见山僧，指点松岩来相告。","佛台隐跃巨灵开，兰若依稀山鬼筑。","日气遥临窈洞分，林烟深锁环径属。","山灵知我幽兴多，叠嶂笼阴方昼覆。","朝雨留丝曳苔痕，晚泉落响鸣虚谷。","仰俯随缘恣欲之，攀梯足倦志为勖。","穷山之致必穷巅，探山之藏必探腹。","远岫飞云忽荡胸，群峰竞秀齐攒目。","凭心俄作岱昆思，此地未许便相局。","反顾犹然如是观，此地有何不可宿。","孤怀迥出已摩霄，五岳丘陵俱伯叔。","眼前位置须阔空，高卑自我非山束。","振衣岂必千仞岗，市纷远处姑免俗。","瑶台偃蹇不亲人，争似故山结缘夙。","孙楚枕次随地宜，苏门啸音千载续。","兰亭褉事今重修，舞雩归咏时方促。","迟暮顿因短景催，浮生半日亦已倏。","延伫皋丘哀众芳，不堪零落及兹速。","搴揽何辞夕朝疲，珍重回车载纷馥。","棠舟兰枻恰与迎，晚棹返映春江绿。","简点销愁旧酒杯，暂借风光痛饮赎。","中流起舞浑难禁，醉客满船助歌数。","兴言兹会良亦艰，灯前摇笔细追录。"]},{"t":"秋日赠诸葛基画民部使出","f":"七言古诗","c":["敢誇三百尽豪英，四海相逢宛弟兄。","自古交情因宦短，于今肝胆赖君明。","君已俨然使星出，我犹依旧一书生。","此日风尘为余熟，此去湖山与君迎。","不堪重唱阳关曲，凄凄数语怅归人。","归人时逐乡关梦，旅客漫将诗句鸣。","西风乍夜绕廊急，霜林应醉黄叶横。","闻说西湖秋更好，聊以兹意送君行。"]},{"t":"除夕同林太常蔡孝廉集民部夏力庸处归来独成","f":"七言古诗","c":["夏君设酒当除夜，相逢总是客同舍。","七千里外得四人，三百六旬尽一斝。","游人莫作岁暮悲，天工此日暂相假。","犹有亲友共呼欢，向须契阔独嗟讶。","愧余当歌不能放，悲余当酒不能下。","绿樽华发两相催，烛光星烂复交射。","久坐共听漏声稀，归来惟有霜风迓。","呼奚独掩小柴扉，寂寥灯前泪参差。"]},{"t":"赠陈子仪中翰使出","f":"七言古诗","c":["朝来燕影向南翔，看君马首亦同方。","与君二载同舍客，漳潮咫尺未殊乡。","不谓离群今日意，忽因黯淡暮春肠。","春肠百结难相赠，凭兹春色送君行。","此去湖山春未尽，扁舟恣意水中央。","千条弱絮诗人料，十里娇红西子妆。","逐日惟邮溪山好，迢迢或恐岁月忘。","未知应接何时暇，但有新篇即贮囊。","陇头春老还相寄，莫待秋风怨阻长。"]},{"t":"赠李大生大行使出","f":"古风","c":["夫駪駪，牡彭彭，骆马啴啴经四方。","嘉君从事多旅力，愧余偃息仍在床。","此去驱驰须尽瘁，好将咨度报明王。","我欲赠君无他语，惟有清梦绕邗浪。","愿得隋堤传好句，时将明月寄愁杨。","更愿一洒邗江水，尽洗纷纷名利场。","此言赠君君自详，此味惟我与君尝。","慎勿轻向他人道，应笑狂夫诗亦狂。"]},{"t":"王嫱故里","f":"七言古诗","c":["柳堤深处明妃里，柳色依然人非是。","当年一曲离宫悲，殊方青冢已垒垒。","天生红颜反为胡，以女宁胡自汉始。","胡儿犹解怜倾城，汉王恩情薄于纸。","春风几度吹愁多，汉恩繇来不足恃。","金屋阿娇终长门，可怜飞燕今已矣。"]},{"t":"三归台","f":"七言古诗","c":["驱车晚过三归台，横山如带云如栽。","峛崺陵曲杂荒苔，阒寂碑文隐不釐。","高岗望望夕氲来，吊古悠然动徘徊。","当年图烈伊谁开，于今村落蔚麰麳。","区区齐地富强推，今古曷云难理财。","兴言神溯天下才，大夫已逝不复回。","犹忆堂阜曾为媒，得君行政何恢恢。","并肩召忽亦可哀，知我鲍叔安在哉。"]},{"t":"十一晚将至崇德阻雨不前","f":"古风","c":["殷其雷，在山之侧，熌烁飞光来自北。","须臾野隘平山迷，淡月疏星不相克。","青林夹道两朦胧，捍索桅竿浑难识。","惟闻雨点起风狂，共惊帆驶一何亟。","舟人颠沛更传呼，疲稿弱缆争无力。","暂依坠岸棘芦丛，咫尺前行莫可得。","敲窗片片如欲入，蜡花引泪残光熄。","雨过犹馀飕飗声，一枕清凉随漏刻。"]},{"t":"十二日泫雨未息风偏舟迟","f":"七言古诗","c":["披衣晨眺秋已极，野意川心俱黯塞。","扶桑倦旭罢朝升，炮车飞布穷天黑。","泫然微雨溅波纹，霢霂穿帘不肯息。","岩谷锁烟弥平原，近山若隐远山匿。","无端南来重飘发，澎湃竞舟欲断纆。","弱缆斜牵奈若何，愁看阴曀日西昃。","吾归至此不计时，默数几与终风值。","岂亦鬼神解相戏，故引长行客心逼。"]},{"t":"曹允大见邀西湖","f":"七言律诗","c":["里湖幽寂外湖泓，山光蒙密水光明。","尔我扁舟湖泛泛，歌舞千场月盈盈。","湖心不管歌舞事，月色能兼尔我情。","情钟我辈自歌乐，淘泻岂必竹丝声。"]},{"t":"西湖公子行有序","f":"古风","c":["百顷湖光无边浩，千年月色无穷皓。","画舟隐跃泛游来，浮光飞艳动洲岛。","歌舞场头公子酣，丝竹行中佳人造。","轻调宛转雪云飞，坐客呶号皆潦倒。","佳人欢容逐谁开，公子逸兴横难扫。","繇来佳人常解欢，繇来公子不知恼。","不有若翁费尽多心图百万，安能博得湖中一声好。","但愿公子百万时贯盈，湖头佳人终不老。"]},{"t":"自龙游登陆至衢州道中","f":"七言古诗","c":["舍棹登途秋逾仲，水意滩声劳远送。","晨起西风拂舆迎，野望霜红逐林生。","出水芙蓉初夭窈，开风松籁鸣孤杳。","到处层峦向人亲，苦恨历历记不真。","迤逦东来若相逐，浮峰或断云能续。","行行惟见与兹深，朝暮谁从觅山心。","欲倩微词通缱绻，识面无缘重偃蹇。","徒将此意寄三秋，三秋问我谓何求。","征夫何求莫遑息，翻似心忧日行国。","长途祇叹往来艰，我家山水久幽閒。"]},{"t":"繇常山至玉山道中行","f":"七言古诗","c":["行行欲尽浙西山，四周峰色尚如环。","但有松声吹绝巘，更馀泉响别人间。","黄岐片席应余待，几度征夫乡梦还。"]},{"t":"过临川见张受先明府共商今古有怀","f":"七言古诗","c":["未信今人非古人，今人视古当更真。","兴来不妨高自位，须知立位先立身。","我亦此身惧靡立，赖君接引方孜伋。","与君性命图初终，宁独气声同呼吸。","祇今吏治疾奔趋，此间不可无君徐。","祇今词苑求卑密，此间不可无余疏。","疏怀久矣独踽踽，是日逢君欣欲舞。","相期兹情力持今，岂曰区区孤尚古。"]},{"t":"刘司马挽歌","f":"七言古诗","c":["喜峰忽起乱胡沙，蓟遵白骨杂如麻。","霜戈踏拥枯杨杪，铁骑横穿宿草芽。","严冬十月方觱发，朔风凛栗倒骝骅。","我师安肯轻暴露，刁斗不闻闻胡笳。","阃外交驰孔炽檄，廷中祇作匪茹芽。","不信干城无纠纠，徒使中逵悲兔罝。","天子赫斯亲授钺，词臣翻入邦政衙。","忠义激人人感泣，挥泪军前众无哗。","四海勤王犹观望，首期身倡遂驱车。","仓卒未遑师干试，须臾独力竟难加。","方寸铁肝终涂地，一代忠臣不暂赊。","英魂零落今何处，气作山河壮朝家。","司马一死寻常事，海外遥闻起恨嗟。"]},{"t":"辛未春溯洄彭蠡晓望漫怀","f":"古风","c":["一枕渡匡庐，湖山夜容舒。","水净霞明清晓望，晔晔紫芝育育鱼。","桃花浪暖三月候，杨柳风前五更馀。","有美一人来踽踽，折柳攀花情半吐。","临流蹀躞倚新妆，一水依依遥数武。","数武终难亲，微衷不可陈。","无缘相邂逅，有意同束薪。","波郎销远魄，青娥蹙素颦。","天台已路阻，武陵孰为津。","念此犹如梦中梦，流声岸色舟相送。","扁舟离人奈若何，波光漠漠馀清弄，胡雁朝飞一湖泓。","鹧鸪晓啼千山雾，胡雁为惊沙朔霜，飘荡河洲倦北翔。","鹧鸪繇来怀南土，焦焦戢羽日思乡。","乡思愁绝不堪见，悽肝摧尽断柔肠。","可奈人归春既老，春老人归程复长。","远游悲俗真何事，小隐东山薄可偿。","长锁寸心依岭海，孤垂两足濯沧浪。","高卧寒岩或起坐，白云随缘相右左。","东壁金松西园花，春草池塘夏秋果。","此地安可无主人，苍生之济不须我。"]},{"t":"投辞","f":"古风","c":["沙濈濈，石粼粼，旦旦沿洄宛在身。","一水合互递赢缩，诸山屈伏渐舒伸。","波流咽声凄劳客，冈峦含意慰游人。","游人事事不异昔，水山到处改芳新。","历乱人间几甲子，销磨此日一冬春。","冬去春来春复暮，落花飞絮交相妒。","莺啼宛转杏催开，雁影蹁跹芦衔渡。","湛湛江流上有枫，偃蹇山幽桂树丛。","冶容年少骝嘶绿，怀春游女步穿红。","行乐犹言飞流电，可怜远客滞征篷。","征篷袅袅真何事，宓妃娀女俱迷自。","两美必合孰为占，导言不固今姑置。","余饰方壮聊浮游，南有乔木未可休。","肠断祇叹西方美，回首徒歌池北流。","谁能念子空懆懆，且复偕我自繇繇。","时当避贤应乐圣，日逢戒心亦居命。","吟卧随缘昏旦资，居诸忘却暑寒迸。","明月邀杯影同人，永昼分眠睡为政。","有时梦入雨云深，不知醉起风雷盛。","三旬一苇恣沉浮，千里万重纷送迎。","已觉长江滚滚辞，缘溪辗转百川差。","夹陵右左回天窄，积石后先划水危。","哀壑夜声多惆怅，黯林晓气半迷离。","迟迟采桑伤少妇，萋萋卉木怨娇鹂。","牛羊既下村烟闭，云水昏森山鬼疑。","自是倦愁生恍惚，时物何心乱客痴。","噫嘻置置勿复道，灯前起舞影相劳。","四千里游未飘蓬，百五日来堪潦倒。","诗篇双袖见闻驱，迩来颇觉窥深造。","囊中一钱留得看，肘后诸方静相告。","此身行止信浮云，周流乎天亦所好。","祇今舍棹始驱车，地近顿宽饥渴躁。","陟彼崔嵬疲仆夫，忽惊霢霂披襟帽。","迷云咫尺袖中生，积雨晨昏驱前导。","萧摵回林醉不醒，崩奔鸣壑纷如倒。","望望犹入最高头，累累建瓴成伏抱。","汀州天上语传呼，潮海水中意可到。","层峰出足起怀舒，远岫交襟凭望扫。","所愁前岭欲移文，投辞急濑烦先报。"]},{"t":"看花饮宋尔孚斋头得脉字","f":"七言古诗","c":["日愁春尽向花索，不谓耽花遂我僻。","明知花在春亦归，多方滋树培春脉。","意中每作俟时思，草零芳秽况同迫。","悲秋有友晓相过，似于春事都有责。","伻来指说载花䑸，溯流宛在浮春壁。","携我披衣一观之，君翻为主我为客。","风摇翠筱众新株，潮湿苍虬数古柏。","正当溪静绿烟沉，移置中庭朱炎赫。","花容懒惰如我疲，贤哉主人急呼白。","春愿以花幸少酬，花情得酒何多获。","三爵浇颜引欢歌，百壶开抱舒愁积。","忘却看花眼如何，此来取醉意应逆。","棋博分曹费黄昏，东城日影欲西掷。","为贪凉暮起襟风，乘兴还从小京宅。","一丘曲折劳跻攀，楼台晚色旷幽莫。","园有盆桃其实垂，中心好之开口格。","踟蹰反步觅所酣，有伴狂奔主不隔。","祇馀子云双鬓皤，主人拉往披韵籍。","为禁狂言恐酌多，閒出新诗细抽绎。","赖有窦外大声呼，裸衣出巡各光脊。","把臂真成醉礼宽，角技齐嫌胜杯窄。","蓬跣飞觞谁绘图，庭树霄轮光潜射。","座中袖手忆何人，依稀认得主者席。","屡次不胜醉场喧，更逃深斋藏小㡩。","我方潜足蓦追随，新来副主复他适。","出门不辞主不知，一天明月印归迹。","看花酒罢携月归，花月与酒成三益。","抵含寻花月下窥，悠然不觉沁心魄。","自怪痴肠惹情憨，肯负风光孤自惜。","叮咛此意寄来春，好留烟景记今夕。"]},{"t":"酒讼用尔孚韵有序","f":"七言古诗","c":["饮醇不谢翻成讼，酒律新添逃主案。","问伴何事必归杨，逃诗姑引逃墨断。","我词未就谁泄伊，伊伴隐情容易看。","不记伴也前作东，狂呼亭尉奔浪漫。","必求金赎十千邀，何须杂署五花判。","北斗擎来挹酒浆，南山可移春水涣。","曩既愁月作归灯，曷不闭月尊中玩。","古人投辖未非师，谁更迫人驱款段。","此言今出谋我深，重来酒债应难散。","准备伶锸入乡园，安能置辩复诋谰。","假饶醉骨未销镕，我愿为金卿为锻。","锻而为器愿为卮，时博酒泉诸公粲。","不然生入复投诗，卿吏何辜空脱腕。"]},{"t":"癸酉北征车中二十日日与尘朝夕也歌以结之","f":"七言古诗","c":["别有氤氲一种吹，胎息于野盛于逵。","阴阳昏晓相割劘，平原广漠任炉锤。","地分驰道天为涯，风拂征旗日助麾。","已遣晴云下碧陲，还招霁霭上高陂。","尔乃为情厌索居，连群呼友向空嬉。","相忘彼已俱谓谁，号召无声会有期。","出入无时乡莫知，行止随程谩速迟。","矫如龙游自委蛇，逸先骏足愁奔追。","远之有望近难窥，动亦何虑静何思。","直前不惧后不疑，荐历严飙势未衰。","掀腾火飙力相持，以游八方莫籓篱。","惟此冲衢盛纷披，造物于渠意有私。","分明遣此令途岐，随缘布置北南帷。","閒情觑彼热中悲，我今矢歌敢索疵。","尘不疲人人自疲，反顾烟颜亦其宜，更欲因之语后骑。"]},{"t":"甲戌奉使荆藩樊山王设舟邀同同使宋今础泛雨湖是日连阴霢霂及登舟而明湖已开霁相迎矣","f":"古风","c":["雨日雨湖游，湖色正宜秋。","乍游觉湖如有素，稍深忘倦遂悠悠。","四顾青松锁幽麓，一望糜芜涌浅流。","细鱼穿荷忽窥客，深藏花下让游舟。","花动香从清涧出，舟行人向碧峰投。","碧峰无数名难识，况逢雨过云林织。","萧萧霜叶结朝烟，细细飞萝连暝色。","青莎白石共离披，水山到处透幽奇。","始知造物多灵秘，耳目未经尽所私。","一勺中含波万顷，九江七泽此间滋。","试问西子湖谁似，千年歌舞空为尔。","楼台近远驾烟霞，花柳春秋乱绿紫。","游人分雅俗，明月愁华烛。","遂使水山情，难穷士女欲。","何如此地一流涡，无限潇湘远意多。","奔溪走壑相回薄，菰蘋掩映自婆娑。","或谓依人中央水，或疑硕人考槃阿。","今日遨游随所见，领略其情未穷变。","岂将位置淩西湖，人生会意当前恋。","漫将彼此费平章，满座踟蹰各有羡。","彼浓新饰艳朱颜，此淡蛾眉呈素面。","身居楚水越溪驰，譬诸有美尽堪思。","主人闻言进客卮，回棹中流动歌吹。","清商一曲入秋辞，白云片片拂风漪。"]},{"t":"过汀岭漫望志感","f":"七言古诗","c":["陟彼高岗望眼直，倚軨四顾山如织。","连空走野入苍冥，东赣西汀青未息。","秋风远逐游人来，朝朝吹入秋山侧。","崭溪崩壑相割劘，万木千林同黯塞。","玉露凋残梧桂枝，白云泛滥烟萝色。","惊心芳树半沉藏，刺眼荆榛方自得。","其中巉绝称隘岭，憭慄初登情孔亟。","嵚岑怪石向人倾，烦挐交丛横马臆。","櫹椮忽动百禽呼，寂寞寒蝉深且默。","低佪转倏欲淫颜，白日荒荒当午匿。","就中秀谷数青松，垂阴曲岫孤特特。","独怜托根官路傍，樵牧无知恣残贼。","斤斧馀痕成瘀伤，令我抚摩泪沾轼。","沉吟此地策疲驱，偃蹇诸峰斜照昃。","薄暮巃嵷山绪黑，山途未可长迷惑。","归去来些故山识，远山悲气孰终极。"]},{"t":"同李唐谷观象台测验回就李寓小酌仍偕往黄可远学士处集饮竟日","f":"七言古诗","c":["明时主意帝心侔，春汉澄霄肃似秋。","太阴躔次忽从蟊，上元晓魄半轮勾。","先期历人按度搜，新法另局绪分抽。","申命礼臣合咨畴，微臣亦向管窥谋。","夙夜惟清观象楼，寅饯纳月尽双眸。","就中分杪各沉浮，过半思维历可修。","归及同官备访诹，摭陈所见达宸旒。","仰称明圣畏天忧，私向贤人乐地遒。","初筵不已遂无邮，对此烟光那可休。","和风穆穆兕觥觓，主客相看瓶罄羞。","忽忆贺监金龟留，春寒何必解鹴裘。","紫宫地远尺寻救，绿蚁香闻对饮驺。","入门高兴发难刘，学士忘形来劝酬。","寸肠缱绻一杯柔，不嫌屡舞溷清幽。","稍出图书佐酒筹，为争彩胜并劳骰。","移樽转席听鸣鸠，明星接瞬下南樛。","李郎自号谪仙俦，长鲸吞吐百川收。","因临嘉树溢黄流，错封藜馆作糟丘。","驱余竹马似船游，飘然不俟我同舟。","温温令主但繇繇，独醒反耻亦堪愁。","千顷汪波忽见投，二难辉映似琳球。","虚怀倾座向生鲰，玄言未了月当头。","起步中庭望月讴，踏歌声调入云飂。","虹桥冷冷浸霓帱，辞君对月意悠悠。","自愧观天识未周，今来卜夜更何求。"]},{"t":"取道临漳见张移孝明府所练乡勇甚称其名而绿野四浮氓妇欢欣各相得也为之留连停车饮其酒竟夕而行","f":"七言古诗","c":["小麦芽青大麦黄，郊无荒草带秋霜。","此地桑麻能此日，此日桑麻见此方。","他方糗备从军旅，此方积敛向仓箱。","他方老稚犹沟壑，此方妇子已圃场。","征车晓过临漳下，踌躇再四依田野。","野外沉云静百阡，就中飞羽鸣千马。","心骇目摇问其因，乃是寓兵于农者。","金鼓相传无事时，狝狩可因农隙假。","今日置兵必农侵，古法何缘复见今。","圣朝方求保障绩，频年空作小康吟。","以民保民惟此术，此术能行君意深。","喜君用意饮君酒，昔见君面今见心。"]},{"t":"秋云行","f":"楚辞体","c":["朝之所思秋云端，暮之所思秋云端。","宿饱思梦秋云散，行衔思往秋云漫。","遂有山风无休歇，吹彻秋云凄且寒。","昨夜枯林泣叶尽，前山寂寞晓霜漙。","云飞激激何山止，秋色萧萧与夜阑。","游子征车逐云过，心如脂辖向秋乾。","不知秋兴谁摇落，长有云心日聚攒。","云心望远归思迫，远望思归秋尚难。","多事前山怨秋老，摆脱飞云下急湍。","湍水洌澌云不止，愿依征辙少盘桓。","如可相依山莫怨，秋今既老客思残。","客思万里秋云下，频年为汝阻千磐。","山兮山兮客思残，所思所思秋云端。"]},{"t":"秋风辞","f":"楚辞体","c":["长夜悠悠白日迷，悲哉秋之为气乃风为。","窈谷彷徨飞叶舞，平原烟邑野云垂。","已入深闺撩远梦，还依绝塞起关思。","登临忽就幽人怨，流年翻生壮士悲。","壮士幽人多惋慨，深闺绝塞易惊痗。","古今摇落出秋心，心心强半皆风碎。","独有酒在歌筵不易忧，至于人沉宦海不可浮。","何爱能分欢喜席，何利能关富贵谋。","故乡思莼闻一叹，汾河哀棹见中流。","于戏恍悢兮秋声，乃无根而纵横。","交关塞之魂梦，深士女之性情。","扬诗骚之陶郁，怆时序之送迎。","不顾荡荡帝王胸，兴亡老壮乐悲同。","征夫思妇无穷止，哀伤群怨与时终。","此外之人难为力，惟有黠贪与愚愎。","九十秋风彼百惑，于戏大块将黯默。","窃歌此辞助秋吟，回风下土尽悲音。","平原窈谷欲飞襟，吹彻千古万下心。"]},{"t":"内叔林韩海招同林翁曰提陈君玉柱脩禊凤凰台举酒对春山漫成二十韵","f":"七言古诗","c":["三春之三始春游，正当禊事倚春洲。","主人爱客能携酒，胜友如云列凤楼。","主言登高客能赋，指点前山春在眸。","随意烟容皆靓好，参差霭黛尽芳幽。","取次林泉开记睹，更将岩壑赴冥搜。","青罗接翠互相就，玄崿霏阴不自留。","无数遥峰来及水，白云孤去碧溪悠。","晴云绿草如绮织，午对澄波作练浮。","抱日残红依鳄溆，回风舞燕逐渔舟。","动静之间情事出，高深所际绪怀流。","冥心相向春如寄，以目为身山可求。","春山与我成三友，对酒如何不劝酬。","酒酣耳热临风立，忽从霄羽望霓帱。","亲叩太皞苍帝语，氤氲满座穆飕飕。","手赠名峰三百六，人天俯仰恣夷犹。","斗南拳石无多地，我生其内我为俦。","千载误归韩姓氏，一杯初醮故峦丘。","岭外丘峦多静隐，虚名于世未区区。","春光九十山终古，今人相值速于邮。","无古无今惟一醉，主人能信予言不。"]},{"t":"鲟鱼浦阻风见渔者歌以问之","f":"古风","c":["天之奥府首称江，厥土惟泥地脉厖。","沿岸居人半渔者，扁舟欲使鱼龙降。","提纲挈网向中流，冲涛绝浪如捣撞。","庸才小鱼受束缚，戢鳞焦尾向厨缸。","鲂鱮相教慎出入，须臾不戒失奔泷。","霜刀烈釜无情面，饕餮匕箸同双双。","神理灵鼋俱疾蹙，扬鬐聚咳夜淙淙。","泣溯潜龙蛟奋武，千里长干黑气逄。","惊波十日连山起，一苇漂萍任撅椿。","我乃高叫渔人速改业，毋使阳侯迁怒滞客艭。","渔人掉头不肯听，得酒高歌醉语哤。","自言少小为此业，彼物胡为处此与我争水邦。","君不见鱼乱繇来从罟设，杀机今日何人不满腔。"]},{"t":"季秋十三日领敕恭纪","f":"古风","c":["螭头地，尺五天。","黄纸敕，阁东传。","玺书纪缦烂云烟，命臣观察无诸边。","作人树人，学古惟专。","无畏无忽，往钦汝前。","以汝兴贤，比及三年。","举能汝职，不能汝愆。","念臣承乏已备员，自知绠短汲深泉。","要当临履何冰渊，手捧天言方寸悬。","二十五条河汉宣，有一未行臣罪千。","许人一言未尝负，何况许心圣主前。","欲令臣书臣肘联，人之掣臣君察焉。","臣其从兹爱踵颠，胸有心无臣敢然。"]},{"t":"七哀章哭宋尔孚 其一","f":"楚辞体","c":["噫吁嘻，痛哉尔孚。","尔能涉云泛雾遂长徂，欣欣遐举自媮娱，岂畏尘寰太浊粗。","精魂坎壈厌微躯，一朝遂不少须臾。","鸣呼哭君兮诗以呼，招魂自古忆骚徒。"]},{"t":"七哀章哭宋尔孚 其二","f":"楚辞体","c":["乃不留斯人，以为山水匹。","双溪秋浪澹冥冥，黄岐一带伤心出。","行歌载酒人何适，啸雨啼烟变白日。","鸣呼哭君兮山水心，山自高兮水自深。"]},{"t":"七哀章哭宋尔孚 其三","f":"楚辞体","c":["乃不留斯人，以为风雅舌。","萧萧九辨二千年，楚秋一派传岭揭。","严霜白露失时心，流入歌章俱秀洁。","呜呼哭君兮风雅芜，蕙华无实百芳枯。"]},{"t":"七哀章哭宋尔孚 其四","f":"楚辞体","c":["乃不留斯人，以为弦酒欢。","披衣朝夕旧盘桓，一樽一曲自波澜。","当年嵇阮何如此，伤心未必广陵弹。","呜呼哭君兮弦酒残，咫尺城东不忍看。"]},{"t":"七哀章哭宋尔孚 其五","f":"楚辞体","c":["乃不留斯人，以为吾道邻。","古云廉吏虽小臣，君子如君不损贫。","吾欲宠君千载名，悲君已去百年身。","呜呼哭君兮吾道非，今之相者独举肥。"]},{"t":"七哀章哭宋尔孚 其六","f":"楚辞体","c":["男儿生不逢时事巳隔，埋志青山头未白。","出门搔首负平生，诗书计就旂常逆。","十载蹉跎民社间，百年荏苒乾坤客。","呜呼哭君兮遂窀穸，及君无恙今何益。"]},{"t":"七哀章哭宋尔孚 其七","f":"楚辞体","c":["嗟今之人亦多端而胶加，窃不自料长咨嗟。","浮云黯黮成朝露，明月销沉化晓霞。","我能为君传笥箧，君自修文泉路遐。","呜呼哭君兮人鬼别，君死君名那可蔑。"]},{"t":"自城冈策马至平远","f":"古风","c":["冬山何有，松何郁连。","山深见松，松深见烟。","白云此中出入，以接沧浪之天。","繇来樵牧牛羊地，不疑征人策马此中还。","征人策马此中还，手折松枝挂马鞯。","溪壑崩奔危马足，树石陵临侧马肩。","念马任劳为我逸，不忍恣心促辔鞭。","朝发城冈之窈谷，午发吉潭之冷渊。","自朝自午，乡关乃前。","拭目分关之水，潈流倒射何溅溅。","心亦不能居其后，身亦不能居其前。","尚忆去冬征魂此地悬，自春夏秋又一年。","无心万木多黄落，惟有山松日静坚。","无心万木难记忆，惟有山松岁寒待客旋。","叹息寒松此岁色，吾今乃知千载其亦然。"]},{"t":"登滕王阁步丘琼山南昌第一楼之韵三首 其一","f":"五言律诗","c":["胜迹虽非旧，风流未忍休。","文心回代劫，江影落春秋。","水自东流去，客为南浦留。","愁人方岁暮，怀古一登楼。"]},{"t":"登滕王阁步丘琼山南昌第一楼之韵三首 其二","f":"五言律诗","c":["复成昔今异，相怜总不休。","时迁人易古，江远气疑秋。","灵杰雄州在，东南俊彩留。","钟情仍我辈，斯日对斯楼。"]},{"t":"登滕王阁步丘琼山南昌第一楼之韵三首 其三","f":"五言律诗","c":["易世佳名在，须臾舞席休。","才人垂一笔，此地始千秋。","星物无心改，雨云作意留。","眼前朝暮色，不尽古今楼。"]},{"t":"下滩","f":"五言律诗","c":["扁舟千岫里，次第出危滩。","侧石通微涧，崩流就远峦。","春风传鸟语，烟水入渔竿。","翻愁花落处，无奈晓芳残。"]},{"t":"久泊","f":"五言律诗","c":["兀坐香浮几，栖迟积所思。","惯于舟作室，宛在水之湄。","独有春邀伴，忽忘已谓谁。","痴来不可解，去住浑皆疑。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其一","f":"五言律诗","c":["六朝金粉色，强半入冰壶。","素岂为春绚，清宜向客癯。","应知魂共濯，独有气相扶。","羞杀千红紫，巧容出世沽。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其二","f":"五言律诗","c":["光非从素借，澹乃得明先。","疑合还珠浦，微分种玉田。","雒神初出水，虢国始朝天。","一洗娇繁态，三春不敢怜。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其三","f":"五言律诗","c":["积水环庭瀰，舒华入幕窥。","寒威春不恕，光泽夜初追。","号召神仍漠，吸呼类若私。","销沉清漏刻，幽韵窅相迟。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其四","f":"五言律诗","c":["常言春候悦，及此凛生威。","碧汉收空肃，疏星拱极微。","月能怀己洁，雪亦感知希。","声臭两俱寂，精华五夜飞。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其五","f":"五言律诗","c":["万物交于气，惟兹召以神。","漫邀春作主，反教夜为臣。","得一清宁见，与参化育陈。","吾将心共洗，此际问天人。"]},{"t":"金陵雪月仲春夜坐邀我不寐也冰几韵之 其六","f":"五言律诗","c":["天与幽人候，寤言矢勿谖。","浅深河汉影，明灭斗星痕。","嚣落孤存伴，澄馀别有根。","阳春留郢调，炉火问寒温。"]},{"t":"昏鸦","f":"五言律诗","c":["昏鸦如有意，时绕屋梁飞。","风急恋巢早，林疏觅伴稀。","栖幽能适意，游倦亦忘机。","一物知其止，天涯客未归。"]},{"t":"残年","f":"五言律诗","c":["残年忽尔去，游子身何依。","寒树收云色，霜风隐夕晖。","昏鸦看共噪，独鹤意多违。","摇落为谁晚，蹉跎一岁非。"]},{"t":"暮岁","f":"五言律诗","c":["日暮岁云暮，冬归人未归。","安能长悒悒，守此独依依。","满目无相识，惊心忽自微。","金门若个客，终日掩柴扉。"]},{"t":"雪夜独坐","f":"五言律诗","c":["漫天疑舞絮，入地总冰霙。","渐促梅魂放，先招竹响迎。","回风千里白，寒夜一冬清。","视尔如堪语，飕飕向我鸣。"]},{"t":"月夜久坐偶进一杯","f":"五言律诗","c":["月能坚客坐，久对则生愁。","徐以风开夜，濯于雪拟秋。","庭花将入梦，樽酒令回头。","忆想成三者，可宜向影求。"]},{"t":"畏见","f":"五言律诗","c":["晓吟归去什，畏见北来旌。","扰扰轩车色，悠悠木石情。","燕云回首断，岭月入怀清。","指屈八千道，秋风咫尺迎。"]},{"t":"桐庐舟中夜坐","f":"五言律诗","c":["定性偏于夜，见闻喜独真。","峰低山献月，舟小水亲人。","久与江湖熟，微知昼夜因。","聊从逝者意，此际證閒身。"]},{"t":"途中见菊","f":"五言律诗","c":["高下风花意，孤村守洁真。","三秋侵素节，一物黯劳人。","招隐非无故，感情即此新。","东篱我家在，种汝待明春。"]},{"t":"秋生","f":"五言律诗","c":["愁至晓魂撄，披衣百绪迎。","露侵宵月黯，风拂早霜明。","相物知为气，观时别有情。","萧萧诸籁发，对此感秋生。"]},{"t":"送许钦翼公车","f":"五言律诗","c":["忽尔先余去，离情动久要。","海风吹雁影，江雪振梅条。","历览披英誉，文章答圣朝。","天人应有策，荷橐拟连镳。"]},{"t":"秋日送冯尔韬明府报最","f":"五言律诗","c":["摇落初分手，登临独寸心。","行云看岭断，下月绕棠阴。","山海馀清迹，诗文忆好音。","圣明方有事，为慎救时针。"]},{"t":"夜坐","f":"五言律诗","c":["屐齿门前静，閒庭任绿苔。","冷风和窍出，疏月向窗开。","水脉池中活，云根屋上栽。","吾庐终吾爱，不足外人来。"]},{"t":"孙蜚莪邹石可过集","f":"五言律诗","c":["雨后诛茅径，春云湿草堂。","一樽供笑语，五马动辉光。","酒赋忘忧馆，啸闻在水方。","稍迟花席上，更醉月中觞。"]},{"t":"西园清事清韵","f":"五言律诗","c":["西园新橘柚，东壁旧松云。","木石能相友，禽鱼遂作群。","栽花泥入袖，灌菜水沾裙。","日暮无他事，独酌起微醺。"]},{"t":"家别慈闱 庚午冬北征作","f":"五言律诗","c":["隐忍竟成去，今从膝下分。","密缝如母见，齧指令儿闻。","繇此燕天雪，相参粤岭云。","征衣空湿尽，夙夜尚殷殷。"]},{"t":"过隘岭","f":"五言律诗","c":["连峰称隘岭，仄径俯汀山。","晓日开林杪，晴烟入岫弯。","羊肠三十里，鸟道百重间。","叹息云深处，终成孔道颜。"]},{"t":"雩都登舟","f":"五言律诗","c":["山色还依袖，棹歌已入桅。","家从云岭去，人向雪江来。","暮霭千林出，寒烟一抹开。","离心迷近远，望眼正徘徊。"]},{"t":"庐陵阻风晚泊","f":"五言律诗","c":["阴曀日飘发，悠悠折客程。","凄深林壑气，淡泊水天情。","寒雾依江暮，霜华逐浪生。","思家寻梦早，可奈旅魂惊。"]},{"t":"梦徐九一邀游虎丘坐千人石上待月联吟觉来枕上偶记数联似五言律也","f":"五言律诗","c":["晚露华山□，游情绝世根。","千秋川泽气，三载粤吴魂。","古月今相对，新诗近孰尊。","沉吟收夜色，歌啸辟天门。"]},{"t":"然不忆何语出何人矣残灯馀几雨雪霏雱有怀耿然依韵追足","f":"五言律诗","c":["莫逆交之橐，有怀梦亦根。","游神通历览，盟性启精魂。","静觉文心一，孤存夙约尊。","远思劳寐接，春雪乱吴门。"]},{"t":"读肃之诗","f":"五言律诗","c":["探意出声始，而神忽逗之。","理于玄引绪，情以静专思。","浑漠人天籁，宁关笔墨司。","掀髯披韵刻，此际孰相窥。"]},{"t":"病腕","f":"五言律诗","c":["臂与閒为狃，腕因不受调。","徐从书纠旷，还借药降骄。","甘苦惟神剂，浅深亦意料。","未能知手舞，肱枕或馀饶。"]},{"t":"晚泊所见","f":"五言律诗","c":["落日逶迤去，丹霞宛转轻。","山深千树绿，月泻一湖清。","澄澹繇宽蓄，空濛自远横。","微风天汉过，仍曳彩云生。"]},{"t":"挂席过南浦","f":"五言律诗","c":["水力惟风竞，高帆出晓阴。","西山飞鸟过，南浦落花深。","雾重千林影，舟轻万里心。","会看龙跃处，直向剑江寻。"]},{"t":"月晕","f":"五言律诗","c":["丹霞组锦幕，金魄累瑶官。","景合诸星拱，灵生两曜通。","重轮初引象，太极始辉空。","圆明欣相覆，身依末照中。"]},{"t":"阴暮","f":"五言律诗","c":["晴阴云日抱，薄暮水霞争。","近远分山异，浅深授客清。","黄鹂依树绿，白鹭点溪明。","微出三春韵，各因一物情。"]},{"t":"农圃","f":"五言律诗","c":["春霖谁见德，独向圃农家。","山集云雷隘，岸倾陇亩斜。","微闻泉脉动，欲令远心遐。","植杖何人者，优游语种瓜。"]},{"t":"晚望","f":"五言律诗","c":["微风传窈谷，细雨到平沙。","岸色迎垂柳，波文卷落花。","云林深愈绿，山卉薄能华。","野意来无尽，青烟叠晚涯。"]},{"t":"春汀","f":"五言律诗","c":["扁舟时一望，云水入春汀。","淡泊如孤性，凄清就远坰。","沙喧争汲女，波动款飞蜓。","随意花风起，悠然动渚馨。"]},{"t":"泊攸镇","f":"五言律诗","c":["跂远日悠悠，聊从一苇谋。","心微迎鸟语，意适俯鱼游。","暮雨仍相续，前滩未可柔。","灭明村火出，孤缆向昏投。"]},{"t":"上滩","f":"五言律诗","c":["弱缆从奔濑，一滩破一心。","身随鸥鸟泛，歌动水龙吟。","偶尔惊涛及，难因短棹禁。","每怀川涉意，因此益临深。"]},{"t":"燕","f":"五言律诗","c":["受风因下上，裔水自差池。","日渚留形薄，春洲递语卑。","处堂恋主德，渡海赴鹏期。","漫有深林在，无心借一枝。"]},{"t":"瑞金寇警","f":"五言律诗","c":["青春犹水国，粉堞见流民。","扰扰居行色，飘飘旦暮身。","自为万里客，每念四方人。","安得春陵作，凄然此地陈。"]},{"t":"雨过隘岭口占","f":"五言律诗","c":["细雨千山内，轻云万木坰。","钩连从灭没，屈折落青冥。","仰胁舒心目，交襟抱影形。","藏身真隘岭，何处是前汀。"]},{"t":"泊上杭界","f":"五言律诗","c":["山深依树峡，溪转见柴门。","鸟雀逢人语，牛羊与牧喧。","澌流无静势，芳麓有微痕。","一苇相依倚，薜萝尚可扪。"]},{"t":"雨泊鲟鱼村隔舟讯杨承之 癸酉北征舟中作","f":"五言律诗","c":["寂寞江村处，连绵风雨时。","招邀无一事，闻问各何思。","玄草君成否，危言我亦为。","消閒差此胜，分手共成诗。"]},{"t":"晚望雷发","f":"五言律诗","c":["披窗舒望眼，向夕屡徘徊。","雨点穷春日，江声动晚雷。","苍茫烟水去，历乱电光来。","看取满盈意，羁怀倏与开。"]},{"t":"清明日雨望计春","f":"五言律诗","c":["九旬春序六，万里客程三。","一水云光湿，千山雨鬓毵。","桃花红未了，柳色绿相参。","何处愁心数，惊时祇自憨。"]},{"t":"泊皖江走笔讯方肃之","f":"五言律诗","c":["三载过君再，依依一水盈。","诗从传处尽，绪自问时生。","以我春江约，听君雨谷声。","书行仍引领，目极片云争。"]},{"t":"有怀陆山甫","f":"五言律诗","c":["思君何处起，回首岭云深。","祖帐披胸语，灯前顾影吟。","阮生馀白眼，季子尽黄金。","徒将一杯酒，为余万里心。"]},{"t":"幽斋偶成","f":"五言律诗","c":["素几明幽独，盆花为客公。","娇纭晴日霭，氲燠暮春风。","心定迎喧寂，窗虚受色空。","午云檐际落，亦向此冲融。"]},{"t":"客路","f":"五言律诗","c":["青春归白水，岐路忆同人。","所畏莺声老，还愁马背新。","长途难屡计，幽事颇宜亲。","近识杨花意，飘摇念客身。"]},{"t":"新暑","f":"五言律诗","c":["炎帝司初令，高云散碧端。","恒旸方与助，新暑遂难宽。","去鸟惟依树，来人未解鞍。","所愁芳草歇，谁念客途单。"]},{"t":"午车","f":"五言律诗","c":["远道收春尽，轻车破夏来。","晴岚归远树，燠霭散平莱。","永昼光初嚇，午云倦不开。","凉薰虽可悦，畏日亦长哉。"]},{"t":"雨意","f":"五言律诗","c":["雨意分朝暮，山容合近遥。","褰帷惟鸟见，倚轼亦云招。","乍令红尘退，还疑碧草骄。","长途争此刻，赢得我歌谣。"]},{"t":"邹滕道中喜连日密云细雨","f":"五言律诗","c":["始见青山色，依依向远人。","炎光能稍逊，景物倍堪亲。","悦性开蝉籁，披襟动客神。","堤花垂晓露，归色尚疑春。"]},{"t":"雨后晓发夹沟驿","f":"五言律诗","c":["云轻龙意倦，雨宿鸟声阑。","晓袖浮芳润，轻蹄印草乾。","尘光愁欲放，曙色幸犹跚。","望里青梅落，应为渴者酸。"]},{"t":"过桃山岳武穆祠愤感再成","f":"五言律诗","c":["忠以冤馀愤，冤奇愤莫寻。","杀臣君不意，报国子同心。","血泪金牌湿，丹铭涅背深。","身亡和计就，悬眼恨留今。"]},{"t":"自徐州渡河途中寻春即见有感","f":"五言律诗","c":["江南春一片，河北渺难寻。","马首迷昏霭，羁怀滞远林。","莺疲歌易涩，柳细叶难阴。","惟有枝头杏，千花慰独心。"]},{"t":"所思","f":"五言律诗","c":["风尘春不让，况复久游身。","懒困花谁主，迷离草似人。","劳心空就远，周道每怀新。","渺渺林烟际，所思欲具陈。"]},{"t":"见孟尝养士及叔孙演礼故碑","f":"五言律诗","c":["时雄因客重，曲学表君尊。","义市齐公子，礼传汉叔孙。","两生终莫致，三窟竟何存。","寂寞荒碑在，徒贻识者论。"]},{"t":"日暮迷途赖初月得至新嘉","f":"五言律诗","c":["烟林西照入，东望似薰春。","竟日无啼鸟，终风独傲人。","疲心销永昼，迷路赖初轮。","细细轻弦出，微光念远身。"]},{"t":"东平晓望","f":"五言律诗","c":["春光惟晓际，花柳暂逢迎。","嫩绿殊轻薄，妖红遂满盈。","凄清从汶水，烂熳及东平。","幽事初关切，风尘莫骤惊。"]},{"t":"东阿晓望见雨后春色心目为之一开","f":"五言律诗","c":["旅绪终无极，花光亦有初。","含情窥远道，连类见群居。","细细朝菲缀，依依晓艳舒。","幽园殊衬帖，春色任亲疏。"]},{"t":"雨宿","f":"五言律诗","c":["雨宿花光重，风浮草色轻。","转添莺欲语，更觉柳摇情。","碧野真如洗，烟林复与清。","欣欣群物意，相对愧劳生。"]},{"t":"将至荏平见雷风大作","f":"五言律诗","c":["鼓动雷风职，方春振百凋。","群生俱有待，万汇各相翘。","久客甘濡滞，饥农欲悴憔。","自悲仍虑物，心折任飘摇。"]},{"t":"暮轺见归鸟有感","f":"五言律诗","c":["群飞俱一息，日入故林招。","自惜羽毛瘁，兼防牖户漂。","如何万里客，不及一枝鹩。","俯首惭诸翼，悠悠促暮轺。"]},{"t":"哀东人三首 其一","f":"五言律诗","c":["岂不重乡井，其如转壑沟。","携持相死救，离散或生偷。","幸未沦胡虏，犹当仰喔咻。","须臾喘息计，黾勉一箪求。"]},{"t":"哀东人三首 其二","f":"五言律诗","c":["东人亦孔痗，饥馑接疮痍。","兵后荒常必，黎馀旱易欺。","何臣容节矫，无地可民移。","万里萧条客，分餐欲济谁。"]},{"t":"哀东人三首 其三","f":"五言律诗","c":["救荒政十二，省薄首相教。","无骨供输挽，何心积厩庖。","鸿飞看在野，鼠食问谁郊。","所叹求刍牧，依然向斗筲。"]},{"t":"见诸邑遍立粥厂高旗旗书抚院明文饥者之口果及粥乎否也","f":"五言律诗","c":["独怜疮补计，今下肉糜文。","巧妇炊谁见，邦人谷未闻。","群哺非易合，中饱竟难分。","自古流图绘，何时达圣君。"]},{"t":"饥者毙于荒而有不尽以荒毙者催科抚字当并计矣二首 其一","f":"五言律诗","c":["狗彘皆人食，衣冠半茧丝。","君无尤旱魃，民已失春时。","考未阳城署，都非孔距为。","如何饥馑故，独使旰宵思。"]},{"t":"饥者毙于荒而有不尽以荒毙者催科抚字当并计矣二首 其二","f":"五言律诗","c":["未易言蠲赈，庶几别旧新。","用三离父子，取一足君民。","经国前贤训，哀时独我陈。","空谈何补切，或可助仁人。"]},{"t":"寂寂","f":"五言律诗","c":["寂寂芳郊色，纷纷孔道颜。","炎凉虽异地，清浊自殊班。","彼结幽人侣，此为达者关。","客心殊异迹，车马亦云山。"]},{"t":"野色","f":"五言律诗","c":["野色来天地，春怀动古今。","云从生及止，烟自浅为深。","接瞬穷诸变，哀时抚寸阴。","生涯从此问，更作远游心。"]},{"t":"四月二日再补客司二首 其一","f":"五言律诗","c":["将母来生事，惟寅夙夜心。","常存非孝意，以著服官箴。","寂寞时犹昨，艰虞道弥深。","作忠求寸补，何地可浮沉。"]},{"t":"四月二日再补客司二首 其二","f":"五言律诗","c":["莫道含香旧，依然束带初。","中原方羽檄，四海尚车书。","典属虽无似，和容庶有馀。","圣朝收敝帚，犹诏锦窠居。"]},{"t":"中秋前一日有七闽督学之命","f":"五言律诗","c":["雪峰初入望，旗鼓旧相扶。","观察当年相，考亭百代儒。","一官仍己学，吾道未邻孤。","叹息高山在，谁能隔步趋。"]},{"t":"有感","f":"五言律诗","c":["十年玄尚白，知我自寥寥。","养拙诗书际，藏身礼乐朝。","何心皋北近，每叹指南遥。","此意含终古，时人那可料。"]},{"t":"坚坐","f":"五言律诗","c":["一室分晨暮，空庭秋气敲。","露凝天汉冷，风动斗枢摇。","纵目来潇旷，虚心对泬寥。","悠悠长夜袭，坚坐遂中宵。"]},{"t":"爽色","f":"五言律诗","c":["燕舍忽成秋，梧风就客愁。","俄传声憭慄，渐觉气高浮。","霜薄朝花耐，天空晚雁悠。","月明西岭对，爽色尽皇州。"]},{"t":"散馆得春曹未补","f":"五言律诗","c":["六载藜灯倦，三秋兰署深。","红颜吹短鬓，白眼愧华簪。","坐对浮云变，时忧末路沉。","闻弦应欲坠，按剑复何心。"]},{"t":"解嘲","f":"五言律诗","c":["少小怀孤尚，浮名那足贪。","遇禽羞获十，分栗任朝三。","已笑书空拙，更深愿外惭。","虽云不晓事，遮莫解嘲谙。"]},{"t":"长叹","f":"五言律诗","c":["摇落秋风日，低徊万古心。","青云悲短翮，白雪怅孤吟。","懒复呼升斗，终须问尺寻。","当年初服在，长叹未抽簪。"]},{"t":"补主客司有提督二馆之差","f":"五言律诗","c":["礼乐从君子，车书尽远人。","献方无异物，典属有微臣。","咫尺阶前近，要荒万里邻。","从兹诸服外，谁敢不尊亲。"]},{"t":"贡使杂沓至馆","f":"五言律诗","c":["重译归中国，咸宾及四门。","正仪思足法，束带自能言。","表饵非吾术，柔怀属圣恩。","须知干羽地，观耀莫齐论。"]},{"t":"西番诸夷方物多恶薄及乌思藏入贡违期诗以示之","f":"五言律诗","c":["流沙非不远，鞭箠在阶堂。","西旅能通道，氐羌自享王。","薄来虽有训，职贡本无忘。","自古咸宾日，何时失献方。"]},{"t":"与朝鲜贡使","f":"五言律诗","c":["独念间关苦，劳来出至尊。","蠢奴方绝命，尔国旧同伦。","普率思王土，梯航亦圣恩。","但无忘远服，自可世维藩。"]},{"t":"鲜使以皇华石洲二集求序兼乞余诗文稿书以答之","f":"五言律诗","c":["著书依北阙，问字及东夷。","八则传箕后，同文入盛时。","未飞司马檄，能诵大苏词。","海外多声教，归求自有师。"]},{"t":"汶上阻雨 甲戌册荆藩道中作","f":"五言律诗","c":["朝云行岫出，暝雨向林深。","乍喜红尘退，还愁绿野沉。","前车迷屡望，后骑未闻音。","惟有孤村火，遥悬失路心。"]},{"t":"邹邑道中雨过晓望","f":"五言律诗","c":["晨郊收宿雨，晓望出馀清。","野意参差碧，山容近远明。","苔浮生日厚，草湿受风轻。","更觉含烟柳，离披似客情。"]},{"t":"晚眺","f":"五言律诗","c":["骋目清郊际，轻阴拂道周。","山容兼野澹，林影入村幽。","万象空烟合，孤霞夕丽流。","繇来多晚兴，此际倍悠悠。"]},{"t":"七夕江月 距立秋前有六日","f":"五言律诗","c":["江远摇凉月，影分天汉流。","弦光低鹊渡，机石拂蟾钩。","巧向何人得，槎因使客浮。","祇怜欢夜短，此夕未为秋。"]},{"t":"十四夜泊繁昌旧县镇","f":"五言律诗","c":["月自无而满，风惟西与南。","秋光时可掬，天意日难探。","绿岸同舟懒，青山对客憨。","羁人甘寂寂，或恐使星惭。"]},{"t":"汉川秋怀","f":"五言律诗","c":["垂耳悲劳骥，冥飞羡逸鸿。","及兹游远日，方见出门功。","招隐怀幽桂，歌骚变落枫。","沧浪何处叟，此调或相同。"]},{"t":"十七早晓发虚江","f":"五言律诗","c":["落月衔山白，归帆出树青。","新凉烟抱石，欲晓影摇汀。","醉梦滩声破，昏愁鸟语醒。","披衣成独对，云水自泠泠。"]},{"t":"雩都山行","f":"五言律诗","c":["秋嶂青无几，合色始纷纭。","积爽招遥黛，含凄散窈云。","浅深环径别，阴霁百峰分。","日暮孤村见，疏篱已落曛。"]},{"t":"大宁晓发","f":"五言律诗","c":["玉露团深巘，征人拂晓裾。","梯盘窥鸟道，穿穴探猿居。","烟合疑松卧，泉幽听谷歔。","赪颜得素术，飞液正堪茹。"]},{"t":"春雨晓对","f":"五言律诗","c":["花雨销红色，春潮转碧芳。","清晨观物变，闭户息时光。","独令幽怀远，因知隐趣长。","深居非避世，不敢向人忙。"]},{"t":"雨宿 其一","f":"五言律诗","c":["孤吟明独对，耳目作生涯。","雨宿闻啼鸟，风前中落花。","无营春愿足，即事晓因加。","静色烟光外，幽情欲共遐。"]},{"t":"雨宿 其二","f":"五言律诗","c":["晓寂堪无虑，所思忽复长。","拙愁因景逼，痴懒怪时忙。","个个啼莺怨，双双舞蝶狂。","撩情若在酒，凭此醉春光。"]},{"t":"乙亥北征至分关却望","f":"五言律诗","c":["出门山导客，及此与云深。","俯视苍茫接，遥看碧落沉。","岐峰迷别绪，洄涧落乡心。","万里伤魂处，离初泪不禁。"]},{"t":"过上杭陈扆六相招夜集自述两令坎壈事诗以慰之兼志别悰 其一","f":"五言律诗","c":["频年离索感，偶对语飘零。","已见君头白，犹求世眼青。","可怜逢故识，仍使叹晨星。","夜尽倾前绪，游人驻马听。"]},{"t":"过上杭陈扆六相招夜集自述两令坎壈事诗以慰之兼志别悰 其二","f":"五言律诗","c":["君归竭俸钱，杯酒客心怜。","此地青山色，当年塞北烟。","不因时坎壈，谁与日林泉。","感昔姑相慰，离悰倍黯然。"]},{"t":"过清江晤陈建侯主簿走笔书赠","f":"五言律诗","c":["垂白西江簿，当年南岭英。","知君能自勖，逢世少同声。","淹泊斯文色，蹉跎此宦情。","但存高士节，尚得古人名。"]},{"t":"泊洪都赠何蜚鸣","f":"五言律诗","c":["常于天下士，特达问宗因。","世道今同见，寸心夙自真。","爱君风义笃，令我气声亲。","三载流洄处，西江一故人。"]},{"t":"和江上","f":"五言律诗","c":["万古天堑水，当前客绪悠。","连空堪四望，落日自多愁。","岁月同滔没，阴晴别应酬。","劳心时不舍，难向逝波遒。"]},{"t":"将至采石矶飘风骤发收舟不及泛泛江中者移时诗以志险用前韵","f":"五言律诗","c":["倏忽诸山动，飘零一叶浮。","风涛观素履，忠信任虚舟。","不历鲸波变，安知鲛泣愁。","平生夷险故，事往默追求。"]},{"t":"久棹","f":"五言律诗","c":["久棹江情备，周流心目知。","云山开气象，风雨幻灵奇。","非海应难水，连天不易涯。","自疑萍转客，万里日追随。"]},{"t":"宋九青给谏将联诗社诗以商之三首 其一","f":"五言律诗","c":["冥思兼旷览，求应总纷纷。","雅颂如能得，兴观亦可群。","倾谈初束帛，豁意已披云。","默尔精魂感，相同独向君。"]},{"t":"宋九青给谏将联诗社诗以商之三首 其二","f":"五言律诗","c":["联心分一砥，执耳问初盟。","大雅微茫日，王风次第明。","兴衰宁大运，终始在元声。","细察推移理，思君练要情。"]},{"t":"宋九青给谏将联诗社诗以商之三首 其三","f":"五言律诗","c":["移风真首务，观世本文心。","历探情声始，返思得失林。","欲求人尽我，不令古无今。","一往同孤尚，千秋讵可禁。"]},{"t":"上陵道中","f":"五言律诗","c":["出郭明孤性，相招已白云。","千峰收晓眺，万壑动秋氛。","气势遥相长，精光近若群。","龙湖天意笃，灵岳自氤氲。"]},{"t":"陪祀昭陵","f":"五言律诗","c":["霜露秋思肃，林峦暮色封。","苍玄归化迹，丹紫变深峰。","瑞蔼环弓剑，灵扃闭鼓钟。","萧萧悽怆夜，奔走向楸松。"]},{"t":"归道取西山是夜宿碧云","f":"五言律诗","c":["山因秋澹泊，静理作游心。","策马排云至，看鸿带月深。","草烟迷础色，松响触泉音。","耳目谁能着，安禅入梦寻。"]},{"t":"是早过香山","f":"五言律诗","c":["古寺烟疑渍，孤光近远同。","晴苔深夙露，寒树老秋风。","畜爽无昏旦，衔幽自色空。","璃灯初一照，顿令皈依终。"]},{"t":"来青纵目","f":"五言律诗","c":["千山供一览，眼尽即云天。","聚霭高卑错，巉阴右左悬。","髻当斜照阙，襟抱反吹前。","睥睨真何际，微茫得又玄。"]},{"t":"洪光松盘","f":"五言律诗","c":["偶循苍径入，已在绿云堆。","晓磴旁阴合，寒烟一缕开。","交巾低密翠，折屐远轻埃。","静里钟声发，还同吹万来。"]},{"t":"玉泉观源","f":"五言律诗","c":["入山不必深，一壑可幽寻。","止岫含奔涧，回堤吐漭音。","蓝光飞玉注，碧潋伏珠沉。","对此能朝夕，清颜或洗心。"]},{"t":"万庄稍憩","f":"五言律诗","c":["罢游因晚兴，花坞得秋颜。","霜叶红相胜，云林绿未删。","较山微绮丽，踞野亦深閒。","夕照寒峰外，何人此未还。"]},{"t":"再督两馆感昔","f":"五言律诗","c":["两阶依日月，万里合风云。","有道夷为守，脩名远不勤。","方期成序至，敢谓后时闻。","却省尸瘝罪，还思告让文。"]},{"t":"喜朝鲜来贡","f":"五言律诗","c":["圣代时称广，东夷岁职方。","再看垂櫜至，始信薄来常。","自抱珍奇耻，非关训导章。","微臣循旧则，夙夜诵无荒。"]},{"t":"以仲冬月转本司副郎自述","f":"五言律诗","c":["一官仍典属，三载见咸宾。","斯亦观生进，即于与客频。","知名宁远域，束带是皇臣。","聊幸当重译，长应备舌人。"]},{"t":"饱食卒岁因之自警四首 其一","f":"五言律诗","c":["匡居能竟日，今始识閒曹。","静觉餐仍素，谁云酒目劳。","殷忧多若醉，嗛食少为膏。","手口徒相息，心颜几忸陶。"]},{"t":"饱食卒岁因之自警四首 其二","f":"五言律诗","c":["职思方岁莫，饮食视云需。","怀肉曾誇剑，分羊复耻钩。","饥犹存季女，饱欲死侏儒。","簌簌何人者，还誇谷有无。"]},{"t":"饱食卒岁因之自警四首 其三","f":"五言律诗","c":["日月将穷节，民神合聚时。","鱼冰坚泽腹，蚕火照田丝。","观蜡因人乐，退公或自私。","作糜名口教，授粲岂徒期。"]},{"t":"饱食卒岁因之自警四首 其四","f":"五言律诗","c":["谋食非君子，观颐及万民。","尝思分社肉，每叹治齐醇。","微术经天下，有孚视一身。","饔餐馀妙理，况可付昏晨。"]},{"t":"送邹石可出守襄阳三首 其一","f":"五言律诗","c":["欲别春风半，离心楚地悠。","行当芳草色，往见白蘋秋。","雁影荆门落，狼烟汉水收。","此时能却望，应忆故人游。"]},{"t":"送邹石可出守襄阳三首 其二","f":"五言律诗","c":["昨从燕黍谷，出问楚筳篿。","转律阳春日，操弧翼轸天。","方城堪众禦，万灶待君烟。","及此鸣庚始，还加五马鞭。"]},{"t":"送邹石可出守襄阳三首 其三","f":"五言律诗","c":["近说襄阳地，古今人事分。","习池当祖道，羊石但征云。","岘泪馀初迹，䍦歌失旧闻。","俟君盘错见，山水未离群。"]},{"t":"国计","f":"五言律诗","c":["农臣思国计，望屋急军前。","多取难因岁，三征不问田。","为都皆可去，署考孰能先。","勉语沟中瘠，扶疮向朴鞭。"]},{"t":"主恩","f":"五言律诗","c":["主恩权用缓，兵火赐田租。","意动天人感，膏同雨露濡。","汉书先父老，周政始鳏孤。","取次三春泽，还思四海俱。"]},{"t":"时难","f":"五言律诗","c":["王心因岁省，天步值时难。","云汉初回象，山川自改观。","黍苗兴旱月，衣褐慰祁寒。","造命明君事，流灾那可宽。"]},{"t":"旰食","f":"五言律诗","c":["年饥思赈术，旰食作含哺。","阍远今如近，天高日可呼。","去郊安硕鼠，瞻屋定飞乌。","叹息穷闾贱，深劳圣主图。"]},{"t":"兵事十首 其一 徵兵","f":"五言律诗","c":["固垒逍遥卒，夷丁杂汉群。","将骄人命贱，寇退首功分。","暮野生燐火，春郊老阵云。","相传今面敌，稍见祖家军。"]},{"t":"兵事十首 其二 措饷","f":"五言律诗","c":["粟行将万里，刍竭自何年。","枵腹难终俟，遣苞孰共前。","方敲民骨髓，稍给士糇饘。","为语三军众，飞腾莫自便。"]},{"t":"兵事十首 其三 防河","f":"五言律诗","c":["颓云朝夕压，坚腹近遥淩。","树介征麾变，霜阴杀气凝。","旟旐来豹幄，组练杂渔罾。","游釜何人者，投鞭那可矜。"]},{"t":"兵事十首 其四 城守","f":"五言律诗","c":["恃险舟皆敌，脩文守在夷。","时危难远语，效死必城为。","有意求蛙产，何心问茧丝。","繇来人志结，不使地天移。"]},{"t":"兵事十首 其五 分险","f":"五言律诗","c":["务隘当分扼，先人作战筹。","联心惟谨养，弭耳贵专谋。","有地因民守，无形令敌愁。","悬思千击万，险阻庶全收。"]},{"t":"兵事十首 其六 合围","f":"五言律诗","c":["使寇如流溃，何兵可障川。","五行迷克土，八载任滔天。","背水人俱怯，壑邻计久偏。","虚声求胜势，群力总波漩。"]},{"t":"兵事十首 其七 老师","f":"五言律诗","c":["玄黄当久战，朝野共无衣。","师老民从毒，兵钝贼见几。","中枢迟上策，专阃积轻威。","不识縻军是，谁云尾寇非。"]},{"t":"兵事十首 其八 策抚","f":"五言律诗","c":["弄兵宁异昔，逸火庶非今。","渠胁分群命，死生问一心。","井闾还旧有，牛犊可新寻。","倘及阳庚日，春风散绿林。"]},{"t":"兵事十首 其九 传烽","f":"五言律诗","c":["极目平安火，乡云白似红。","朔风悲立马，南雪滞征鸿。","燐野荒寒日，腥川恣渴虹。","天涯微宦客，愁坐似羁笼。"]},{"t":"兵事十首 其十 露布拟而期之也","f":"五言律诗","c":["连阃歌铙日，深宫动乐晨。","乾坤将厌杀，城野共还春。","夜影销欃焰，朝书出战尘。","尚期三捷至，先系百渠陈。"]},{"t":"季春十日姚永言招同黄可远宋九青夜集谈诗微商同异三首 其一","f":"五言律诗","c":["谬附东南美，君前见古今。","连杯存酒意，聚首出文心。","交岂声坛重，时当宦海深。","试将清夜语，还赋白头吟。"]},{"t":"季春十日姚永言招同黄可远宋九青夜集谈诗微商同异三首 其二","f":"五言律诗","c":["惊坐初雷殷，虚怀永夜怡。","同声堪异响，故友合新知。","泣鬼千年后，风人百代移。","多言妨古秘，三口借君卮。"]},{"t":"季春十日姚永言招同黄可远宋九青夜集谈诗微商同异三首 其三","f":"五言律诗","c":["春夜融如水，因人共与清。","波澜从酒动，原委向诗明。","河汉虽无极，山泉各自生。","繇今看末砥，何似一杯平。"]},{"t":"阅邸抄见晋中闻喜沁原等县开立人市至父子夫妻相食又豫中南阳母子相食随奉明纶前后发御前银五万馀遣使星夜解往设法救济感叹有作四首 其一","f":"五言律诗","c":["易子春秋讳，分翁楚汉欺。","犹言家不计，或在势难支。","今日虽荒馑，皇恩积岁时。","伤心沟壑际，竟作兽人为。"]},{"t":"阅邸抄见晋中闻喜沁原等县开立人市至父子夫妻相食又豫中南阳母子相食随奉明纶前后发御前银五万馀遣使星夜解往设法救济感叹有作四首 其二","f":"五言律诗","c":["兽食人犹恶，民饥兽所怜。","官言终坐毙，帝念久颠连。","昃日分宫膳，飞云入灶烟。","救荒十二策，谁似主心先。"]},{"t":"阅邸抄见晋中闻喜沁原等县开立人市至父子夫妻相食又豫中南阳母子相食随奉明纶前后发御前银五万馀遣使星夜解往设法救济感叹有作四首 其三","f":"五言律诗","c":["臧圭行急病，汲节矫便宜。","自古贤臣事，于今圣主思。","收人宁问乏，遣使尚忧迟。","疋帛宫中数，惟民不计赀。"]},{"t":"阅邸抄见晋中闻喜沁原等县开立人市至父子夫妻相食又豫中南阳母子相食随奉明纶前后发御前银五万馀遣使星夜解往设法救济感叹有作四首 其四","f":"五言律诗","c":["移民终小惠，罪岁始多侵。","当道矜豺虎，驱人忍兽禽。","何官思野色，惟帝达天心。","真切流膏下，兼闻引痛音。"]},{"t":"孟秋十六日于役天中与黄赞伯联辔有述二首 时虏氛方逼近畿 其一","f":"五言律诗","c":["治行千里日，求士两河时。","日月方交斗，风云未改期。","阶前辞舞羽，马上听谈诗。","结束依戎伍，何人识主司。"]},{"t":"孟秋十六日于役天中与黄赞伯联辔有述二首 时虏氛方逼近畿 其二","f":"五言律诗","c":["诘戎非不急，文事岂虚求。","将与戈予客，兼同表饵谋。","因之观士报，终以太儒猷。","济济中原俊，谁忘普率雠。"]},{"t":"自感二首 其一","f":"五言律诗","c":["日月难因世，乾坤孰置身。","在三从属我，未一所求臣。","争大宜心竞，持危视力陈。","祇今言报国，何事可为人。"]},{"t":"自感二首 其二","f":"五言律诗","c":["说剑求欧冶，读书与斲轮。","纵横思计就，文武择能陈。","世合轻儒术，时方倚斗臣。","峨冠虽未解，交椊亦其人。"]},{"t":"淇水古意","f":"五言律诗","c":["停车淇水上，古意见秋风。","绿竹诸君子，白圭一武公。","千年称睿圣，当日自童蒙。","非哲非愚者，庶几三复终。"]},{"t":"闱中第三场有鹤集鸣明远楼当事索言纪瑞","f":"五言律诗","c":["天中明远楼，楼上鹤鸣秋。","何日遵鸿渚，先时引鹿呦。","在阴縻爵见，闻野向皋浮。","云路从朝翼，嵩河特近游。"]},{"t":"夜坐阅卷毕循步阶櫩仰象有言","f":"五言律诗","c":["肃然秋夜对，起视已星陈。","心目无穷止，菁华始逼亲。","斗箕分极远，经纬九霄均。","云汉垂垂下，天中烂客身。"]},{"t":"秋雨连日是夕拜榜既毕云烂星陈明月出焉是可纪也二首 其一","f":"五言律诗","c":["黾勉秋期竣，适当云汉清。","光为君子吉，化以圣人成。","豫野招贤见，宵中太乙明。","灿然心目际，毋乃至文精。"]},{"t":"秋雨连日是夕拜榜既毕云烂星陈明月出焉是可纪也二首 其二","f":"五言律诗","c":["宵中糺缦缦，大象乃苍苍。","似竭风云力，方开斗极光。","昭回同四表，焕发始中央。","俯仰观文意，谁云少报章。"]},{"t":"上雒王别馆曰城市丹丘其中园洞石山特幽至可屡游诸君子见招多于此习而不厌因以有言二首 其一","f":"五言律诗","c":["宋代愁花石，梁王叹粟民。","何知城市里，自得水山身。","易地殊忧乐，观时杂笑颦。","开樽君子至，爱客寸心真。"]},{"t":"上雒王别馆曰城市丹丘其中园洞石山特幽至可屡游诸君子见招多于此习而不厌因以有言二首 其二","f":"五言律诗","c":["飞楼烟上下，虚洞月来还。","身在天人际，书传大小山。","盛名今古迫，丹诀岁时閒。","为问长生术，其中可驻颜。"]},{"t":"登石山之巅楼楼有振衣石二首 其一","f":"五言律诗","c":["竟日迷清兴，登兹遂所求。","人閒初厌雨，楼旷久矜秋。","倚石孤云动，凭轩百象浮。","如蝇看市响，歌管一声收。"]},{"t":"登石山之巅楼楼有振衣石二首 其二","f":"五言律诗","c":["全出秋颜色，初如客性情。","前峰经掌削，环郭渐鳞生。","暮霭相回互，寒烟各纵横。","久看非不美，劳心畏远迎。"]},{"t":"永城王邀同赞伯宴郊外别墅墅中环亭为池池荷留秋秋宵迟客两悠然也二首 其一","f":"五言律诗","c":["市嚣初不染，郊意已全幽。","霜叶閒随野，残荷力度秋。","开云亭势出，得水岛烟浮。","载酒园何处，清樽此地酬。"]},{"t":"永城王邀同赞伯宴郊外别墅墅中环亭为池池荷留秋秋宵迟客两悠然也二首 其二","f":"五言律诗","c":["主意初筵秩，幽人不速来。","方塘低照拂，庭树晚风开。","宿鸟窥樽起，游鱼听乐猜。","夕阳难遣兴，秋夜尚悠哉。"]},{"t":"柘城王邀同赞伯晚登铁塔二首 其一","f":"五言律诗","c":["铁塔豫梁传，数朝不数年。","标形如上涌，托体况中坚。","角亢晨昏宿，嵩河近远联。","谁能名不朽，吾欲勒其巅。"]},{"t":"柘城王邀同赞伯晚登铁塔二首 其二","f":"五言律诗","c":["忽遂登临志，还思创始功。","循阶攀峻绝，环级转空濛。","秋色收残照，乡心御远风。","因高谁不赋，我意仲宣同。"]},{"t":"过临清何洁卿民部招同赞伯署中园集","f":"五言律诗","c":["浥露思园竹，开樽有故人。","时危秋兴浅，夜静酒谈真。","戏谑无拘客，醉醒共远身。","别来醇意满，不必向君陈。"]},{"t":"之武城留题公署冀长民者一见之","f":"五言律诗","c":["偃室留千载，下城又一时。","非公人不至，学道孰相期。","烹小同鸡邑，歌弦异茧丝。","若愁今令苦，当作古贤思。"]},{"t":"报命之日即转本司正即有述二首 其一","f":"五言律诗","c":["硕人方万舞，君子俟三年。","率属通夷夏，赏功尽腹边。","曹清容我拙，吏习觉官贤。","屈指来王至，还当束带前。"]},{"t":"报命之日即转本司正即有述二首 其二","f":"五言律诗","c":["四门宾客主，三许姓名题。","岂不专官久，终忧下国携。","缀球思共骏，航海望山梯。","何日秋风里，东西罢鼓鼙。"]},{"t":"有怀岐岩新寺因寄悦则讯其近日功程兼以勉之四首 其一","f":"五言律诗","c":["为汝开禅壁，息心此地逢。","市声销二水，松响接诸峰。","欲晓云光漫，深秋叶径封。","岩烟时未歇，近远俟归踪。"]},{"t":"有怀岐岩新寺因寄悦则讯其近日功程兼以勉之四首 其二","f":"五言律诗","c":["怀人披萝薜，及秋葺苇葭。","时因陵麓势，日引竹松华。","筑磴留苔影，通泉护药芽。","但添新磬钵，不碍古烟霞。"]},{"t":"有怀岐岩新寺因寄悦则讯其近日功程兼以勉之四首 其三","f":"五言律诗","c":["绝壑闻溪虎，空潭少毒龙。","锡飞堪独选，云构可相从。","新竹栽何径，幽岩辟几重。","山灵关佛性，苟就亦禅慵。"]},{"t":"有怀岐岩新寺因寄悦则讯其近日功程兼以勉之四首 其四","f":"五言律诗","c":["崖谷亦何主，求人独以清。","寻玄思化迹，触类表前名。","穿石分泉响，添林得鸟情。","鸣弦方独奏，从此会希声。"]},{"t":"赠宋尔义北上访兄兼寄其兄尔孚二首 其一","f":"五言律诗","c":["轻装仍万里，一再未云艰。","至性关今古，高情失水山。","独怜原鹡去，空忆渚鸿还。","以我良朋叹，为君游子颜。"]},{"t":"赠宋尔义北上访兄兼寄其兄尔孚二首 其二","f":"五言律诗","c":["亦知官有命，吾道少逢人。","时最苛廉吏，君犹念远臣。","遥闻燕谷律，应得岭云身。","归去黄峰北，故山不厌贫。"]},{"t":"辞筵独坐漫柬诸子","f":"五言律诗","c":["偶作辞筵客，堪疑惯酒人。","阶庭贪暑退，冠履畏烦真。","子夜花留梦，深宵月在邻。","此怀应似雪，所思欲成春。"]},{"t":"自吴城至马当湖江八景 其一 珠矶 出吴城三十里","f":"七言律诗","c":["章江千里弛流难，泛滥珠矶获大观。","冬日浮沙愁野溢，春波拂渚惧闾殚。","非缘樵牧开林麓，已令蛟螭作踞蟠。","望望烟云多宝气，明湖倒影自漫漫。"]},{"t":"自吴城至马当湖江八景 其二 星墩 在星子县湖中","f":"七言律诗","c":["从风从雨自何时，一卷中流众共之。","岂有恒星终不见，谩言宋石久无知。","湖山一体如微具，翼轸分临或在兹。","便欲葺荷惟此地，乘槎泛斗复谁期。"]},{"t":"自吴城至马当湖江八景 其四 虾蟆石 在南康下","f":"七言律诗","c":["虾蟆石在几秋春，不向风涛化甲鳞。","自与庐峰为御畜，肯同诸阜作臣邻。","每愁鳌钓归龙国，稍喜蟾光下月轮。","万载湖山终不变，蛟螭怒舞欲何伸。"]},{"t":"自吴城至马当湖江八景 其五 大姑山 俗云大姑鞋在湖口上三十里","f":"七言律诗","c":["春水凝寒木叶濡，姑山风袅未秋殊。","缑城巨迹谁来往，雒浦溦波事有无。","遗舄于今看定履，冲流千载似前驱。","佳期夕望逾荒忽，眇眇愁予隔步趋。"]},{"t":"自吴城至马当湖江八景 其六 石钟 在湖口县","f":"七言律诗","c":["乍向江湖二水湄，初闻金石八音吹。","自从击拊经夔手，不尽铿鎗动武思。","风水千年空怒感，扁舟一往已情移。","咸池遗响今犹见，河海诸人未许知。"]},{"t":"自吴城至马当湖江八景 其七 小姑山 俗云小姑钗在彭泽下十里","f":"七言律诗","c":["伊人何在水中游，江有姑山未可求。","势出波烟冯万壑，云连泽气下长流。","风涛聚处如环共，木石丛居胜远游。","中砥不愁彭蠡溃，洪澜独倩马当收。"]},{"t":"自吴城至马当湖江八景 其八 马当山 在小姑下二十里","f":"七言律诗","c":["行地方知独马宜，横流万古见山奇。","澄江如练同鞭影，侧石连云共辔随。","砥尽狂澜龙虎怒，别开幽壑介鳞疑。","繇来天驷无羁络，周汉何缘得骤驰。"]},{"t":"九九同周仪伯张长卿陈木生游玉泉寺","f":"七言律诗","c":["重阳还似昔年閒，长啸西来恣往还。","万物经秋凄作气，三杯浇我醉为颜。","徐观松舞情何适，欲叩泉根足未艰。","愿化天人身百亿，随风遥向白云间。"]},{"t":"是夜宿碧云寺","f":"七言律诗","c":["偶借僧窗此夕閒，飞尘远处静云还。","坐看日落归山意，欲引风清放月颜。","夜半灯幽僧舍冷，梦中峰峭客魂艰。","醒来摇笔追残句，犹记千山鳞甲间。"]},{"t":"次日过香山寺","f":"七言律诗","c":["香郁林泉翠欲华，遥随秋意入山家。","松深寺隐钟声杳，岭曲峰多径路赊。","古佛台中云气绕，山僧榻下日光斜。","游人眷眷情何止，冷月凄风起暮霞。"]},{"t":"冬夜同曹允大方肃之姚永言徐九一陈尔新宋则甫过从李大生夜集得关字","f":"七言律诗","c":["连璧英姿总一班，樽前且斗此时閒。","狂言不禁仍多酌，醉舞何知复下关。","烛烬销花沉夜漏，风声入座起酣颜。","但令主意无烦客，便欲相期日往还。"]},{"t":"戊辰除夕同乡人小集","f":"七言律诗","c":["如何身世两悠悠，日月相穷不自繇。","欲入初春添一老，有怀今夕结千愁。","客中酒债残年送，梦里乡心五夜收。","且向诸君同暖热，谁能万里独回头。"]},{"t":"赠曹允大得假","f":"七言律诗","c":["君名已许一时传，惟有君心数友联。","同此孤怀观进退，难将傲骨较方圆。","繇来类族能通志，此去湖山亦比肩。","别后应思今日况，岭云江月静相怜。"]},{"t":"过细柳营","f":"七言律诗","c":["细柳名传汉尉时，于今柳色戟须眉。","连旌自令风云合，坚壁宁誇介胄奇。","一日师中军礼见，千秋阃外将权知。","我来吊古方徐辔，天子当年不敢驰。"]},{"t":"西湖舟中谒岳武穆庙并墓所","f":"七言律诗","c":["谁使升堂便肃钦，将军生面古犹今。","须眉隐跃峰千丈，肤理疏残土一浔。","冷落英魂风月夜，流连客意水天心。","兴怀往事徒悲愤，醉后灯前泪不禁。"]},{"t":"严州过滩","f":"七言律诗","c":["万壑东来转一涡，千峰叠起竞群嵯。","水流挟石生雄势，风力扶人杀怒波。","俯视汹腾如过颡，遥瞻蹙缩得盈科。","溯洄莫叹洵长阻，人世滩头较此多。"]},{"t":"离舟","f":"七言律诗","c":["离舟偏觉在舆新，水陆咸知万里身。","夹树含风初揖客，远山敛雾乍窥人。","不堪归路迷遐迩，可奈秋心乱夕晨。","翻恨多情云片片，随峰布置黯征轮。"]},{"t":"广信早发","f":"七言律诗","c":["我行日日向山逢，濛雨昏林气欲冬。","浮翠朝华清晓色，飞烟远碧净秋容。","诸峰壁立初无路，曲径环来别有缝。","倦客未遑寻佳胜，幽人何处喜闻跫。"]},{"t":"到家感喜 其一","f":"七言律诗","c":["忆辞燕夏岭冬并，屈指征途秋送迎。","云物随缘看逆旅，尘风初别感劳生。","北山未拟均贤什，东海私宽一乐情。","倖沐皇恩因岁月，重脩子职但温清。"]},{"t":"到家感喜 其二","f":"七言律诗","c":["十旬不觉暑寒推，万里时兴夙夜哀。","初向梓桑歌敬止，还从屺岵忆犹来。","江山梦断渔樵侣，岭海缘深鹿豕媒。","饶有家园堪结搆，蓬门偏把白云栽。"]},{"t":"杨乐庵建慈云寺既成见招得胎字二首 其一","f":"七言律诗","c":["岭海初闻大小开，天花忽见后前台。","风吹碧嶂临飞锡，月满澄湖出渡杯。","闭阁杨雄时坐卧，逃禅苏晋暂徘徊。","悬知吾辈皆前会，漫许沙门点故胎。"]},{"t":"杨乐庵建慈云寺既成见招得胎字二首 其二","f":"七言律诗","c":["自从千载韩山后，又见三车象力开。","便道人缘终就劫，乍疑佛教顿更胎。","毒龙观法新无碍，溪鳄知文久却回。","始信当年焚骨者，空言亦许大颠来。"]},{"t":"为林翁曰提题城南书室","f":"七言律诗","c":["问津重许入桃源，烟树绮花揖我言。","在水孤亭宜半榻，环城苔径助幽轩。","千年榕色交风态，五夜池心见月魂。","怪道侯门车马处，古情犹向北窗存。"]},{"t":"己巳除夕有雨","f":"七言律诗","c":["萧萧一室溯天涯，夜梦初依岭外家。","嘿数鸡声强破漏，閒看灯烬冷销花。","春方主帝催冬宿，天亦亲人借雨加。","自是皇仁东渐海，波臣万里沐恩赊。"]},{"t":"元日仍雨试笔","f":"七言律诗","c":["残华忽改觅何因，梦换春光与岁新。","犹忆衣冠随从列，初为衫履惯閒身。","香焚一室观年力，花发清朝试晓神。","却怪天心勤转序，密云飞汉两粼粼。"]},{"t":"虏儆烽传步谢韶石廉宪韵","f":"七言律诗","c":["男儿许国亦无多，几向肝陶复胆磨。","热血千秋留愤壮，孤怀此刻抚沉疴。","天方閟毖劳亲钺，身敢栖迟惮枕戈。","所惧闻鸡先有客，披衣中夜浩长歌。"]},{"t":"阅邸报有感","f":"七言律诗","c":["烽火传来动几旬，徒从事后感时新。","回风往日当年泪，武雨谋云此局人。","戎马何堪忧圣主，腥氛岂但泣边臣。","祇为报国身犹远，不忍丹心岭外沦。"]},{"t":"舟夜有所思","f":"七言律诗","c":["多时远室滞秋云，薄暮扁舟溯落曛。","水月相临惟野共，山风入抱向潮分。","在川不舍心中事，阻道相从物外群。","若使伊人难可即，来波去渚枉纷纷。"]},{"t":"北上见露布感吟","f":"七言律诗","c":["杞人无故尚忧天，海外相兼烽火连。","久恨长缨从岭阻，新闻露布自云宣。","两阶既格三旬后，诸邑能馀几姓还。","此日疮痍明主悉，无暇侈进太平篇。"]},{"t":"庚午除夕偕伯常兄吴城舟中二首 其一","f":"七言律诗","c":["岁暮湖头两弟兄，黄昏孤缆一江城。","白云千载烟波语，此地连床暖热情。","独恨年华他国去，同怜春色故园生。","祇应酌尽残冬酒，莫使飘飞旅梦惊。"]},{"t":"庚午除夕偕伯常兄吴城舟中二首 其二","f":"七言律诗","c":["客鬓朝朝欲老来，流年不但远婴孩。","湖心况逐残冬隐，山色兼招暮雨催。","忍向离颜萋岸草，孤将旅绪发江梅。","时光奄迅一如此，安得昆明无劫灰。"]},{"t":"过安庆柬方肃之","f":"七言律诗","c":["休沐归宁恰后先，岭南江北雨云渊。","玉堂清梦知同切，湖海相思忍独怜。","稍喜鸣莺迁谷日，忽忘小草出山年。","迩来东观开新局，何事离群守旧玄。"]},{"t":"归篷","f":"七言律诗","c":["归篷已诏片云生，去鹢先招一鸟迎。","短楫浮烟迷客望，满江流水总春情。","桃花半落红窗暖，草色初添碧渚清。","遮莫匡床随几息，午魂犹许蝶蝴争。"]},{"t":"午窗","f":"古风","c":["镇日支颐耐斗?，波烟下上习相从。","午窗入影撩情乱，望眼耽幽起骨慵。","山以春深难隐色，岸于江远易舒容。","云心久向孤篷寂，剩有閒愁不敢供。"]},{"t":"夜眺","f":"七言律诗","c":["计程能使客思憨，错向江乡认故潭。","渔火灭明时一见，吴音清浊久微谙。","远汀野色桅光带，断岸罛声戌漏参。","如可容舠聊止足，几于閒泊较廉贪。"]},{"t":"去舟日与风逆归舟乃能顺也","f":"七言律诗","c":["幽窗晓色自江烟，云际高帆万叶联。","风本无心随所受，天微于气诏当还。","三春就我成来日，一水从人又此年。","自北自南无限思，樯声棹响漫潇然。"]},{"t":"晓柳千堤绿","f":"七言律诗","c":["独有江光并柳间，盈盈赊色贷流湾。","春将画意传幽岸，日以晴烟到远山。","久客犹能怜舞袖，轻风谁使屈丝鬟。","千年一曲歌残晓，白傅依稀认小蛮。"]},{"t":"晚桃一带红","f":"七言律诗","c":["浴罢新芳倦晚晖，江村累累粉香围。","从娇出艳妆梅质，于绿分红裼柳衣。","一水含情遥欲迩，六朝比色是还非。","谁怜不语珍深谷，几度春风问瘦肥。"]},{"t":"竟日青山","f":"七言律诗","c":["竟日青山费眼描，云心静以远为招。","忧从桃棘时相过，思向榛苓未可要。","恰向望中生旷漠，先从意外落喧嚣。","此身疑却行僧似，丘壑随缘付一瓢。"]},{"t":"南来好伴","f":"七言律诗","c":["四载依依几送迎，故山结色此能生。","春情广覆千峰落，霞侣先开一壑盈。","相过不移知我素，此中何有祇云清。","南来好伴兹堪恋，去去江天日暮情。"]},{"t":"孤村","f":"七言律诗","c":["旦昏随息一舟偕，忘却孤村为客排。","山自云深来及水，江从天远达于涯。","蓬门蚤闭人烟带，绿草斜纷日影埋。","何许关情坚晚对，月明初向碧流揩。"]},{"t":"清明日雨","f":"七言律诗","c":["春惟有色雨为声，静落青烟一水迎。","花欲妆时先自沐，人从睡起较微清。","一瓢深浅斟于耳，百日沉浮助以情。","可奈销魂仍旦旦，杏村酒熟又清明。"]},{"t":"望","f":"七言律诗","c":["霁色娇纭雨忽争，飘风一息乱江情。","春愁欲老先留媚，日懒新长却倦明。","入眼初惊天地异，怡神仍觉水云清。","远山近岸纷相诏，恰与幽怀不但声。"]},{"t":"晚过彭蠡波静月生","f":"七言律诗","c":["湖以光临止浪喧，月为波澹缀云樊。","微招翠黛相呼吸，静寄烟涛与吐吞。","康乐诗词馀石镜，长庚游览继松门。","祇今惟此中流照，九派三江不敢奔。"]},{"t":"夜发过江西","f":"七言律诗","c":["中宵梦破子规啼，以梦寻家断复迷。","罔觉何思深似海，翻疑不酒醉如泥。","天风忽许高帆举，山月初将短棹携。","发发惊涛欹枕渡，晓魂已过大江西。"]},{"t":"寤言","f":"七言律诗","c":["寤言凄晦百般投，极目空明一带浮。","雨点风声凭客受，山心水意倩谁收。","烟帆无数争迟速，游子三春自去留。","总为时光来悯默，繁云黯䨴不胜愁。"]},{"t":"晚刻喜得微雨","f":"七言律诗","c":["雨脚千山纷欲生，悠然一水漠相迎。","春深易令云施色，昼永初从晚出清。","天以农忙应有意，人于客久漫添情。","潇潇可奈无多得，芳草迷离亦与争。"]},{"t":"记得出门","f":"七言律诗","c":["记得出门笑向西，自东自北竟先迷。","怀情独与湖山匹，积绪孤于岁月稽。","敢为凉雱歌雨雪，徒从晻霭望云霓。","犹馀初服将脩退，微尚终当以意题。"]},{"t":"晚对自叹","f":"七言律诗","c":["逶迤春日落馀晖，云各还山鸟倦飞。","感物方知回首得，观生几许素心违。","草玄执戟真堪哂，轻举悲时孰与归。","祇有藏声随海上，时从鸥客可忘机。"]},{"t":"泊万安小滩村雨后待月","f":"七言律诗","c":["稠花弱柳叠芳洲，历乱村烟向晚收。","云水相参天易合，冈峦环集月难浮。","山风拂面吹游子，春渚添流拥小舟。","夜静溪閒无一事，空濛应接亦悠悠。"]},{"t":"所见","f":"七言律诗","c":["流色滩声得雨添，石肩山足竞洄漩。","千峰啼鸟从缥缈，两岸丛花自反偏。","幽事递来勾意往，扁舟迟搒缩波前。","缘溪宛转青郊见，错认桃源夹口边。"]},{"t":"雨发雩都","f":"七言律诗","c":["两部蛙吹破雨宵，数声鸟语乱风朝。","水浮芳麓青衫湿，云出幽峰翠黛描。","聊倩溪回传景受，但闻滩涩费情调。","汀烟极目行人断，何处乡愁向我挑。"]},{"t":"听滩","f":"七言律诗","c":["汹涌孰来仍孰往，噌镗相应复相挑。","后先欲挟千山动，近远齐归万水嚣。","从石谐音如击拊，因风鼓浪亦吟飘。","祇兹浩浩非无意，独与幽人破寂寥。"]},{"t":"留春","f":"七言律诗","c":["春愁无赖已纷纷，可奈春归愁转分。","天外何年亲合乐，客中此日又离群。","众芳欲歇伤心见，毕气谁收回首闻。","安得青阳常守帝，微生长许坐氤氲。"]},{"t":"己卯季冬北征就道舟中却寄张公亮明府明府时以新诗索予小序二首 其一","f":"七言律诗","c":["文章千古寸心留，醇饮于君自乳投。","无可淡浓方共远，凭谁欣厌与相酬。","甘棠二载依风雅，玄草三冬忆应求。","颇怪河阳花满县，新梅独许赠行舟。"]},{"t":"己卯季冬北征就道舟中却寄张公亮明府明府时以新诗索予小序二首 其二","f":"七言律诗","c":["性僻耽佳我亦如，流传嗤点共删除。","心期自出寻常表，文力长扶百六初。","未坠于人终不坠，其馀诸子尽堪馀。","风流一代归君手，怅望千秋独起予。"]},{"t":"宋尔孚携斗酒及新诗追至三河同舟竟日夜而别酒醒却望寻韵寄答","f":"七言律诗","c":["清朝一苇共洄从，酒醒云山忽数重。","别意返随东去水，冰心遥映北来峰。","故园日月君长有，宦海波澜世几逢。","回首青青岐岭际，长将颜色照寒松。"]},{"t":"过汀岭","f":"七言律诗","c":["淩晨策路向苍冥，松霭飞烟露草零。","晓色初迎千涧白，征衣遥拂万峰青。","水方划地分江海，山复摩穹别赣汀。","安得身如赤熛怒，南天长有白云扃。"]},{"t":"樟树镇舟中守岁得雨","f":"七言律诗","c":["日月将穷逝水深，家人半聚慰孤心。","市烟交杂居行扰，江雨流连晓暮侵。","玉律吹来需暖候，玄冥歌罢度寒阴。","扁舟到处为乡国，不用思声问越吟。"]},{"t":"庚辰元日溯流剑江","f":"七言律诗","c":["元日光烟湿翠微，意中春在百峰飞。","江流就我舒新色，剑气冲牛发旧辉。","泽鸟连群喧水际，梅花疏影静柴扉。","阳和此岁知多少，独向东风问瘦肥。"]},{"t":"是岁闰王正故首月春至稍迟","f":"七言律诗","c":["东皇首出万民和，千载青阳续汉歌。","水国风光同荡漾，江村谣俗祇婆娑。","勾萌莫叹氤氲浅，解冻方留闰泽多。","极目寒峰瞻太皞，波臣一苇奈春何。"]},{"t":"春日苦雪","f":"七言律诗","c":["日不自明借雪光，雪凭风势敢飞扬。","春和力浅难开岁，阴蹇时深欲稚阳。","望入寒烟俱怒发，吹来汨浪自狂忙。","浮云黪黩真无赖，羁束愁人在水方。"]},{"t":"皖江雪望","f":"七言律诗","c":["春风满月未鸣莺，江雪连朝向客迎。","氲霭尚迟光澹荡，瑞华先启物勾萌。","铺张吴地同梅峤，妆点南天接玉京。","最是行云交望眼，玄黄杂揉共虚清。"]},{"t":"二月二日入山东境","f":"七言律诗","c":["八千潮路及东封，章水吴山凡几重。","北望方知天地远，南车惟向斗枢从。","丘园故梦经年阻，花木春情仲月逢。","为问飘飘何所似，岭云一片出幽峰。"]},{"t":"春分后入东土无日不与诸花共朝夕也","f":"七言律诗","c":["不是憨春不自知，八千川陆总花时。","风光一半销南楫，烟景三分付北骑。","道左中心微我适，枝头偏反更谁思。","独怜烂熳红深处，九十春怀并在兹。"]},{"t":"东阿道中稍见诸山逢迎然陵峦低浅殊不惬春望也","f":"七言律诗","c":["江舟二月伴梅开，征马旬朝逐杏来。","疲路尚馀千里在，孤怀复向数峰堆。","山童未称深春色，地古还兴旷士哀。","屈指东风销几度，空将花事委尘埃。"]},{"t":"午后得雨尘沙稍退诸山作烟云色微觉可人","f":"七言律诗","c":["春深易雨况依山，雨后诸山各静閒。","柳伴歌莺偕洗渴，花同征客共清颜。","尘光稍逊烟光满，野色相兼暮色还。","颇怪陵阿知浅露，黄昏独下白云关。"]},{"t":"初十早渡德州河是午至景州","f":"七言律诗","c":["衣带燕齐百事同，微差物候共尘风。","春光有限难疏放，野色无边自塞充。","四望独疑山水尽，孤心双系日云中。","便劳烟景长为伴，同入金台上苑东。"]},{"t":"十一晚将至商家林漫望","f":"七言律诗","c":["野日荒荒向夕斜，昏尘未肯厌疲车。","春同北至还迟钝，月自东浮尚远遐。","燕草微丝看易没，商林晚色望难赊。","欲知客舍随新柳，独数烟条第几家。"]},{"t":"北地风沙殊少春色春光懒困倍于人矣","f":"七言律诗","c":["辜负三春是此时，愁心百丈绕游丝。","飞花片片畴怜汝，芳草萋萋尚忆谁。","频拂尘颜清一望，强赊山色慰诸思。","长驱冀北真何事，回首江南梦也宜。"]},{"t":"雄邑道中见易水愤胡马之污清流也","f":"七言律诗","c":["萧萧易水表前名，叹息荆卿事未成。","壮士秦廷空浪死，衣冠是日仅偷生。","膻尘遂染寒风色，茄管宁知变徵声。","最下流头经马饮，春来岸草尚欹倾。"]},{"t":"晓发新城喜见西山山色尚在明灭间也","f":"七言律诗","c":["忽扫尘容向郁葱，西山结色有无中。","轻云自在分晴岫，杂树因依合远空。","极目安知春所际，息心堪与日相同。","颇疑朝市喧阗处，独有烟霞出晓风。"]},{"t":"薄暮将至涿鹿诸峰片片可数明月忽自东相映矣","f":"七言律诗","c":["朝夕看山山暂亲，苍玄眼际划然陈。","自缘丘壑关情素，转觉风烟入望新。","随意行云思就客，无心去鸟巧先人。","稍需明镜飞天上，更作千峰一片春。"]},{"t":"季夏六日过徐九一小坐同集者为方肃之周仪伯分得先字二首 其一","f":"七言律诗","c":["触热相烦度午烟，同人不速乃翩翩。","微勤问业归文酒，即事求心寄石泉。","美酝三升方计日，冰壶一片已千年。","颇疑大隐金门地，尚有无怀共葛天。"]},{"t":"季夏六日过徐九一小坐同集者为方肃之周仪伯分得先字二首 其二","f":"七言律诗","c":["同异苔岑又十年，久拚世法与周旋。","人间独傲俱馀子，海内相知祇数贤。","晨夕何甘心外迹，古今谁是踵如肩。","旧闻閒暇披衣者，言笑无厌未偶然。"]},{"t":"杨葵宸宫赞分桐晋府特上捕蝗之章诗以柬之","f":"七言律诗","c":["西山雨过爽飞初，酷暑骄阳今渐除。","綵笔遂干参井气，咨诹还上斗辰居。","周桐遗叶于唐是，汲节便宜想汉如。","便拟姚崇蝗害息，救时一事总君馀。"]},{"t":"葵宸有相念之语复以诗答其意","f":"七言律诗","c":["升沉端不问君平，千里相思叹友生。","自学玄奇甘寂寞，独期清俭减驺声。","六年久令诗书负，八载依稀礼乐明。","愧汝师臣犹鞅掌，于余执戟未全轻。"]},{"t":"会昌登陆山行即目","f":"七言律诗","c":["一月江舟江水穷，清朝逾岭岭云同。","回溪九折看来往，窈谷千林问塞通。","山色淡浓松雨外，泉声深浅草烟中。","要能此地心魂息，甚愧驱驰一远躬。"]},{"t":"修邑志成有不察而斋怒者乃得谤又以有所誉来也感而赋之四首 其一","f":"七言律诗","c":["文献萧萧近百年，敢云千载定斯篇。","于人行直惟三代，自我为正指九天。","非鉴无情应有怒，以汤止沸岂能平。","明知户说终何术，苟信余怀亦所坚。"]},{"t":"修邑志成有不察而斋怒者乃得谤又以有所誉来也感而赋之四首 其二","f":"七言律诗","c":["所期今昔力为担，每至淳漓必再三。","因事而言先史意，誉谁必试众谋参。","文如有阙真余罪，献或无徵亦邑惭。","渺渺中心谁与察，此身已拟怨劳甘。"]},{"t":"修邑志成有不察而斋怒者乃得谤又以有所誉来也感而赋之四首 其三","f":"七言律诗","c":["一任纷纷自吐茹，繇来述史罪知馀。","毛吹何事专无厌，肘掣还疑尚可书。","祇为乡邦章法重，久拚物我怨恩除。","余情止此诸非急，应有空衡鉴拙疏。"]},{"t":"修邑志成有不察而斋怒者乃得谤又以有所誉来也感而赋之四首 其四","f":"七言律诗","c":["要终原始或余知，虽不周今于古师。","稽彼周官图志设，各因小史训言垂。","百年时事终须记，五岭文明尚拟吹。","但使维桑多气色，甘从微阐见瘢疵。"]},{"t":"题双峰寺有怀石山禅师 寺旧在双山。宋末，石山移此地","f":"七言律诗","c":["三百年来旧佛宫，依稀犹记石山翁。","预为法界传灯钵，故入尘寰试色空。","四壁人烟天蚤暮，一湾流水日西东。","镜台菩树今何在，锡杖遥遥觑紫峰。"]},{"t":"西园","f":"七言律诗","c":["閒庭日扫多黄叶，茅屋相参只白云。","乔木风霜依水旧，盆花雨露向人欣。","朝暾破绿帘分艳，夕照还苍壁聚曛。","更有方池通远汉，辉星皎月动波文。"]},{"t":"云岛","f":"七言律诗","c":["所谓伊人在水方，云心不禁野思长。","搆园未亩求千树，取径如林集众芳。","昼霭迷烟生暝色，春华醉景失秋光。","时人漫拟花溪地，我自乾坤一草堂。"]},{"t":"孔有德倡援辽叛卒屠七邑破登城登抚孙元化按兵不动甘为虏也志慨","f":"七言律诗","c":["天骄蠢尔日烽惊，率土臣民雠不轻。","挟纩多年应马革，脱巾一旦起羊羹。","乍传七邑趋风溃，疑说专戎伏地迎。","贷息游魂终一死，尔曹遂作负恩生。"]},{"t":"感时","f":"七言律诗","c":["弄兵赤子岁无停，到处沉迷浑不醒。","牢落官军观望熟，萧条井邑散离经。","八方输挽烟尘塞，万国干戈草木腥。","天地疮痍须一洗，旄头何日坠妖星。"]},{"t":"催科","f":"七言律诗","c":["额外新加旧未蠲，心头肉尽祇空怜。","周黎已见无遗日，汉诏难逢赐半年。","刍牧宁堪平陆后，茧丝翻自晋阳先。","方知此际催科术，能向疮痍觉汝贤。"]},{"t":"经计","f":"七言律诗","c":["也知国计重经边，经计还须问百年。","自古财生应有道，方今民食以为天。","寡盈于岁微当酌，用缓之间或可权。","但使桑麻能尽复，未烦日议赈荒钱。"]},{"t":"偕诸友赏川茶得行字三首 其一","f":"七言律诗","c":["久拚逆旅付春行，春绪孤从纵饮争。","忍向花朝轻骛逐，恰来酒伴喜逢迎。","眼前同尽樽中事，岭外兼逃市上名。","祇此酣情欣暂得，留将欢梦慰浮生。"]},{"t":"偕诸友赏川茶得行字三首 其二","f":"七言律诗","c":["春草时从梦里生，芳晨那复总群英。","玉山自向花丛压，金谷犹惭酒数轻。","屡舞参差还照影，酣呼恼乱夜壶声。","光风淑气随杯转，细雨凝香入夜清。"]},{"t":"偕诸友赏川茶得行字三首 其三","f":"七言律诗","c":["烟景相招座客盈，小园幽赏起谈清。","花容婵媛迟春色，酒意飞扬入夜情。","秉烛非关时序促，兴怀翻觉昔今轻。","却疑当日兰亭事，俛仰犹多感慨生。"]},{"t":"次日薄暮偕诸伴集尔孚浮春涘得言字","f":"七言律诗","c":["晚追春色出东门，有约还过载酒园。","兴入花前同不浅，杯从诗思与俱烦。","全消数局浮更永，赖有馀音止座喧。","此际忙閒因底事，醉醒以外欲何言。"]},{"t":"和宋尔孚悠韵","f":"七言律诗","c":["春光翻借我能游，寻得春情向酒搜。","薄暮晴烟依郭静，清宵流色望郊浮。","千杯痛饮何辞醉，四座歌欢不受愁。","撰就新词还语宋，莫将秋绪向今悠。"]},{"t":"和杨承之分韵","f":"楚辞体","c":["生计应从曲蘖栖，酣情屈指数君齐。","忙閒世故杯中失，迟速风光醉后迷。","竟日相逢谁是主，三春结伴总如泥。","欢来痛饮真何极，留取同心归赋兮。"]},{"t":"夏日陈羹姚吴越望越瀛偕陆山甫谢儒美集饮南岩","f":"七言律诗","c":["岩光初拂爽尘襟，好友相招别有心。","垒石扶云疏碧洞，馀霞敛日反苍林。","晚风微递南薰薄，霄汉轻移北斗深。","留取空冥归窈谷，醉携山月下孤岑。"]},{"t":"五月二日王子龙招看赛龙舟得流字","f":"七言律诗","c":["暑雨蒸沉午梦收，画船声报晚江柔。","披襟风色先迎水，入眼波光远趁舟。","郭外云山容我伴，天中节序诏人游。","清时独许从鸥客，笑傲中央一叶流。"]},{"t":"再用子龙韵","f":"七言律诗","c":["画舟空作叶公看，岂少真龙见者难。","俄觌津南初出剑，翻惊溟北乍飞翰。","卷风雪浪须臾变，带雨云峰咫尺瞒。","独有中流歌笑客，扁舟不动顶奔湍。"]},{"t":"孙蜚莪偕宋尔孚杨承之携酒过从得榴字是日夏尽","f":"七言律诗","c":["壶榼招邀过一丘，凭将君酌反相酬。","未须棋局长消夏，祇畏诗篇早赋秋。","对酒方知朋与好，感时独许醉忘忧。","却惭东老虽贫乐，斋璧犹劳众擘榴。"]},{"t":"题宋尔义亦楼有序","f":"七言律诗","c":["醉卧斯楼三月醒，是中清景梦疑经。","远招云岫千峰碧，近入棉阴一片青。","恐碍烟光低翠牖，为收爽气启霞扃。","秋容此日知尤好，葭露梧风想共泠。"]},{"t":"寄赠冯尔韬给谏二首 其一","f":"七言律诗","c":["棠歌久系召南思，衮职新传仲甫司。","鸣佩应知清响集，谏书莫以圣朝推。","绘图持节真何日，补牍牵裾此一时。","岭外遥将无别绪，山居翘首看封辞。"]},{"t":"寄赠冯尔韬给谏二首 其二","f":"七言律诗","c":["生平日向久要寻，留取孤肠不愧今。","一别自分居索共，有怀倍觉远思深。","榕江梧掖三年梦，丹阙蓬门两地心。","愁入燕天舒望眼，西风回首岭云禁。"]},{"t":"烹茗邀悦则过坐偶及禅理即席口占","f":"七言律诗","c":["漫将儒教释神玄，捉得真如共此天。","但识存存俱不朽，莫因渺渺视诸缘。","一灯在室光时照，万月于川影各圆。","深夜梅香窥座发，谈馀起对自悠然。"]},{"t":"癸酉北征二人偕至茶阳江帆迅速翻怪春风促予离也","f":"七言律诗","c":["万里春风怅别程，征帆喜速此翻惊。","已成家远因亲聚，遂有波滔向我迎。","预拟青山同客舍，早分流水作乡情。","离心何地堪消折，不惮天涯咫尺争。"]},{"t":"舟中别诸亲远媵者","f":"七言律诗","c":["交手舟行难遽分，一杯酒尽反为君。","离筵稠叠离仍讳，别渚潺湲别始闻。","心逐春深燕地草，梦回日落故江云。","临风长恍烟波语，愁绝于今未忍云。"]},{"t":"过永定关","f":"七言律诗","c":["去涧依依鳄渚潨，来云早向凤山蒙。","乡关暌隔兹方始，仆马瘏痡此曷终。","身陟闽峰高最处，眼看潮海近无中。","纵然回首空肠断，蜷局悲怀随地同。"]},{"t":"杨承之以谒虔州王文成祠诗见示用韵","f":"七言律诗","c":["良知一炬百年光，千载岐羊乍识乡。","道在斯文关后死，功馀我武诵维扬。","清朝砺带乾坤壮，圣庙牺樽日月长。","此地歼妖公一事，虔江石齿自襄阳。"]},{"t":"阻风晚泊五云驿","f":"七言律诗","c":["百望西江未肯东，寤怀极浦起劳忡。","来帆却笑征刀涩，风力翻将水性穷。","近远予程俱莫问，流洄川意浑无终。","愁人此际空延伫，日暮烟涛一缆中。"]},{"t":"既而暮雨萧然别有遣予怀者","f":"七言律诗","c":["晚泊悠然逗所思，方春而雨固其时。","流澌桃浪江痕复，烟锁林湾野色披。","定性微闻山泽动，孤怀恰与水云羁。","年来进步甘迂拙，懒向征帆较速迟。"]},{"t":"风泊洪都何非鸣明府榼酒相贻走笔谢之","f":"七言律诗","c":["滕王阁渚冲风日，南浦江头遇子晨。","千顷波汪堪止浪，一方流溯巧从人。","虽迟客步欣留胜，已慰荆怀复饮醇。","便拟鸣榔终却望，敢云击楫是前身。"]},{"t":"连朝如晦廿四早风平舟发披衣起望山月随人矣","f":"七言律诗","c":["解缆声闻促晓看，梦回波色静长干。","浦云半捲川光溢，山月初悬棹影跚。","不有澌流连晚涨，谁冲积气壮春澜。","劳劳纵目孤相问，风雨过馀薄自宽。"]},{"t":"因念澄江时得如此则来舫去刀两俱莫逆固不欲专丐南飙独予帆迅也","f":"七言律诗","c":["游人计远自多端，大块吹同本一般。","定后狂波何处问，澄馀止水可微观。","春江此际还如练，山月于时已在竿。","安得诸川同是刻，来舟无涩去舟安。"]},{"t":"过采石吊李白墓","f":"七言律诗","c":["苍松渺渺谪仙坟，采石矶头草木芬。","此地江山空识李，唐朝内外不容君。","词林气魄青莲重，诗酒风流白水分。","闻道骑鲸非复是，春峰箕尾伫遥氛。"]},{"t":"恭谒孝陵二首 其一","f":"七言律诗","c":["波臣万里逐春风，稽首天灵拜紫嵩。","绕阙祥云时献瑞，环庭翠柏日摩穹。","踞蟠象合诸峰拱，芊郁年多晓气笼。","入眼兴怀歌膴膴，瓜绵不但数岐丰。"]},{"t":"恭谒孝陵二首 其二","f":"七言律诗","c":["象纬霄寒挂晓峰，龙湖回首怅攀从。","夷膻扫出千王世，明运长开百代宗。","天意亦钟成鼎处，臣生虽晚奕云逢。","冈陵气色今多美，时际中兴自郁冲。"]},{"t":"雨日李小湾宗伯召饮寅齐暮辞风舆口占为谢","f":"七言律诗","c":["角巾折雨入龙门，李郭当年意可论。","湿径穿青依翠幕，疏烟流润上青樽。","六朝春色因君转，五岭云心以聚温。","别去醇情昏霭是，舆风虽剧不惊魂。"]},{"t":"将至滁州途中得雨","f":"七言律诗","c":["春此时归我亦行，归行何事异其程。","岐途柳倦难分绪，落日鹃催别作声。","扑面烟风回首罢，浥尘轻雨近峰生。","苍苍迷霭昏舆外，祇许前山入望横。"]},{"t":"晓发过关山","f":"七言律诗","c":["雨后云光湿晓星，朝来风意漠芳坰。","征衣已带前山色，春路还留夹道馨。","花气归从莺语碎，林烟散作马头青。","古来极目伤心处，况复惊时此地经。"]},{"t":"过桃山岳武穆庙","f":"七言律诗","c":["越水残肤旧已寻，徐山祠庙此相临。","循途未敢趋风谒，感昔难将涕雨禁。","父老遮边当日话，冤臣下圄片时心。","寻常一死关夷夏，不尽孤丹泪古今。"]},{"t":"有感诸同年","f":"七言律诗","c":["驱驰忆昔此中归，联袂诸君剖上畿。","燕鲁齐吴三叠尽，东西南北五年违。","歌城琴父双寥寂，为陆辞丘半是非。","马上询人惊欲泪，故堤柳色共依依。"]},{"t":"望阙","f":"七言律诗","c":["燕云咫尺望中跚，未息征尘已意安。","眼到西山朝气出，梦回南岭晓魂残。","舟车地尽风光忆，春夏程争日月看。","万里见闻今默数，诸缘返计漠无端。"]},{"t":"解柱明中翰见招草桥山庄是日孙大器管泰阶曹允大黄改庵刘胤平同其弟拙存俱集","f":"七言律诗","c":["草桥园涧备层阴，驾水开筵万木森。","撤暑流情浮醴动，窥樽云色落杯深。","兰亭禊罢春为夏，金谷诗成古复今。","拚得扶光西汜促，主人终宴尚馀心。"]},{"t":"是日诸子肩舆余独乘马醉归辄供笑谑诗以解嘲","f":"七言律诗","c":["红尘拨尽别为天，只此清樽不易然。","暑鸟依亭惊客至，游鱼仰沫听音前。","欢来临涧觞飞羽，醉后扶鞍马似船。","莫讶知章狂态出，羸君柳絮拂归鞯。"]},{"t":"立秋晓对","f":"七言律诗","c":["朝看一叶下凉襟，昨夜商飔初动林。","周史空悬三日令，楚臣已迫四时心。","新来乳雁横霄影，老尽鸣蝉咽露音。","始觉朝清秋易肃，西郊不用更迎金。"]},{"t":"秋馆读书","f":"七言律诗","c":["金风落响出西山，雨过郊烟度曙关。","鬓欲惊吹来坠叶，胸能收爽去蒸颜。","槐云午结冰衙盖，葭露宵团玉水湾。","何幸一官无暑气，秋声先向夜藜还。"]},{"t":"赋得秋凉入郊墟 馆课 其一","f":"七言律诗","c":["京华不碍石泉踪，为爱秋初野外容。","微变原情因雨过，轻凋林色尚云封。","草芳欲怨鹈先出，露白翻思人可从。","此际清怀堪四掬，未须眉爽倩西峰。"]},{"t":"赋得秋凉入郊墟 馆课 其二","f":"七言律诗","c":["草际轻烟云际阴，萧萧秋望自秋吟。","也知赢肃分天地，无奈登临尽古今。","野意平分悲客气，时光同出达行心。","何当选厉依兹节，一趁西飘扫若林。"]},{"t":"渴愁","f":"七言律诗","c":["西杓挹露斗浆浮，多病相如自渴愁。","无好无能时倚柱，独清独醒半行游。","图书以外他何物，神骨之间或似秋。","却叹凄其絺绤际，缁衣敝改孰为谋。"]},{"t":"揽辔","f":"七言律诗","c":["栖栖马背自清狂，六载冰衙弟子行。","玉佩羞看门下铗，朱衣竞哂酒炉鹴。","已怜梅摽今三实，忽见葭苍此一方。","揽辔逍遥歌九辨，愿言思古莫心伤。"]},{"t":"方肃之得转假附来使寄怀","f":"七言律诗","c":["劳劳尘足忽秋惊，羁旅燕天怅友生。","懒骨如余羞径捷，素心于子觉名轻。","独留文史山中富，正想须眉江上清。","四载为期今复订，梧风葭露忆初迎。"]},{"t":"陈子仪初入都相过小酌是刻得雨","f":"七言律诗","c":["春风别后满秋思，在水苍蒹五度丝。","忽报音容欢执手，顿忘主客急衔卮。","行云旧是樽前物，快雨初倾酒下时。","君去屋梁颜色照，更生明月欲催诗。"]},{"t":"封荆将就道子仪宜以诗祖余也而索余己巳赠行之作因复以诗答之","f":"七言律诗","c":["别君犹索祖君诗，聚散随缘总莫期。","南北岐途千载泪，漳潮衣带一方思。","凭兹别意难言处，正想离情无尽时。","和汝唱予俱一况，劳劳休作渭城词。"]},{"t":"封荆就道以仲夏九日","f":"七言律诗","c":["征车晓夕似行云，野色峰容近远醺。","出郭何心初一啸，兴怀随地入孤闻。","岂将词赋销长日，正想咨诹答圣君。","此际悠悠思不禁，自怜朝野望中分。"]},{"t":"忆去岁北趋九歌之作感而有述","f":"七言律诗","c":["去岁吴江续楚骚，无端悲往自心忉。","明知褊性宜閒散，幸际明时逐队曹。","偃息翻惭何补报，驱驰敢自谓贤劳。","恭承嘉命荆封日，遥望湘流吊汨皋。"]},{"t":"暑尘道中回首有感之作","f":"七言律诗","c":["朱宿衔烟朝露晞，星车破暑此时归。","飘尘北拥悲鸿渡，积翳南昏泣燕飞。","自叹泥躬随蹇蹇，翻愁迷路滞騑騑。","燕台回首晴空蔽，不但征人面目非。"]},{"t":"岐路","f":"七言律诗","c":["粤地燕天入思迷，遂令行与住皆疑。","时怀靡及迟周道，夜梦频惊促晓骑。","南北况逢羊屡失，去来惟见鸟争窥。","一身岐路今遑恤，四海迷津那可知。"]},{"t":"秋心","f":"七言律诗","c":["我本青山尘外侣，自从逐队效驱驰。","频年客路长销夏，到处人言亟失时。","入眼沧桑知几变，举头云物正堪思。","晓来征陌轻阴覆，一片秋心细雨吹。"]},{"t":"入徐界望黄河","f":"七言律诗","c":["黄河天际落徐封，晓气迎车净客容。","云接浮光生渺汉，山含远润入幽峰。","西来万里流何极，北上千帆影自重。","却叹寻源非汉使，会应东海问朝宗。"]},{"t":"季夏买舟白水将赴楚蕲阻雨未发却寄仁和宋尔孚明府","f":"七言律诗","c":["雨涨三山滞客津，吴江夜半越潮沦。","遥知宋渡新来岁，再见苏堤旧日春。","身在峰飞观折水，心如湖止任游人。","扁舟几度思洄溯，无那秋风欲楚蘋。"]},{"t":"将至采石守风夜眺见江流四拥一缆悠然不禁烟波之感","f":"七言律诗","c":["江意潇然欲放秋，似因客绪倍添流。","遥看绿嶂涵牛渚，忽望青潮没鹭洲。","月浦光遥昏缆带，星河彩曳夜桅收。","不堪久对商飔发，别入枫林一段愁。"]},{"t":"孟秋之朔发金陵旬日始至芜湖","f":"七言律诗","c":["百里芜湖十日程，退寻进尺较平生。","与波上下非吾事，阻道流洄是客情。","击楫徒兴当日舞，布帆难借此宵横。","永怀不寐飞江月，洗却千愁照独清。"]},{"t":"舟夜守立秋 交节以十三夜亥二刻","f":"七言律诗","c":["愁客思归坐晚风，梦回秋色度江枫。","吹来雁影澄波外，咽破蝉音碧树中。","斜月西藏飞爽露，行云四敛肃高空。","祇因一叶伤心见，摇落千年悲气同。"]},{"t":"十五早得雨晓对诸山","f":"七言律诗","c":["雨洗秋颜碧嶂重，江浮客意澹相宜。","生平丘壑缘如素，游倦烟霞望亦私。","极目云深采药处，惊心露白溯洄时。","遥怜故岭千峰色，翻令伊人在水思。"]},{"t":"舟滞大通得同使宋今础书知至广济相需多日","f":"七言律诗","c":["经时予跂日心忉，一苇难航自郁陶。","无那三秋销客路，遥知九辨入君骚。","登山临水方悲远，暮雨朝云复赋高。","我亦离歌归楚调，安知清响发江涛。"]},{"t":"来札有一苇恣泊江鱼尝新之语乃余舟中景则大不然也因移就小舟极夜之力至皖江拟即就道兼赴先以诗谢","f":"七言律诗","c":["藜火当年共起居，皇华谁令异舟车。","自从江汉迎秋日，正想云山拥节初。","敢为思鲈兴我叹，恰因烹鲤得君书。","驰心夜半飞蕲道，流恨朝来积皖潴。"]},{"t":"舍棹兼程以不得即就今础为恨","f":"七言律诗","c":["朝来舍棹策星车，夙夜王程敢自如。","晓云随地林烟积，宵月悬山野态虚。","几度怀人歌道左，忽疑见子在衡舆。","遥遥楚甸诸峰外，遵路何时始执袪。"]},{"t":"今础久寓广济相需筮诸关圣得此时宾主欢相得他日王侯却并肩之语筮者方旋而余继至相晤出此竞叹灵奇因各诗以纪之","f":"七言律诗","c":["一自藜灯共草玄，六年周道复联翩。","出门喜见同人益，获上应思信友先。","祇为骥程堪附尾，却惭驽足屡加鞭。","嘤鸣此日关神听，莫道逢君只世缘。"]},{"t":"偶阅太白集因商李杜同异","f":"七言律诗","c":["杜子沉雄李俊扬，或仙或圣总难方。","惊风泣鬼真无敌，破卷如神孰可当。","江汉分流终自合，云霞异彩转相章。","始知大雅无偏伯，今古斯文共一王。"]},{"t":"与今础至蕲春同话一署因及旧事州茂才袁道长兄弟翩然相顾各以诗章见赠走笔步韵答其一","f":"七言律诗","c":["因谈旧事各空书，犹幸皇华出有车。","驹絷谁从之子屋，凤歌频接楚狂舆。","自怜今日双星使，同是当年太乙儒。","不谓逢君倾盖语，南金双锡满征裾。"]},{"t":"孟秋廿八日册封礼成恭纪","f":"七言律诗","c":["帝命敦庸二礼郎，双衔节册下蕲阳。","南藩服壮雄三楚，翼井星临灿七襄。","桐剪清秋新露渥，茅封广汉旧流长。","繇来宝玉分周室，此日亲亲在一堂。"]},{"t":"荆王锡宴兼索诗篇应教启谢","f":"七言律诗","c":["恭随使节觏衣裳，私觌仍歌既醉章。","麟岫晴云依殿绕，金糊秋爽拂筵光。","未徵雪赋梁园客，已附游诗邺下行。","此去乘槎归海外，犹疑远汉露零瀼。"]},{"t":"偕今础谒樊山王留酌清轩更有雨湖之约","f":"七言律诗","c":["翛然相造便杯同，竹径松阶半榻中。","草色翻庭经细雨，歌声拂树入流风。","未知折角人争效，更有披襟独辨雄。","此夕隆欢真不意，尚期一苇兴何穷。"]},{"t":"是夕饶黄山侍御邀同今础酌南楼共望雨湖","f":"七言律诗","c":["南楼纵目便湖山，犹似扁舟碧渚间。","电里波光时一见，雨过秋色夜初还。","幸逢绣史携新赏，遂使金沙识故颜。","主意未终客未倦，何妨秉烛对流间。"]},{"t":"四日发蕲阳有感","f":"七言律诗","c":["此地空怀屈宋音，无缘凭吊怅孤心。","平原十日徒相款，咫尺三湘未可寻。","游远依然同迫厄，悲秋何处问登临。","祇怜入楚多骚怨，况复乡思动越吟。"]},{"t":"是夕泊垄坪镇舟眺","f":"七言律诗","c":["广汉初方忽仲秋，生涯到处祇孤舟。","露从葭满归遥水，风自蘋吹入近洲。","十日黄蕲无胜览，深更独苇愧东流。","乡心漫有丹砂梦，怀古终输赤壁游。"]},{"t":"见月落秋空云敛波出悠然有感","f":"七言律诗","c":["从来不识汉江秋，湛湛枫林寄古愁。","落日扁舟依绿屿，清宵万壑抱沧流。","月方一见思其满，云自初生看及收。","遂有波光迎夜色，因之凄绪发蘋洲。"]},{"t":"西山秋水 初八日南浦登舟","f":"七言律诗","c":["携来吴楚百川秋，并入西江一水流。","江水流秋秋欲半，秋江对客客多愁。","蝉如有恨藏朝树，鸥自无心出暮洲。","莫道归帆朝暮迫，月明江远倍悠悠。"]},{"t":"急雨","f":"七言律诗","c":["秋云犹作夏峰奇，急雨衔山过水湄。","长浦斜阳从望失，夹堤流电向襟麾。","丹林绿霭初回互，碧野澄川忽骤驰。","此际孤篷依落叶，萧萧一任晚风吹。"]},{"t":"临流","f":"七言律诗","c":["清宵悲客独舟看，望入星槎机石寒。","金斗浆浮疑在水，银河影泻似奔湍。","浅深夜色依愁见，近远波声出绪漫。","莫是征人归意懒，临流孤眺便相安。"]},{"t":"穷川","f":"七言律诗","c":["日抱孤情入逝川，维舟夜对得其先。","石倾雨过蘋中水，溪泻云深树里泉。","素影摇秋同荡漾，轻阴落夜共洄漩。","繇来此意何人会，始信如斯即我缘。"]},{"t":"中秋夜泊界亭村雨望","f":"七言律诗","c":["秋中孤缆一流湾，明月相愁闭远山。","落木疏枝云黯淡，芳汀细草雨潺湲。","独怜团扇因寒置，忽忆浮槎自海还。","何事蟾光终畏客，却教萤火熠离颜。"]},{"t":"人日寄谢儒美兼招赴宛在堂也","f":"七言律诗","c":["春朝梦子生池草，人日题诗附陇梅。","烟景当前迷独往，光风入抱逐谁来。","鸣嘤一鸟原求和，偏反诸花莫漫猜。","若使相思能命驾，床头新酿恰初醅。"]},{"t":"趋燕在即值儒美有五羊之行驰书言别诗以复之","f":"七言律诗","c":["衡心十载日相求，相视相期物外游。","忽听羊峰催折屐，空馀鳄渚忆同舟。","岭梅落尽劳乡梦，江杏开时结旅愁。","两地云天堪一泪，春风万里倍离忧。"]},{"t":"郡中别馆未为客也而客况倍之长宵不寐因之诗之","f":"七言律诗","c":["一馆萧然予客凉，似疑客惯未全尝。","晚云自作秋容远，落烬相依夜息长。","酒罢细闻诸籁寂，吟成出见列星光。","漫劳久对深寒绪，却令多愁只独商。"]},{"t":"暮春北征舟中寄题宋尔义荔馆酬灯夜见邀诗债也","f":"七言律诗","c":["游子离群感故游，名园烟景令回头。","春山选胜堪持赠，灯夜风光惜未酬。","漫忆千花明晓洞，因思片月挂宵楼。","朝来把笔题前句，无数行云带远眸。"]},{"t":"泊采石步谒李供奉祠 其一","f":"七言律诗","c":["日落沧江止问津，停桡独访谪仙人。","风骚此日应谁主，诗酒当年别有神。","明月胸怀随晓夜，澄江颜色几秋春。","文心世法今如古，翘首于君欲具陈。"]},{"t":"泊采石步谒李供奉祠 其二","f":"七言律诗","c":["试观秀谷与明流，今古文章乃独留。","水不波澜将易测，山非云水想难幽。","两间灏淑平分此，百代高深遂莫俦。","我向馀风思大雅，先生犹许水山求。"]},{"t":"金陵舟次五月五日","f":"七言律诗","c":["榴花眼际照江津，兰浴天中净客身。","白水蟠龙空在望，彩符艾虎不须陈。","五丝自续他乡命，万里谁怜于役人。","卮酒临风招屈子，孤舟吊古倍伤神。"]},{"t":"将渡江就道过刘映薇寓次小集","f":"七言律诗","c":["蓬飞俱作异乡身，能酌清樽感故人。","入世孤容分我拙，论心端合向君真。","各言此子宜丘壑，同叹于时少筏津。","酒醒明朝仍两地，驰驱漂泊总沾巾。"]},{"t":"渡徐州河","f":"七言律诗","c":["滔滔一水迅流潺，激激孤城楗石关。","地不得宁黄土泛，人求所止白云攀。","遥天低树全归水，近野平芜半没山。","有客横波扬素楫，寄言河伯念民艰。"]},{"t":"午车剧尘心眼交颓过任丘见城下红莲袅袅袭人喜而咏之","f":"七言律诗","c":["藕花香逐客车过，暂拨尘容向泽坡。","霞彩红分晴日艳，露房粉坠午光和。","城阴半覆轻菲下，岩草横将细萼拖。","恰是怀人依道左，临风几度醉颜酡。"]},{"t":"以诗言诗送王觉斯学士之南掌院二首 其一","f":"七言律诗","c":["今之作者竞炎炎，伪体新辞日就纤。","声不归情何所本，大而能则独君兼。","经时宋室双文正，变论开皇一仲淹。","自愧谈心初执手，骊歌率尔向鸿渐。"]},{"t":"以诗言诗送王觉斯学士之南掌院二首 其二","f":"七言律诗","c":["明文郁郁大经垂，群杰相雄复自师。","举世言风因失雅，何人述史乃徵诗。","东西旧识兰台赋，南北新瞻学士仪。","此去六朝金粉地，再三终始问兴衰。"]},{"t":"送冯留仙备兵苏松","f":"七言律诗","c":["三秋雁影看朝移，昨夜骊声忽助悲。","纵使心同肩自比，骤然膺牉背先知。","因今惜别倾前绪，以后相酬但久期。","眼望东南揆奋日，思君樽俎尚能之。"]},{"t":"细柳营 其一","f":"七言律诗","c":["高皇逃楚渡河驰，使者犹收信耳师。","此际徐行宽介胄，顿令坚壁退胡骑。","劳军以礼非徒试，命将于权必便宜。","故垒年来营柳在，春深还拂汉旌旗。"]},{"t":"细柳营 其二","f":"七言律诗","c":["阃外争传细柳踪，纷纷棘霸漫相逢。","备胡何事堪忘守，节制之师岂但攻。","当日不闻天子诏，千秋犹识汉军容。","征麾乍指旄头落，上郡云中忽罢烽。"]},{"t":"迎春","f":"七言律诗","c":["乡心撩乱入春先，客里从春六度然。","历历风云同记睹，悠悠日月异周旋。","销磨旅腊增梅恨，倾盖京华问柳缘。","蚤晚烟光人世满，不知绮语向谁传。"]},{"t":"除夕前一日立春 其一","f":"七言律诗","c":["家园春满百花先，旅馆春来冻柳边。","淑气初从皞帝转，寒威犹向土牛牵。","为留一腊归残岁，却换三冬作旧年。","此际相逢如故友，乡怀细语白云前。"]},{"t":"除夕前一日立春 其二","f":"七言律诗","c":["看春北地见花难，把酒因人作菜盘。","剪出宫枝誇綵燕，移来幡胜愧郎官。","时当水木互乘代，律动葭莩异暖寒。","周史多年空故事，汉书何日涣新观。"]},{"t":"祫祭陪祀四首 其一","f":"七言律诗","c":["嗣岁之朝祫祭行，丰年欲向孔皆迎。","繇来肇祀能无悔，直到雍歌见靡争。","穆穆曾孙相越对，皇皇多士介昭明。","在庭柷敔俱和肃，祖德维人不但声。"]},{"t":"祫祭陪祀四首 其二","f":"七言律诗","c":["于穆高皇骏有声，嗣文成祖肇禋行。","一时帝子俱廊配，十七元臣允国祯。","问礼欲知因每事，记功思作不徒名。","即今多难追前烈，访落何人续庙清。"]},{"t":"祫祭陪祀四首 其三","f":"七言律诗","c":["首辟华夷出会清，重贻镐雒配于京。","开天远驾千王德，继序新昭二祖名。","指掌犹求烝禘说，闻声兼得武韶情。","小臣夙夜思公在，为赋时周叶大明。"]},{"t":"祫祭陪祀四首 其四","f":"七言律诗","c":["单心我主日明明，夙夜维基受有成。","在庙方将纯德显，于时端合笃恭平。","畴为骍角当牺选，一任桃虫自鸟惊。","嗟尔戎功能永念，虽歌小毖亦和鸣。"]},{"t":"对西山因忆昨游","f":"七言律诗","c":["西山积爽不轻吹，日抱秋光隐翠微。","定性于朝容一见，玄心何地可孤违。","昨游岩壑经云闭，今忆松盘羡鸟飞。","欲理前盟相告语，烟霞久已择人归。"]},{"t":"趋署回闭户有所思","f":"七言律诗","c":["兰署潇然独论文，公馀闭户似离群。","官惟宾客言相与，心及乡邦梦已分。","溟海秋澄千里月，罗浮春发百峰云。","玄思一息堪来往，今古馀情付落曛。"]},{"t":"除夕二首 其一","f":"七言律诗","c":["平分两岁一宵中，愿得驱邪五尺筒。","旅灶何劳虚耗照，国傩应见害除终。","丰年鱼梦因三雪，阳日庚鸣俟晓风。","坐守椒盘孤致祝，伫看簇律太皞同。"]},{"t":"除夕二首 其二","f":"七言律诗","c":["寒灯守岁客相宜，不打灰堆不卖痴。","禳厌聪明刬旧误，粪除口舌待新禧。","天街火静沉香夜，邻舍声喧爆竹时。","自向冰池呵冻管，何须暖热一盆吹。"]},{"t":"丙子年起元日早朝","f":"七言律诗","c":["千门淑气向青阳，一望庭煇上紫光。","自合风云烟阙下，最浮葱郁瑞楼央。","臣人率土同三祝，圣主深宫念八方。","殊锡上卿能虎拜，独惭微贱点鹓行。"]},{"t":"朝回自叹","f":"七言律诗","c":["我生三十姓名沉，而立无能岁转侵。","气及方刚多可戒，游初欲遂少从心。","眼前节序蹉跎甚，身外乾坤愧恧深。","抗疏传经因底事，匡衡刘向古非今。"]},{"t":"人日邹石可民部招同林紫涛侍御夜集","f":"七言律诗","c":["天涯聚首是同乡，人日因君尽一觞。","且喜三星依日下，安知百事向人忙。","镂金剪綵谁誇胜，煮菜屠苏亦共尝。","努力樽前深夜语，明年此会莫相忘。"]},{"t":"紫涛频以牙痛告归若有所期诗中及之","f":"七言律诗","c":["密坐深杯兴转赊，盘蔬再整不禁牙。","多情西月低还照，解事东风暖暂加。","有客床头倾柏叶，何人檐额点梅花。","时逢贴帐难辜负，休把芳邻当酒家。"]},{"t":"送林紫涛巡按宣大三首 其一","f":"七言律诗","c":["自向天涯比德邻，相看宦海异今人。","非缘寡合联心迹，似倍文交结道神。","目极云鸿伤两地，情先谷鸟恋馀春。","忘君持斧思投辖，未了深言欲具陈。"]},{"t":"送林紫涛巡按宣大三首 其二","f":"七言律诗","c":["霜简淩春出帝京，西人翘北指云旌。","天连毕尾分躔野，地界华夷合使星。","自古岩关须命世，因君毅骨静骄兵。","便使乌台归画阁，祇今龙塞望烟清。"]},{"t":"送林紫涛巡按宣大三首 其三","f":"七言律诗","c":["大梁兵气下狼墩，小丑凭陵杂雁门。","惯帅虚传李牧野，夸生漫议赵充屯。","乌云结势迎骢马，玉帐随身出绣幡。","送子不须秦策赠，凭君铁面驭驹辕。"]},{"t":"步韵和汪皖公计部扇头近作","f":"七言律诗","c":["今日逢君又一时，风云世事不胜知。","人言宦海皆名利，我法前程但酒诗。","总合浮沉看梦境，微分劳逸问心期。","岂无白眼双能变，赖有孤肠一片支。"]},{"t":"即事有感仍呈皖公计部","f":"七言律诗","c":["财生天地未应殚，持算君民合总盘。","肉食深谋捐俸最，茧丝报政考功难。","耕屯故议盈千牍，租役新条罄百端。","头会佳名仍手实，疮医何术免心剜。"]},{"t":"自问","f":"七言律诗","c":["巧拙分心亦易知，屈伸同术遂难思。","本无傲骨时如傲，自有痴肠日就痴。","凭此方人非复是，忽然问我信还疑。","看来世路宜孤往，梦入虚舟尚远期。"]},{"t":"孟秋四日承命典中州乡闱恭纪","f":"七言律诗","c":["巍巍五岳独高嵩，下有黄河万里同。","川岳半分人地责，图书全表圣贤功。","其间名世关今古，此日观成见始终。","昭代薪槱乡举盛，斯文得与乃天中。"]},{"t":"共事为黄赞伯铨部赞伯我友有同心矣","f":"七言律诗","c":["黄郭当年一代师，敢将名姓强追随。","澄清淆浊君应否，谠论危言我尚为。","身入风云观错变，心先时地力推移。","斯文未坠天中在，吾道前行即后规。"]},{"t":"与赞伯有商","f":"七言律诗","c":["一自文心落众缘，狂澜百派任波漩。","敝衰八代当年甚，刑法诸家近日贤。","汉世治安空策论，宋朝君德忽经筵。","浮言口实真堪唾，力洗儒羞或共肩。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其一","f":"七言律诗","c":["星车夕发遂河干，来往征途异暑寒。","城野秋残闻见改，堂阶地隔怨咨难。","郑图欲献须多绘，贾策方成仰乙观。","昧死臣言终出位，循躬九载日瘝官。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其二","f":"七言律诗","c":["忧时注将总偏词，昧昧何如一个思。","淮蔡深谋全倚度，西人寒胆独称琦。","公孙阿世终蒙落，司马闻边始戒夷。","自下邦家分利殆，祇今中外问安危。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其三","f":"七言律诗","c":["丈夫投笔计封侯，孺子逢桥已遇留。","飞食莫凭封万相，坐帷须拟决千筹。","清宵几对风云色，何日能忘天地忧。","未扫匈胡终负国，忍看辽土竟沦酋。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其四","f":"七言律诗","c":["千载筹胡指顾中，清宵读史念车攻。","大原薄伐中兴伟，沙漠深藏远略雄。","唾手辽云心未已，系缨北阙事堪同。","古今大义容臣举，十万横行报乃公。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其五","f":"七言律诗","c":["王制宜人不厌奇，诸臣陈力已心驰。","簿书期满观中秘，弼教功成望百揆。","钱谷兵刑非相事，股肱耳目有新司。","即今师济盈中外，可许登庸答帝咨。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其六","f":"七言律诗","c":["宵衣明主值多难，朝市相逢策治安。","止辇求言劳汉帝，诘戎立政想周官。","处囊一遂誇锥脱，投笔千人说剑寒。","六月南师今又老，何年西顾始中宽。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其七","f":"七言律诗","c":["足兵足食总难齐，骄子未欢饥子携。","不惜琼林收散卒，岂无膏泽下残黎。","牛羊视久须刍牧，将帅思深尚鼓鼙。","事急但求兵革利，应知民志险山溪。"]},{"t":"既渡河车中即事以新旧见闻作古今愿怀诗八首 其八","f":"七言律诗","c":["文武途分或掎轻，封疆事急且观兵。","公侯久废干城选，军旅初因俎豆行。","六艺成名先执射，七书传塾已为经。","从兹儒效兼安攘，不是皇心喜纵横。"]},{"t":"秋辨九首 其一 陷昌震陵","f":"七言律诗","c":["小丑饥来望饱归，中枢上策总依违。","狼堆晓夕添红焰，龙鼎风尘出翠微。","选将徵兵仍故檄，全师守境便神机。","三辅残黎何地免，诸陵端藉在天威。"]},{"t":"秋辨九首 其二 宣镇捷功","f":"七言律诗","c":["降丁掩尽便称奴，文武同时竞绩肤。","何处奔狼将弭耳，依关突豕忽同驱。","尚方再锡今司马，郊垒应羞古大夫。","坚卧营深终不起，观容使至好相呼。"]},{"t":"秋辨九首 其三 辽帅归镇","f":"七言律诗","c":["岁益金钱月选丁，捣巢出塞计横行。","东西一任夷戎合，南北多方主客营。","量敌为军终后战，潜师有地肯先声。","如云千骑归朝策，何日重关止夜惊。"]},{"t":"秋辨九首 其四 枢督交病","f":"七言律诗","c":["初秋塞马已先驰，晓燧相传杂信疑。","阃外枢中交卧理，霸门棘上总儿嬉。","云深老阵屯关险，鼓竭衰军望阙疲。","屈指封狼贪志满，奴归应是捷闻时。"]},{"t":"秋辨九首 其五 倚将将将","f":"七言律诗","c":["时危倚将付全疆，节制虚名军政傍。","署状谁忧骄蹇变，处堂端合煦安常。","相传战守无中策，所仰威灵独尚方。","十万从今凭将将，六师视古日张皇。"]},{"t":"秋辨九首 其六 救民收民","f":"七言律诗","c":["八载腥尘复向秋，何年桑土未阴求。","丸泥忽坠谁封守，一鼓齐歼有秘筹。","旧养苍黎难死救，新归士女苟生偷。","相看满地鳏孤遍，独赖如天圣主收。"]},{"t":"秋辨九首 其七 陵疆功罪","f":"七言律诗","c":["误国刑章首不忠，陵疆何地可欺蒙。","先时已失权威爱，后事犹然饰罪功。","政典千年难日异，天颜咫尺敢雷同。","即今中外全躯得，退食清朝亦省躬。"]},{"t":"秋辨九首 其八 朝天闻乐","f":"七言律诗","c":["马首征云达帝京，朝天有日念馀生。","西山积霭浮朝霁，大角妖氛落夜星。","天道及期苗命格，秋风辞塞汉关清。","胡笳渐远闻三捷，夔乐依然奏九成。"]},{"t":"秋辨九首 其九 望阙思乡","f":"七言律诗","c":["西风去路马蹄遥，望阙归来数夕朝。","鹈鴂鸣馀窗草歇，蟪蛄声急井梧飘。","水山在目犹行远，湖海关心欲懒朝。","九辨歌成悲气迫，三秋思已故山招。"]},{"t":"既作九辨诗因以自解","f":"七言律诗","c":["三秋纪事未应欺，寸管低徊几自疑。","举国深谋惟倖免，微臣同疚敢痴迷。","官名礼乐容诗史，志在春秋独我师。","知罪从人真莫问，危言圣世尚当为。"]},{"t":"饮王子龙斋达旦冒雨而归连日滂沱不已秋夕既七银河黯然独坐偶成遣怀书谢","f":"七言律诗","c":["秋声酒后梦回初，风雨驱人自索居。","虫网时飏昏树霭，萤辉忽映夜窗虚。","印苔屐静孤怀滞，悬榻人遥积绪疏。","欲望银河迷五色，双星云里竟何如。"]},{"t":"送王子龙广文公车","f":"七言律诗","c":["驰烟溯水及春阑，花浪轻舟似羽翰。","九万鲲鹏因海运，八千车马始江干。","图书满橐随身易，弧矢关心忆路难。","此去垂天凭健翼，一毡一蓿岂君官。"]},{"t":"送辜端伯给谏使竣还朝三首 其一","f":"七言律诗","c":["四牡騑騑莫问程，皇华兼向采薇赓。","春风到日燕尘乱，使节过时凤水清。","万里流图堪远绘，中原杂种岂终横。","知君玉帐随身去，遮莫旄头影自倾。"]},{"t":"送辜端伯给谏使竣还朝三首 其二","f":"七言律诗","c":["大角缠兵晓燧浮，同人相视向戈矛。","独劳原隰歌王事，谁任中边负国雠。","犹豫狐疑成底用，凤观虎视合先忧。","韩江极目燕云杳，不尽离心共北流。"]},{"t":"送辜端伯给谏使竣还朝三首 其三","f":"七言律诗","c":["南北心同自比肩，幽人应许遂林泉。","二三才俊皆清要，左右封弹各后先。","日犯龙鳞依主圣，时当天步赖群贤。","若逢姚子与冯父，为道升沉共勉旃。"]},{"t":"九日清斋独坐","f":"七言律诗","c":["一室萧然秋在中，碧溪流水醮篱东。","佩萸泛菊追清事，戏马游龙止霸风。","只有文心从露白，任教庭叶赴霜红。","真成独对看摇落，九日还如九辨同。"]},{"t":"九日同诸公登涵元塔四首塔之七层 初峻工于是日 其一","f":"七言律诗","c":["高标今始出层穹，十载观成见有终。","流峙分形归系干，云霄一气表空濛。","凭虚欲御飞纶囷，入远多佳起郁葱。","自是南天擎柱立，何人独许奠鳌功。"]},{"t":"九日同诸公登涵元塔四首塔之七层 初峻工于是日 其二","f":"七言律诗","c":["双溪奔注百川随，一砥中流倩客龟。","灵杰真关人地力，经营合借鬼神为。","千年自我增孤耸，八代如韩起溺衰。","沧海明珠应可见，绿图幡簿未全欺。"]},{"t":"九日同诸公登涵元塔四首塔之七层 初峻工于是日 其三","f":"七言律诗","c":["去天三百似依稀，云构中霄始合围。","真气盘空龙象喜，文光首出斗牛依。","烟峰下上随登降，倒景苍茫在指挥。","久立萧然群动息，因高独使万殊归。"]},{"t":"九日同诸公登涵元塔四首塔之七层 初峻工于是日 其四","f":"七言律诗","c":["独顶孤峰柱海门，功归造化轴归坤。","六牛四女互经纬，东渤南溟共柢根。","禨祲遥占城市色，盈虚频见汐潮痕。","冥搜物象如环掌，心目应从万古论。"]},{"t":"题为九日登塔四作皆塔诗未及九日盖所重在塔也然既已九日安可无此作以补之","f":"七言律诗","c":["烟凝暮紫夕光移，秋意因高见远吹。","何处风囊来舞激，翻惊羲驭在鞭箠。","登临不尽今人感，眺听还多往事疑。","安得淩云皆赋手，漫劳落帽共相嗤。"]},{"t":"富沙较士即事","f":"七言律诗","c":["棘院潇然午漏沉，青青诸子见文心。","篇中风雨看飞动，笔底波澜问浅深。","遥忆花砖同缓步，可堪铃阁独怀音。","三三六六来清梦，能信余思第几岑。"]},{"t":"怀富沙诸子","f":"七言律诗","c":["门外青山尽我徒，一峰如意百峰俱。","从兹石鼓云难秘，遂有生刍玉未殊。","雪调于人终自寡，文心得我讵云孤。","苍苍极目犹回首，不尽馀思付藐姑。"]},{"t":"季夏念一日顺昌道中","f":"七言律诗","c":["竟日青山自委蛇，潭光云影静相宜。","忽闻雷雨诸峰动，先变秋飔十日吹。","窈谷飞烟来淡薄，奔溪倒影下孤危。","欲穷耳目将何际，不尽苍茫是所思。"]},{"t":"初秋九日发樵川薄暮至拿口驿","f":"七言律诗","c":["三伏劳劳手万篇，出门西望正潇然。","泬寥野色诸峰外，清浅秋光一水边。","树石陵临来素影，雨云停蓄下轻烟。","息心相对空明处，颇许新凉入暮天。"]},{"t":"薄暮发富屯月行二十里至顺昌","f":"七言律诗","c":["路入青山兴已遥，斜阳古道倍萧萧。","归巢夕鸟微妨静，咽露初蝉不避嚣。","乍见秋容惟月树，复闻涧响促星轺。","云林正得幽人意，何事王孙费隐招。"]},{"t":"繇白莲至铁岭月行至将乐","f":"七言律诗","c":["晓夕青山近远从，翠微西日渐斜封。","云迷不辨秋深浅，雨过初看月淡浓。","万壑泉声归去水，千林烟霭散前峰。","灭明颇见真空色，独许劳人息意逢。"]},{"t":"易小玉华为独清洞","f":"七言律诗","c":["卷石离奇自洁贞，翩然遗俗似孤生。","烟霞隐出冈峦势，风雨微交薜荔情。","堪与三秋留玉骨，何须别洞借华名。","伊余选胜初贻赠，万古清山表独清。"]},{"t":"赋得薰风从南来 阁试","f":"五言古诗","c":["熙朝长化日，昼漏午沉沉。","铜羽光吹动，花阶燠气侵。","奇峰飞近关，霁霭散高林。","解愠朱明职，阜财圣主心。","有臣迟退食，与众共披襟。","自奏虞弦后，薰和尽古今。"]},{"t":"懋敬殿落成恭纪阁试","f":"五言古诗","c":["辰居依极拱，遵轨继谟先。","元气从空结，心源有敬传。","太薇窥座入，万象烛光前。","望道惟于密，藏身更以玄。","一中千帝栋，日跻百王椽。","堂构宁徒美，还歌明配天。"]},{"t":"喜雨即事","f":"五言古诗","c":["百灵知帝心，风电交相努。","圣主自徵休，甘霖先润浦。","月从所好星，龙怒如奔虎。","隐隐光眩空，霏霏膏入土。","廷僚率属歌，田畯呼儿舞。","泽自九天飞，诏因六尺睹。","自非省岁王，安得若时雨。","此日元和书，拜稽上九五。"]},{"t":"赠陈尔新得假时余亦赋归","f":"五言古诗","c":["黄虞不可作，宇宙日陵偷。","万事趋墦垄，一官等舍邮。","谁将忠孝意，为答圣明酬。","聚讼争睚眦，连群竞践蹂。","薨薨呼雁骛，泛泛逐蝤蛑。","世道交相丧，乾坤孰共救。","未能分纠结，何以已戈矛。","宦海方无畔，友谊亦鲜投。","角弓生永叹，伐木动殷忧。","遇子当辰岁，交君乃一周。","二三孚结契，朝夕静图谋。","追琢天人学，盱衡今古筹。","旷怀深激慨，真性每绸缪。","始识三吴俊，能空四海俦。","才华当代选，肝胆古人求。","相砥同偲切，未遑问悔尤。","安知清见玷，聿尔介招仇。","感彼途多涩，披余意弥周。","谁能甘汶汶，聊复偕繇繇。","昭雪蒙皇鉴，徘徊因友留。","归与方起兴，游子共添愁。","回首东方远，兴言南木樛。","此怀今日共，兹意别来抽。","暂握都门夏，相要湖水秋。","登堂期八拜，载酒问扁舟。","客绪为家迫，朋情以别裒。","凄其江月冷，缅邈岭云悠。","行矣多旃勉，怀哉远喔咻。","心胸匪石转，名利总毛輶。","从此分携后，有言凭信脩。"]},{"t":"自燕都至白门纪行四十韵","f":"五言古诗","c":["瞻云游子意，锡类大君恩。","明发怀乡梦，晨驱远帝阍。","朋情宽别绪，旅况促归魂。","出郭成燕粤，登途念隰原。","长羸方永日，星火适当昏。","流汗时披体，惊沙日蔽轓。","逶迟周道永，鴥郁北林棔。","雾向人烟集，尘随马首奔。","横空皆布烁，弥野尽飞燉。","四合东西道，参差南北辕。","下车敦独宿，舍馆欲忘言。","郁薁供时食，菽葵备晚餐。","睡思昏默默，鼓角静浑浑。","虫唧催更变，鸡鸣破日暾。","披衣神聿诧，言驾志先惛。","虔祝凉飙至，私期密盖屯。","聊辞燕冀坟，乃历鲁齐藩。","炎帝光初遏，睡龙气乍喷。","殷雷惊起侧，骤雨快倾盆。","沾足能清曀，披襟可濯烦。","依人迎柳绪，娇路叠芳墩。","恣取千峰翠，孤闻一水湲。","迷筠穿得路，垂枣弱披垣。","云与山呼吸，风依谷吐吞。","管台荒不理，孟庙宇重尊。","碑纪歼妖处，观盈戮叛墦。","萧条循兖界，迤逦渡河源。","怪激如呼怒，淤衡若鼓喷。","一望皆活发，万里尽混湓。","城版侵鱼鳖，民居傍鹿猿。","怡观虽浩浩，率浒尚沄沄。","忽见庄鱼乐，还悲我马啍。","晨过汤沐邑，夕发祖皇庉。","草昧烟云旧，冲疲气色喧。","关山仍阻险，葛驿暂栖跟。","屈指三千里，渡江已百村。","凉薰翻碧萏，初露转霜蘋。","炎伏辞朱宿，清秋在白门。","乡心疏岁月，归梦绕家园。","长啸声何极，孤吟意自论。"]},{"t":"凭轼望云有序","f":"五言古诗","c":["谁噏山河气，扶摇上碧苍。","嘘空回汉彩，弥极绘天章。","萦郁舟车影，蒸腾城郭行。","奇观惊海市，远眺杂江光。","迎日生朝色，回风变晚妆。","疑经帝子织，初制月仙裳。","玉殿霞烟绕，瑶宫雾幄张。","陆离舒复卷，夭矫止还翔。","已识从龙志，先成驾鹊梁。","声施如可附，富贵亦当忘。","极目怀千虑，矢诗愧七襄。","凌虚从此去，垂翼入溟乡。"]},{"t":"寄怀曹允大","f":"五言古诗","c":["分携何足道，秋意恻悽酸。","室迩思人迫，心劳不客宽。","言归非一日，怀子集千端。","面目馀刚气，诗文审故欢。","断金应可利，济火岂云难。","孤尚同肩比，千秋各意观。","凭兹离地约，反向别时看。","往矣遥相忆，云山日就漫。"]},{"t":"林浴元民部邀游虎丘夜半方回","f":"五言古诗","c":["龙门通世好，虎刹获新观。","会晤缘非偶，登临足未艰。","层峰随野眺，曲涧恣幽盘。","风入陵通气，日归寺隐峦。","歌声依谷响，酒兴得山宽。","别后空馀此，扁舟破夜澜。"]},{"t":"次姑苏杨维斗徐君和朱云子共邀舟游","f":"五言古诗","c":["朋聚远方乐，游从智者欢。","旷怀欣四美，通志恣千端。","舟破光天色，人惊静夜澜。","凉薰乘暮意，弦月挂初冠。","旅绪因秋引，家思得友宽。","敦情馀别后，岂曰比肩难。"]},{"t":"别曹允大后便邮复寄言 有引","f":"五言古诗","c":["官閒人不识，有友忽相求。","陡晤须眉旧，久要意气周。","为期詹五日，寄语入三秋。","同济情无让，平原义复修。","溯游从水在，载酒向舟谋。","指点千泓静，低徊一叶浮。","湖光随意放，秋色敛情收。","孤月怡清赏，诸峰悦远投。","无端家绪迫，有恨岭云悠。","信美非吾土，谁能三宿留。"]},{"t":"南城何凝生以遂垞具体索题","f":"五言古诗","c":["梁园千古胜，徒以靡华传。","谁复知空有，惟君搆自然。","五云携手后，一亩结缘先。","至境非资外，幽栖欲近玄。","披图清幻息，览纪结真诠。","我欲罗浮上，神游此洞天。"]},{"t":"黄尔栽弄璋召饮新斋得而字","f":"五言古诗","c":["园成叶喜日，春盛命杯期。","异赏同幽致，畸悰属窃思。","台悬溪水溜，庭共树阴垂。","结搆全依韵，对酬别有姿。","花开留待客，月到巧催诗。","时许苍苔印，未须赋远而。"]},{"t":"兖州道中驰力上何象冈宗伯","f":"五言古诗","c":["五岭披云至，三台瞩曜躔。","寻常天可级，咫尺日为边。","碧落师臣位，风尘游子鞯。","云泥身尚隔，桑梓意堪缘。","宗岱东来近，斗星北正悬。","骥程看历块，鹏翼羡垂天。","力绝追风后，时忧运海迁。","考槃难遽矢，窃禄更思弦。","辽豕心知恧，楚鸡志自翩。","时人今共忽，夫子旧私怜。","顾盻阪车道，拭磨荆水渊。","能留双足卞，所恃九方歅。","感激情犹在，琢追质始全。","蓬生欣在直，萝附尚需牵。","官阁于君动，金台请自先。","筐梅怀女暨，丝组彼姝联。","叩角方长夜，弹冠亦有年。","红尘嗟易落，青眼不徒然。","况复岐途泣，徒歌万舞篇。","愿言霄羽末，一念日中前。"]},{"t":"孟夏念八日奉命册封荆藩德安王并妃就道计程之作","f":"古风","c":["宝玉分周室，威仪出汉宫。","列星辞帝座，五色下层穹。","拜命明章左，锡圭翼井东。","龙虬飞六节，鹥凤挟双桐。","俨若乘云御，飘如帅电?。","玺书光牡驷，旄采建雄虹。","嘉德思炎土，清尘戒祝融。","漱阳餐午气，爱日度薰风。","夕辔林烟满，朝舆月雾朦。","超氛宜上溘，观世且停騣。","随地歌谣采，及时名誉通。","驾言燕冀北，直向楚蕲中。","原隰驱驰异，舟车夙夜同。","路从霄汉迥，槎望斗牛穷。","遥计包茅土，今怀湛露瀜。","秋湖明赤舄，梦泽表彤弓。","文物南藩盛，声名荆服雄。","客心耽古迹，长啸入江枫。","极目云山渺，回看象阙崇。","永怀多不寐，默识自为功。","岂曰俱王事，所知独匪躬。","咨诹无近远，报答有微衷。"]},{"t":"感祖陵震惊矢愤","f":"五言古诗","c":["群凶甘不赦，上逆在天灵。","瓜瓞千年地，旄头一夜经。","风云忘护呵，神鬼不遑宁。","坐令熊罴没，何堪草木腥。","同仇真刻骨，小丑尚藏形。","率土王臣义，枕戈各涕零。"]},{"t":"经池河红心濠梁道中目伤口绘三十韵","f":"五言古诗","c":["驱车维仲夏，骆马日啴啴。","西照奄然没，南薰惨不欢。","客怀非一事，天步值多难。","晨发污尘满，昏停长夜漫。","居行同怵惕，来往共辛酸。","细听途旁语，备言当日端。","一朝鸱义突，万族豕蛇残。","双泪迎锋镝，孱魂失羽翰。","奔逃生莫倚，枕藉死相看。","林鸟悲巢失，枯鱼泣水乾。","芟夷及草木，存活少羸单。","白骨谁当掩，青燐每自叹。","遗人归烬土，故井积腥干。","野哭千家咽，阴风六月寒。","孤儿号独影，鬼妇掩馀瘢。","转壑形方继，燎原势未殚。","旌旗朝夕至，戎马近遥欢。","兵法先批捣，寇情复转丸。","谣词多反侧，偶语半顽奸。","所见皆传火，尚闻有揭竿。","张皇畴振旅，慎固孰瘝官。","已失备无患，当思危得安。","眼疮何以补，心肉莫徒剜。","髀拊须颇牧，罝施必纠桓。","自嗟行踽踽，空抱意慱慱。","谁忍千挥血，无缘一洒丹。","将军今在阃，国士待登坛。","岂但歌牛角，终须顾马鞍。","域中平小丑，关外斩楼兰。","伫望搀抢落，先令南顾宽。"]},{"t":"固镇驿阻滞感述","f":"五言古诗","c":["蹇蹇趋王日，騑騑周道朝。","时危贤者贱，世乱仆夫骄。","敢自悲迟滞，如何驾远遥。","晨林风鹊乱，昏树月乌噍。","未静烟尘色，谁怜羽翼焦。","穷途西日暮，酷昼午云烧。","长息思原隰，饥心望阙朝。","嗟嗟行役者，徒尔复歌谣。"]},{"t":"利国监晓发","f":"五言古诗","c":["晨光谁共悦，物性与人情。","所畏红尘动，故穿绿霭行。","蝉声初露濯，林影乍风明。","渐出前山色，孤闻一水声。","因之深自省，遂觉有同迎。","念此征途扰，犹能静理生。"]},{"t":"书情呈倪玉汝宫端","f":"五言古诗","c":["惜诵期终悯，缄思绝世挐。","顿承英哲诲，因向旧怀摅。","忆昔疲南亩，移情赴北车。","逢时多曲折，自守一千徐。","趋舍方违众，否臧欲任予。","矜愚忘草莽，豁达对簪裾。","但谓方肠坦，不知世故疏。","鄙夷繇径至，忽略当门锄。","昭质虽纷饰，陈辞未得舒。","终然迷忌讳，遂尔触崎岖。","远集将何所，卑飞或可居。","公庭歌锡爵，独坐耻空书。","亦有心怜者，谁为手援欤。","以兹时亟失，祇与意踌躇。","在我惟求犮，于人敢吐茹。","非关难援引，本自少声誉。","攘诟依清白，离尤入静虚。","去来仍直道，先后念皇舆。","怆恻春秋代，吁嗟日月除。","悠悠长路渺，歉歉一身馀。","瞻顾观民极，阽危问服初。","前脩苟不失，夫子谓何如。"]},{"t":"送何香山师相","f":"五言古诗","c":["丘梁绝代睹，名业与公巍。","十载师臣席，三年论道扉。","硕肤明逊节，宠利戒深讥。","龙德当渊跃，虎争下殿归。","人嗟风度远，我念雪门违。","斗极于南是，凉雱自北非。","星轺初夕发，明主久宵衣。","屈指东居日，悲心俟渚飞。"]},{"t":"清明雷发占为有年其太和之至而鼓动之先乎诗以志喜不敢臆为宣也敬衷易之诸卦以明理之固然","f":"七言古诗","c":["三春帝位恰生东，一震初宣久复功。","奋豫繇来占地出，观颐此日始山从。","天为物与行于下，泽以时随出自中。","若借明章还合电，方交动巽应恒风。","阳当大壮纯刚至，候及亨来致虩终。","甲折何心迎解作，满盈谁力引屯通。","休徵有象泯归妹，圣世无忧假至丰。","所愧涉川亡利益，孤于小过省微躬。"]},{"t":"孟夏六日宛在堂后两楼告竣王子龙宋尔孚杨承之尔明就饮西楼台上得中字","f":"七言古诗","c":["楼成孟夏正薰融，枕带双扶古寺东。","有客连群呼北牖，携樽扫地向西窗。","傲睨更择深篁近，指点为寻仄径通。","阶引跻攀劳转折，槛供徙倚递冥蒙。","浮空立栋依环沼，御气开棂吸远风。","明灭诸山来不了，盈虚一水出无穷。","前川碧涌林湾薄，负郭青回麦垄充。","坐对云归千岫白，起看日坠半江红。","丹霞夹照纷披映，霁雾横轇次第矇。","恰好凉襟因友共，全收瞑色入杯同。","醉忘春去惊苍宿，卧恣天行数紫宫。","屈指不知时似箭，举头又见月如弓。","明生石炬光森漫，影拂榕阴佳郁葱。","静觉心胸消磈礧，错疑床履亦虚空。","市声迥绝虚台上，天语微闻广汉中。","纵目双河初倒景，浩观四际弥烟丛。","挹浆漫倩悬峰斗，颓玉犹誇饮涧虹。","此乐谁能推兴罢，因高辄欲擅词雄。","归从韵府翻图璧，移取灯檠撤锦幪。","努力夜游应有意，不堪秋至各飘蓬。"]},{"t":"董子下帷处","f":"七言古诗","c":["一席横经古迹馀，前贤端不负居诸。","藏修此地光形敛，园舍多年置足疏。","祇畏春秋成卤莽，何甘功利滓空虚。","积精师圣观强力，阿学逢时耻伪誉。","直待天人三策就，方留灾异五行书。","迄今千载推名业，西汉醇儒属仲舒。"]},{"t":"无衣篇","f":"七言古诗","c":["频岁防秋念马肥，其时邦政日歔欷。","宁知弭兽先卑鸟，遂有奔狼引突豨。","绸牖诸公初彻土，同袍数子久无衣。","中宵踊跃闻鸡起，四座旁皇拂剑飞。","普率为仇相告语，谁人敌忾肯从违。","因兹小逆亡天道，所以微臣仰圣威。","一怒王师纾众愤，三旬帝羽耀秋晖。","即看日月销兵气，应使风云解斗围。","累累腥膻沉远毳，明明纪律表央旂。","恭惟神武方无敌，蠢尔昏迷自绝归。","取彼凶残清塞漠，执其讯丑在都畿。","祇今拭目观营柳，何日忧心罢采薇。","藏幄素书龙虎秘，随身玉帐鬼神机。","仆夫已召将于牧，君子之车庶所依。","独向劳歌催永夜，不禁万舞及朝晞。","草茅心力虽长短，朝阃无因此是非。"]},{"t":"题驿舍画屏二首 其一","f":"五言绝句","c":["柳色依山卷，楼阴傍水浮。","孤舟閒啸者，于世更何求。"]},{"t":"题驿舍画屏二首 其二","f":"五言绝句","c":["纠蓼云中树，磷砰天外峰。","柴扉堪泄泄，诗酒静相供。"]},{"t":"立秋日二首 其一","f":"五言绝句","c":["炎光未息夏，悲籁已鸣秋。","何须问梧叶，客绪自悠悠。"]},{"t":"立秋日二首 其二","f":"五言绝句","c":["燕天随夏迈，吴地逐秋来。","万里家何处，四时候几催。"]},{"t":"次东乡雨夜枕上口占二首 其一","f":"五言绝句","c":["愁含溪涧色，梦破雨风情。","只为家思旧，翻成旅绪新。"]},{"t":"次东乡雨夜枕上口占二首 其二","f":"五言绝句","c":["黯黯侵魂点，愔愔入耳声。","那堪如晦刻，庭树复鸡鸣。"]},{"t":"季冬立春小园花发已半有友共对三首 其一","f":"五言绝句","c":["微雨逗芳华，悠然动百花。","岭南春事早，梅李竞交芽。"]},{"t":"季冬立春小园花发已半有友共对三首 其二","f":"五言绝句","c":["三年梅岭色，并作此朝春。","留得东风旧，吹来百卉新。"]},{"t":"季冬立春小园花发已半有友共对三首 其三","f":"五言绝句","c":["梦起朝莺唤，春先改岁来。","寻芳忘竟日，对友肯辞杯。"]},{"t":"鄱阳舟中晓望","f":"五言绝句","c":["湖平轻点雨，山远静连云。","望望迷烟合，水天何处分。"]},{"t":"迎春晓占","f":"五言绝句","c":["澄湖舒夜色，微雨蔼朝情。","东风乍相过，流莺忽送声。"]},{"t":"春江听雪","f":"五言绝句","c":["梅使驰朝信，鲛人泣夜声。","千山俱素韵，一水尽凄情。"]},{"t":"食","f":"五言绝句","c":["莫歌冯客鱼，同鄙曹人肉。","便作天随生，杞粮而糗菊。"]},{"t":"睡","f":"五言绝句","c":["长夜空漫漫，白日可于于。","却笑宁牛角，不如庄蝶须。"]},{"t":"閒","f":"五言绝句","c":["时晒渊明巾，日扪子瞻腹。","忽从南郭嘘，嗒然形槁木。"]},{"t":"酌","f":"五言绝句","c":["月影来自天，江流拥酒泉。","不须语客去，我醉即当眠。"]},{"t":"退之气魄","f":"五言绝句","c":["一封抗佛骨，默祝开衡云。","却飞潮海檄，暴鳄徙纷纷。"]},{"t":"季贞风流","f":"五言绝句","c":["四明号狂客，紫宫遇谪仙。","解龟得酒后，骑马似乘船。"]},{"t":"阿子歌 十首 其一","f":"五言绝句","c":["六年刚载震，频夜梦维蛇。","及兹诞阿子，居然弄瓦儿。"]},{"t":"阿子歌 十首 其二","f":"五言绝句","c":["我怀本无恶，虽女遣余思。","云何坠地刻，即我断肠期。"]},{"t":"阿子歌 十首 其三","f":"五言绝句","c":["不信颜比玉，翻成命如丝。","灯前挥泪睫，促对可怜姿。"]},{"t":"阿子歌 十首 其四","f":"五言绝句","c":["谓汝非我女，胡然十月私。","谓汝为我女，不暂一朝随。"]},{"t":"阿子歌 十首 其五","f":"五言绝句","c":["汝母生邻死，沉痛时未知。","祇今怀空席，悽怆泣枕欹。"]},{"t":"阿子歌 十首 其六","f":"五言绝句","c":["对此安能已，强颜作慰词。","更无词可慰，祇有泪相吹。"]},{"t":"阿子歌 十首 其七","f":"古风","c":["怯听?兄语，相将慰莫悲。","谁能心头肉，剜却肝无摧。"]},{"t":"阿子歌 十首 其八","f":"五言绝句","c":["愁煎终为恨，痛剧转成痴。","合眼中宵半，梦起哭还疑。"]},{"t":"阿子歌 十首 其九","f":"五言绝句","c":["丝绪今千结，蒲肠复寸离。","等彼风前旆，摇摇竟不持。"]},{"t":"车中即见四首 其一 虹影","f":"五言绝句","c":["虹桥天际远，影落晚霞明。","风卷垂幽谷，依稀饮涧生。"]},{"t":"车中即见四首 其二 雁沙","f":"五言绝句","c":["沙平浮野阔，雁影应其清。","瀚塞今初乳，何时霄羽横。"]},{"t":"车中即见四首 其三 自顾","f":"五言绝句","c":["晴空无一碍，云鸟结霄邻。","自顾劳劳者，独驱马足尘。"]},{"t":"车中即见四首 其四 双窥","f":"五言绝句","c":["独鸟依深树，孤云出远山。","双窥车马次，何客最烟颜。"]},{"t":"返照","f":"五言绝句","c":["雨过青山暮，行云湿尚飞。","忽开峰外日，返照及征衣。"]},{"t":"客程","f":"五言绝句","c":["古道夕阳平，衔西送客程。","客程无止息，明月复东迎。"]},{"t":"与伯常兄小酌","f":"五言绝句","c":["篷开山献绿，杯动水含烟。","不用池塘梦，偏宜共酒船。"]},{"t":"泊大滩","f":"五言绝句","c":["万树临滩峡，秋声出水寒。","孤舟相对宿，有梦亦频残。"]},{"t":"泊赛上","f":"五言绝句","c":["寸缆横滩雾，孤篷没树烟。","昼行观逝者，夜泊得如渊。"]},{"t":"下姑听啼鸟","f":"五言绝句","c":["晓鸟宿秋枝，连啼急水湄。","归舟难久听，莫使去舟知。"]},{"t":"自大姑至硿头酌酒数滩","f":"五言绝句","c":["舟仅容瓶屈，举杯滩半沸。","一滩酒一杯，恰尽杯中物。"]},{"t":"对春鸟有感十首 其一","f":"五言绝句","c":["巧鸟窥帘语，飞飞令客思。","无情翻有意，偶对似终期。"]},{"t":"对春鸟有感十首 其二","f":"五言绝句","c":["晓鹊求多舞，昏鸦不愿啼。","群情分所见，微物转相迷。"]},{"t":"对春鸟有感十首 其三","f":"五言绝句","c":["仓庚守候鸟，虽小系春声。","最重农桑课，閒关士女情。"]},{"t":"对春鸟有感十首 其四","f":"五言绝句","c":["燕巧行霜怯，鸠新探雪威。","相要图暖计，聚翼向朱扉。"]},{"t":"对春鸟有感十首 其五","f":"五言绝句","c":["漫道鸠居鹊，真成鼠化鴽。","春风容物变，万族自喧哗。"]},{"t":"对春鸟有感十首 其六","f":"五言绝句","c":["反舌何时至，乘春入帝都。","啼莺含愤恨，力小未能驱。"]},{"t":"对春鸟有感十首 其七","f":"五言绝句","c":["为群非鸷种，告好亦鸩媒。","不解诸禽性，难辞失伴哀。"]},{"t":"对春鸟有感十首 其八","f":"五言绝句","c":["野鹜终朝食，云鸿竟日飞。","无心分秽洁，何意较瘦肥。"]},{"t":"对春鸟有感十首 其九","f":"五言绝句","c":["下视逢鸱嚇，冥飞羡鹄过。","谢鸱相勖意，因鹄远虡罗。"]},{"t":"对春鸟有感十首 其十","f":"五言绝句","c":["草色愁鹈鴂，乡心寄鹧鸪。","不知春既老，竟与物为徒。"]},{"t":"所见四首 其一","f":"五言绝句","c":["去日葵倾赤，归时菊散英。","登临观物意，来往较秋情。"]},{"t":"所见四首 其二","f":"五言绝句","c":["总在秋光路，云山异浅深。","山云将白尽，随地绕秋阴。"]},{"t":"所见四首 其三","f":"五言绝句","c":["晚山相对碧，残照网秋风。","秋色如烟缈，风林一望中。"]},{"t":"所见四首 其四","f":"五言绝句","c":["心清秋许见，山远暮能光。","微著烟云色，所思不可方。"]},{"t":"车中即事五首 其一 朝夕","f":"古风","c":["计日尘容惯客，沿堤柳色迷天。","朝暾马右分旭，夕照襟西送烟。"]},{"t":"车中即事五首 其二 晓夜","f":"古风","c":["鸡逐晓风唤客，鸟衔夜月窥人。","便寻家梦能几，况复醒来不真。"]},{"t":"车中即事五首 其三 南北","f":"古风","c":["野旷青天作幕，烟深白日游丝。","南车北马何极，春草秋花共驰。"]},{"t":"车中即事五首 其四 西东","f":"古风","c":["拭目云飞在阙，惊心鸟语归林。","谁云西向真乐，还忆东山卧深。"]},{"t":"车中即事五首 其五 闻问","f":"古风","c":["所以随缘得句，频因触物关思。","愁闻我马嘶激，若问傍人那知。"]},{"t":"连日苦雨讯杨承之","f":"古风","c":["一天云雨如织，尺地往还各疏。","折角先生不出，草玄夫子何如。"]},{"t":"讯王山人","f":"古风","c":["近山翠色多滴，远树烟容自牵。","难付子綦偃仰，伫看摩诘诗篇。"]},{"t":"讯悦则上人","f":"古风","c":["斋北斋南雨点，溪前溪后流声。","石门泉韵非远，城郭风尘暂清。"]},{"t":"宛在堂中即事 其六","f":"古风","c":["在水之中搆室，开窗于北高眠。","何知汉与魏晋，自谓无怀葛天。"]},{"t":"宛在堂中即事 其十九","f":"古风","c":["屈指粤东名业，曲江南海琼山。","斯文未丧今日，后死何人可班。"]},{"t":"四月一日二首 其一","f":"七言绝句","c":["晓来风色北窗归，一岁几何三月非。","谁道时光不作意，晴阴云日半依违。"]},{"t":"四月一日二首 其二","f":"七言绝句","c":["落尽黄梅四月天，空枝一鸟语春还。","早知梅熟春同去，怨却花时信早传。"]},{"t":"系春","f":"七言绝句","c":["曾无好事系春华，冷落閒庭片片花。","半榻幽清贪晓睡，三杯软饱觅生涯。"]},{"t":"问春","f":"七言绝句","c":["几将閒绪问春华，愁客无端怪落花。","花落何堪兼雨夜，客愁可奈是天涯。"]},{"t":"说士与逸民之品不同","f":"七言绝句","c":["张仪寸舌犹问妻，子陵两足可加帝。","终当披裘耕富春，何事读书学游说。"]},{"t":"得时与避世之怀各一","f":"七言绝句","c":["渊明不折小儿腰，子房却进老人履。","归去仍招白衣人，功成亦从赤松子。"]},{"t":"呼奚觅怪石二首 其一","f":"七言绝句","c":["山琢胎形水织纹，千年濯魄冷清濆。","无端过客多閒绪，携取东归意亦慇。"]},{"t":"呼奚觅怪石二首 其二","f":"七言绝句","c":["横流堆叠乱波容，戏拾诸般置夹笼。","借问参寥谁处是，好和清水作相供。"]},{"t":"衢州道中二首 其一","f":"七言绝句","c":["西流一水向东潺，夹右诸陵并道擐。","归路惟多千嶂阻，愁来欲把众峰删。"]},{"t":"衢州道中二首 其二","f":"七言绝句","c":["云影相从树影亲，近峰如作远峰臣。","奇观始信天工巧，谁把丹青挂夕晨。"]},{"t":"十八早自从叔公车舫至峡江过伯常兄舟中共酌醉后口占二绝 其一","f":"七言绝句","c":["沙明涛白豁天开，江远舟轻破月来。","阮氏风流今日事，相逢急进手中杯。"]},{"t":"十八早自从叔公车舫至峡江过伯常兄舟中共酌醉后口占二绝 其二","f":"七言绝句","c":["仙舟飘渺溯潺湲，访载寻稽忽可扳。","一笑一歌江日暮，流光山色窅然閒。"]},{"t":"时得家报伯常兄城侄痘疹新愈喜甚口占相慰二首 其一","f":"七言绝句","c":["万里江云收玉峡，数行家信出金川。","为兄同慰凤毛种，不惜歌欢鹢首船。"]},{"t":"时得家报伯常兄城侄痘疹新愈喜甚口占相慰二首 其二","f":"七言绝句","c":["烟波江上恰相随，春草池塘未足奇。","醉罢不知霜色夜，诗成已是月明时。"]},{"t":"过丰城剑江二首 其一","f":"七言绝句","c":["剑光何德烛天河，已没平津又若何。","神物终非人世玩，江充长与万年磨。"]},{"t":"过丰城剑江二首 其二","f":"七言绝句","c":["江来万里独何求，剑去千年不可留。","夜半霜华生月色，还疑精气逐舟浮。"]},{"t":"望庐山有引","f":"七言绝句","c":["相对无缘认岭峰，入看祇许白云同。","却于舟行成横侧，漠漠天屏一镜中。"]},{"t":"偶占","f":"七言绝句","c":["晓风飞去片花吹，暮雨低来折柳垂。","愁绝子规声欲断，美人独立意迟迟。"]},{"t":"舟发雩都苦雨随缘成八首 其一","f":"七言绝句","c":["一苇何堪万点侵，无人告诉只呻吟。","中宵料理三移枕，竟日绸缪两蔽襟。"]},{"t":"舟发雩都苦雨随缘成八首 其二","f":"七言绝句","c":["无端林响引风窥，多事桅声报客知。","缘岸低来同懒困，偏帆迟去半欹危。"]},{"t":"舟发雩都苦雨随缘成八首 其三","f":"七言绝句","c":["一片春深积雨吹，花开如喜落花悲。","未知悲喜终谁得，雨却归春春亦疑。"]},{"t":"舟发雩都苦雨随缘成八首 其四","f":"七言绝句","c":["招招舟子笠蓑蒙，踯躅溇沙湿岸中。","惊起浴鸥飞别浦，横拖醉竹压孤篷。"]},{"t":"舟发雩都苦雨随缘成八首 其五","f":"七言绝句","c":["缘溪处处野花逢，裔草拖泥乱影重。","恰似春光怜莫主，传教细雨沐新容。"]},{"t":"舟发雩都苦雨随缘成八首 其六","f":"七言绝句","c":["夹陵一带碧波洄，雨脚迷离纷欲催。","何处村烟云卷去，随缘鸟语客传来。"]},{"t":"舟发雩都苦雨随缘成八首 其七","f":"七言绝句","c":["泯泯朝流晚更添，洄沙拂渚浪花兼。","贪看激石分波过，忘却迟舟缩棹黏。"]},{"t":"舟发雩都苦雨随缘成八首 其八","f":"七言绝句","c":["已恨愁来春欲痴，那堪思去雨犹疲。","可怜百日思愁绪，迸与今宵春雨知。"]},{"t":"小卧口占二首 其一","f":"七言绝句","c":["久客何思空默默，斗舟伸足便蘧蘧。","篙声落石午魂乱，竹影穿窗暮眠疏。"]},{"t":"小卧口占二首 其二","f":"七言绝句","c":["已拚三旬从在水，偶随此刻卧行天。","浮空一片孤云往，薄暮归山对我眠。"]},{"t":"走笔向宋尔孚乞绛桃","f":"七言绝句","c":["耽花成癖况当春，频向东风觅故人。","闻说绛桃三月放，芳园可许一枝新。"]},{"t":"短叶乞花不能尽意昨者一枝新之句主人以为求插净瓶乃余所求者本也","f":"七言绝句","c":["谁使陵溪别有春，桃津多事向渔人。","当年若解贻仙种，不遣花飞出世新。"]},{"t":"更乞百叶一种","f":"七言绝句","c":["珍重当年禁苑春，助娇消恨旧何人。","风流争似潘郎得，付与河阳满县新。"]},{"t":"乞绛桃而得碧桃因向主人称谢","f":"七言绝句","c":["露种原从天上春，云根移自日边人。","一枝清韵堪盈匊，不数妖红万朵新。"]},{"t":"乞绛不与而与碧兼为花神解嘲","f":"七言绝句","c":["金谷丛中万种春，淡妆羞见艳妆人。","自知颜色承恩少，飞入茅庭逞素新。"]},{"t":"尔孚复以诗乞余长春花新本数株此花种固来自尔孚也","f":"七言绝句","c":["娇丛离陆不胜春，春盛还归春主人。","若使花情犹识旧，此朝投报莫疑新。"]},{"t":"林九娘墓三首 其一","f":"七言绝句","c":["比年贼寇乱村烟，嬴得偷生问节全。","里妇惊传刀下语，狂奴许杀未容怜。"]},{"t":"林九娘墓三首 其二","f":"七言绝句","c":["一抔香落陌头馨，三协春风宿草经。","贞冢无心催恨色，年来空作断肠青。"]},{"t":"林九娘墓三首 其三","f":"七言绝句","c":["古来烈女死犹生，不爱身前重后名。","纵使贞魂甘寂寂，谁能凄断付孤茔。"]},{"t":"速杨承之诸子过坐","f":"七言绝句","c":["连宵苦雨住柴扉，湿尽苍苔屐齿稀。","白眼科头容觅伴，阮家粗饭莫相违。"]},{"t":"向王子龙乞盆兰","f":"七言绝句","c":["九畹丛中百种芳，较书台下日相望。","庭兰索伍情多迫，莫使琴歌对草伤。"]},{"t":"三月三十夜与承之偕二兄小酌计春已去十有三日议各取平上去入之十三韵为五绝以纪事上平十三","f":"七言绝句","c":["六载风光不系跟，逢春能几见家园。","相怜何事轻相失，花木凄然亦与喧。"]},{"t":"下平十三","f":"七言绝句","c":["多时春去月犹三，留得春名一刻甘。","今夕何当重赋别，双愁强付一杯担。"]},{"t":"上十三","f":"七言绝句","c":["眼见东风愁不反，朝来梅雨催春远。","阶前落尽百端花，懒俟今宵苔卧稳。"]},{"t":"去十三","f":"七言绝句","c":["悠然相对莫相问，报答时光都有分。","伊我九旬同醉醒，诸篇颇觉春遥近。"]},{"t":"入十三","f":"七言绝句","c":["春情我意肯终极，每至离思同黯默。","却怪疏怀百懒惛，无端幽事偏窥得。"]},{"t":"晚泊小步承之向索诗题口占答之","f":"七言绝句","c":["参差一叶渡春溪，同步芳洲日正西。","共道春山皆故识，更邀溪月作新题。"]},{"t":"过峡江悼自从叔二绝 其一","f":"七言绝句","c":["当年江峡醉扁舟，击楫同歌万里流。","三载家山人物变，不堪此地独回头。"]},{"t":"过峡江悼自从叔二绝 其二","f":"七言绝句","c":["云满长江雨满舟，悲予不但泪添流。","死生既隔山河异，他日归看宿草头。"]},{"t":"答杨承之上巳诗","f":"七言绝句","c":["已过清明修褉天，桃花欲尽杏花颠。","一声黄鸟催春色，满地红苔落雨溅。"]},{"t":"白发非春事承之亦愁春乎答此似嘲实以慰也","f":"七言绝句","c":["三月飞红乱欲纷，江头风色正愁君。","独馀两岸杨花絮，留与扁舟丝鬓分。"]},{"t":"百里金陵","f":"七言绝句","c":["百里晴江二水新，六朝金色数峰春。","烟花想像青门内，压酒吴姬是主人。"]},{"t":"过采石吊李白墓四首 其一 一快其遇知章也","f":"七言绝句","c":["英豪相视一杯中，笑向金銮顾紫宫。","貂作当年知己具，靴留千载侍臣风。"]},{"t":"过采石吊李白墓四首 其二 一伤其厄力士也","f":"七言绝句","c":["赋就调羹动主知，歌成酌酒感妃辞。","无端宿醉双靴落，故令新妆一语疑。"]},{"t":"过采石吊李白墓四首 其三 一伤其以诗见弃而快其才也","f":"七言绝句","c":["金笺捧出庆池章，落羽翻辞銮殿旁。","供奉清班能几日，风骚不尽古今场。"]},{"t":"过采石吊李白墓四首 其四 一快其以酒相忘而伤其志也","f":"七言绝句","c":["主恩朋意两殊遭，知遇无缘答寸毫。","只为宫阉多气色，故藏名姓入醇醪。"]},{"t":"舟间柳絮二首 其一","f":"七言绝句","c":["柳絮纷纷不耐春，先来羁缆向愁人。","萍飘自合伊同绪，未落衣襟已怅神。"]},{"t":"舟间柳絮二首 其二","f":"七言绝句","c":["本随春放亦春迷，恼乱东吹一片西。","错认梅风飞粤岭，分明桃水落吴溪。"]},{"t":"既而见柳浪不兴丝波自卷觉起絮因风尚多事耳","f":"七言绝句","c":["未假风情向日飞，预分晴气散春菲。","无端潮色随丝住，遮莫青流着素衣。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其一 西楚霸王妾虞氏","f":"七言绝句","c":["楚歌声尽落腥风，霜剑先君试粉红。","拚得残魂随马右，大王留面渡江东。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其二 魏武赎归蔡文姬","f":"七言绝句","c":["但得生还恨亦欢，离颜羞向漠云看。","若云胡地堪回首，青草应将汉冢瞒。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其三 桃叶渡泛秦淮","f":"七言绝句","c":["兰枻花樽桃叶津，秦时流水晋时人。","杯前明月今归我，柳下清歌别有春。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其四 春尽以诘旦渡江是晚风雷骤发","f":"七言绝句","c":["二旬孤缆白门津，花暖烟深数夕晨。","此日江风知客去，一声平卷六朝春。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其五 陈见侯自燕得选回相遇浦口舟中","f":"七言绝句","c":["浦云初出日边襟，江口欣闻岭外音。","率尔乡情无细问，乡情话及令愁深。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其六 四月一日发浦口","f":"七言绝句","c":["梦忽醒时春去深，风烟驿路马蹄寻。","征车带得江云湿，散与滁山一片阴。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其七 舟车","f":"七言绝句","c":["天涯昏旦八千身，落尽舟车九十春。","极目东来云外黛，举头北阻日边尘。"]},{"t":"偶见郭六脩侍御怜古诗八绝句步韵漫成其二 其八 策蹇","f":"七言绝句","c":["关岭轻云驴背生，燕天远日照鞭明。","幸无车马骚安邑，恰有莺花送客程。"]},{"t":"昏尘","f":"七言绝句","c":["西郊落日正明霞，北面昏尘欲暗车。","却恨芳茵堤柳外，不随马足蔽征沙。"]},{"t":"大店借宿","f":"七言绝句","c":["青钱买得主人情，白酒权浇远客程。","野鸟檐茅同雾宿，邻鸡庭树又烟惊。"]},{"t":"黄河道中","f":"七言绝句","c":["群峰沓嶂逐河生，马首轻云到水明。","西望昆源襟右入，天风吹出暮涛声。"]},{"t":"拖泥郊野宿","f":"七言绝句","c":["日落山深暂隐霞，西林倒挂月弦斜。","灭明村火驱前导，代拂征鞍是主家。"]},{"t":"闻姚永言不果北上","f":"七言绝句","c":["东车西马路横差，不见征人祇暗沙。","眼里尘颜多错认，堤前柳色又迷花。"]},{"t":"望尘","f":"七言绝句","c":["倚日初能紫陌驰，因风转欲碧空吹。","分明入眼惊相向，身近其中却不知。"]},{"t":"汶上晓发见烟树参云","f":"七言绝句","c":["千林蓊郁碧云间，万鸟衔烟自往还。","俯视氛埃不可犯，直临远汉接苍颜。"]},{"t":"午车睡吟不知已至高唐也","f":"七言绝句","c":["日昃中天倦未醒，高唐云气动征軿。","昏愁有赋难书就，梦里微吟寤自听。"]},{"t":"千柳","f":"七言绝句","c":["道旁千柳尽妖颜，作意随人问往还。","刚为春归飞别絮，又从风晓屈离鬟。"]},{"t":"孤松","f":"七言绝句","c":["孤松拔秀出幽山，色可餐人气莫攀。","祇许云霞依翠盖，不随风雨落苍颜。"]},{"t":"雄邑署中夜坐得月","f":"七言绝句","c":["万里今宵尺五天，深更夜对不知眠。","东方涌月金盆大，挹水舒华净客烟。"]},{"t":"固安饮黄亨臣明府署中达旦","f":"七言绝句","c":["琴堂肃肃月来还，此夜同生万里颜。","影落深杯乡语尽，晨驱马首向西山。"]},{"t":"散馆曹允大相讯诗以代柬","f":"七言绝句","c":["五夜藜吹尽六霜，与君一体乍分行。","梦中不识仙凡异，犹逐秋风向玉堂。"]},{"t":"封荆将就道别梁瑶石铨部适卢本潜给谏胡兰石侍御俱集小酌口号","f":"七言绝句","c":["人归何事后春归，别絮离丝共落晖。","楚水吴山无限思，枫林江上白云飞。"]},{"t":"简点行箱","f":"七言绝句","c":["羸得青山识故邛，任教玄草滞行箱。","承明著作非吾事，归向云峰自卷藏。"]},{"t":"夏日奉命册荆藩车中计程之作","f":"七言绝句","c":["南鸿北燕日蹁跹，每岁征程计八千。","却怪沿堤春后柳，年年新色为余怜。"]},{"t":"倦醉","f":"七言绝句","c":["昏舆倦醉自歌劳，半梦湘江半赋骚。","欲向三闾谋独醒，仍愁渔父教哺糟。"]},{"t":"晚至黄河阻渡","f":"七言绝句","c":["霞彩波光抱日沉，黄云隔岸覆城阴。","我来欲渡无津吏，南浦滔滔出暮心。"]},{"t":"晓渡","f":"七言绝句","c":["击汰中流水欲波，飞扬极目自为歌。","千年几度澄清俟，一苇冲风意若何。"]},{"t":"凉阴","f":"七言绝句","c":["竟日凉阴障暑流，炎光无力夏情柔。","白云随意青峰上，半作春容半作秋。"]},{"t":"风拂","f":"七言绝句","c":["独坐江风拂面迎，萦波微曳月华轻。","可怜如镜初秋魄，吹落扁舟见客情。"]},{"t":"露团","f":"七言绝句","c":["玉露初团入夜清，澄江如练月如晶。","无边秋色随风乱，不尽山光到水明。"]},{"t":"流閒","f":"七言绝句","c":["江长月散夜流閒，无限波光去不还。","却寄愁心归白水，莫嫌孤缆滞青山。"]},{"t":"书怀","f":"七言绝句","c":["濯足流中万顷迎，拂衣云外一轮生。","此心夜半临江月，持向秋旻问孰清。"]},{"t":"潜山道中晚行怀方肃之四首 有引 其一","f":"七言绝句","c":["去年春水荡离忧，今日秋山积近愁。","满月云林难指数，碧烟一带自沉浮。"]},{"t":"潜山道中晚行怀方肃之四首 有引 其二","f":"七言绝句","c":["逢人指点问君家，咫尺青山云半遮。","落日峰西飞夕照，似浮颜色映流霞。"]},{"t":"潜山道中晚行怀方肃之四首 有引 其三","f":"七言绝句","c":["千秋还碧入斜晖，万鸟衔青落翠微。","漫托离心归晚岫，白云愁绝未能飞。"]},{"t":"潜山道中晚行怀方肃之四首 有引 其四","f":"七言绝句","c":["论心一载便千秋，不向今人不古求。","馀子中原俱碌碌，丈夫世上未悠悠。"]},{"t":"夜行至晓","f":"七言绝句","c":["四更山月照星轺，不惮驱驰不惮遥。","祇愁魂梦归家少，泣向秋风问楚招。"]},{"t":"黄梅道中听松风","f":"七言绝句","c":["路入黄梅静晓闻，松风随地拂禅云。","秋声半老人间世，天籁长归物外群。"]},{"t":"分署承今础以二诗相招使者立促步韵答之","f":"七言绝句","c":["与君乍别异枯荣，不谓君心似我情。","强欲从郡无那懒，思君窗卧对云行。"]},{"t":"寓所有绿柳垂阴拂云檐落因复以此转招今础步其二之韵","f":"七言绝句","c":["白云绿树抱幽居，人境何年乍结庐。","樽酒迟君茵席上，披襟共话柳风初。"]},{"t":"州刺史唐伯闇以蕲州志相贻","f":"七言绝句","c":["问俗蕲春见楚书，水山奇异尽堪除。","独留麟凤供金节，不教龟蛇乱里闾。"]},{"t":"卧起","f":"七言绝句","c":["朝对梧风暮柳云，萧然一署自氤氲。","北窗卧起中庭坐，木落天空雁几群。"]},{"t":"夜吟","f":"七言绝句","c":["朝朝酬对一游艰，独剩孤吟入夜閒。","梦落丹枫秋欲半，歌怀赤壁月初还。"]},{"t":"仲秋三日送节马上口占别今础四首 其一","f":"七言绝句","c":["六节翩翩指北翔，臣谊翻令友情长。","星分楚野迷千岫，思入燕天共一方。"]},{"t":"仲秋三日送节马上口占别今础四首 其二","f":"七言绝句","c":["蹇蹇王臣各未家，客中离异倍伤嗟。","秋深古道非前色，愁见堤荷作旧花。"]},{"t":"仲秋三日送节马上口占别今础四首 其三","f":"七言绝句","c":["鲁粤犹然称二东，八千里路在其中。","与君此地舟车别，秋色平分近远同。"]},{"t":"仲秋三日送节马上口占别今础四首 其四","f":"七言绝句","c":["蕲峰中断马头分，古道离颜共白云。","交手再三挥手去，萧凄畏对楚关曛。"]},{"t":"过赣关见民舟阻隔有感","f":"七言绝句","c":["疲篙力尽出危湍，几度魂销却望寒。","稍得安流堪下楫，官家何事又重阑。"]},{"t":"山峡见月","f":"七言绝句","c":["月开山峡到江船，翠黛含辉入水鲜。","此地孤清谁共挹，沙眉石齿妒婵娟。"]},{"t":"舟行偶成","f":"七言绝句","c":["夹嶂中开出短帆，奔湍洄注入深岩。","濯缨石上闻渔咏，洗帻沙滨怕鹤衔。"]},{"t":"舍陆就汀舟喜见家乡在即三首 其一","f":"七言绝句","c":["穷舟所载不如车，能向山行胜策驴。","荡桨幽峰随落涧，不愁前路有崎岖。"]},{"t":"舍陆就汀舟喜见家乡在即三首 其二","f":"七言绝句","c":["西来汀水欲朝东，万嶂千岩一缕通。","急濑掀刀难坐望，轻帷短被卧秋风。"]},{"t":"舍陆就汀舟喜见家乡在即三首 其三","f":"七言绝句","c":["青山频过不知名，但忆乡关此地迎。","昨夜归魂先识路，秋风吹向绿榕城。"]},{"t":"至大埔闻乡音","f":"七言绝句","c":["八千里外始乡关，乍听乡音慰客颜。","几夜梦依双膝下，征衣频拂念途艰。"]},{"t":"孟夏一日瑞金署中晓望","f":"七言绝句","c":["一望苍然欲见春，飞花舞树动芳晨。","莺声啼老蝉声细，始觉烟光已去人。"]},{"t":"三河舟晚","f":"七言绝句","c":["芳汀列树碧流分，界出家山断续云。","万里征魂依曲岸，寻常估客步斜曛。"]},{"t":"茶阳登车念别亲友亦稀人事山行纵日欣感交心","f":"七言绝句","c":["眼见千山同是春，意中一壑转相亲。","来云片片深行色，去涧淙淙落世尘。"]},{"t":"雪后杨荆岫见投近藁走笔代柬","f":"七言绝句","c":["窗前雪艳几徘徊，宝玉临门气欲来。","古鼎敲云初见色，春风吹出绿光开。"]},{"t":"客司即事四首 其一","f":"七言绝句","c":["无辱无荣典客名，来王来享向人成。","朝朝研墨磨朱卷，停笔槐阴听啭莺。"]},{"t":"客司即事四首 其二","f":"七言绝句","c":["肘后诸方莫漫嗟，自从九折当医家。","但随夔步含鸡舌，还守蜗居远鼠牙。"]},{"t":"客司即事四首 其三","f":"七言绝句","c":["终身于物共推移，大隐金门是我师。","眼不皆青从世尔，玄如尚白欲谁欺。"]},{"t":"客司即事四首 其四","f":"七言绝句","c":["若道长安未若家，微官清况尽堪誇。","凭他风雨迷天路，不入曹椽似水衙。"]},{"t":"寄家中诸兄弟十首 其一","f":"七言绝句","c":["花时长忆弟兄群，绿岛春杯夜未分。","一自梅风辞凤岭，于今柳雪滞鸿云。"]},{"t":"寄家中诸兄弟十首 其二","f":"七言绝句","c":["春草池塘梦得时，连床夜雨倍相思。","阿奴碌碌真游倦，又负三三修褉期。"]},{"t":"寄家中诸兄弟十首 其三","f":"七言绝句","c":["惭愧西园百树低，惜花人去鸟空啼。","凭兄咫尺相巡问，莫遣红飞绿更迷。"]},{"t":"寄家中诸兄弟十首 其四","f":"七言绝句","c":["自北殷忧日夜移，向西言乐古今痴。","看来世路同驹隙，何事秋风落雁期。"]},{"t":"寄家中诸兄弟十首 其五","f":"七言绝句","c":["天伦乐事在诗书，未足三冬向五车。","比似怡怡相对日，弟疑兄质莫群居。"]},{"t":"寄家中诸兄弟十首 其六","f":"七言绝句","c":["西汉新书辟召行，力田孝弟比科名。","休言捷径皆时誉，但使趋庭继祖声。"]},{"t":"寄家中诸兄弟十首 其七","f":"七言绝句","c":["滔滔流俗似奔波，百丈危滩万石峨。","不信长年从水势，虽凭短楫奈舟何。"]},{"t":"寄家中诸兄弟十首 其八","f":"七言绝句","c":["暂闻鲸海一波收，无奈狼烟百燧浮。","眼外征云云外路，鸟飞犹作旆旌愁。"]},{"t":"寄家中诸兄弟十首 其九","f":"七言绝句","c":["半载鱼书万里程，寻常来往赖时清。","行云似欲添愁客，又向关河暗戟旌。"]},{"t":"寄家中诸兄弟十首 其十","f":"七言绝句","c":["平安消息便千金，梦断重关折寸心。","无限归愁因伯季，鹡鸰声急是诸吟。"]},{"t":"对春雪偶书","f":"七言绝句","c":["耐守春寒惯客身，时将冻笔斗芳晨。","悬知世事皆云过，惟有文心向雪新。"]},{"t":"见落花有感","f":"七言绝句","c":["每到春深念物华，可怜柔叶可怜花。","一般红绿还相妒，解舞新条笑落葩。"]},{"t":"过邯郸口号六首 其一","f":"七言绝句","c":["世事浮云那足猜，名根浸骨去还来。","邯郸莫用前时枕，几岁频从梦里回。"]},{"t":"过邯郸口号六首 其二","f":"七言绝句","c":["漫道玄关不待人，潇然独善竟何邻。","千言牛背传关尹，今古人心始谷神。"]},{"t":"过邯郸口号六首 其三","f":"七言绝句","c":["若使仙群少异才，云谣玉牒久尘埃。","顽仙百辈名山卧，天地玄文何代开。"]},{"t":"过邯郸口号六首 其四","f":"七言绝句","c":["已知百岁苦无多，未解仙途数几何。","一日人间真七世，便同元会亦飞梳。"]},{"t":"过邯郸口号六首 其五","f":"七言绝句","c":["今古终归必尽身，眼前为假便为真。","乾坤别有黄粱境，祇恐神仙亦梦人。"]},{"t":"过邯郸口号六首 其六","f":"七言绝句","c":["茫茫羲驭亿千年，驻景何人出世缘。","非我尽迷生死地，于君欲问后先天。"]},{"t":"晚眺","f":"七言绝句","c":["千里烟容浸碧苔，游人一望一心灰。","无端秋色缠烽燧，几度西风扫不开。"]},{"t":"竣事以季秋十三日渡黄河","f":"七言绝句","c":["秋落河干气亦清，黄流相对白云行。","大梁晓气千波卷，留与文光一派明。"]},{"t":"哀鞠四绝 其一","f":"七言绝句","c":["离悯初闻百绪倾，凄其苫次但魂营。","当年陟屺嗟无死，今日哀莪恨有生。"]},{"t":"哀鞠四绝 其二","f":"七言绝句","c":["儿向征途母计归，密缝手线在儿衣。","祇今线绝临行手，儿纵归来膝下非。"]},{"t":"哀鞠四绝 其三","f":"七言绝句","c":["游子飘篷失故形，哀哀匍匐望行星。","伤心露草依风树，每夜玄霜杀晓青。"]},{"t":"哀鞠四绝 其四","f":"七言绝句","c":["孝薄无繇达至尊，陈情五上自声吞。","纵然此日酬王事，已自今生负母恩。"]},{"t":"痛兄三绝 其一","f":"七言绝句","c":["昨夜南杓坠鸟星，柳注霜飞翼雨零。","池毛已落人间影，张素空留天上形。"]},{"t":"痛兄三绝 其二","f":"七言绝句","c":["一抔初筑共泥驮，三月庐居片石磨。","封树未乾松未植，伯从母去仲如何。"]},{"t":"痛兄三绝 其三","f":"七言绝句","c":["三十年来弟与兄，如形依影响从声。","声销影灭归何处，未了前缘结再生。"]},{"t":"悼内二绝 其一","f":"七言绝句","c":["潘壁庄盆事未殊，人间哀乐总须臾。","情知汝去终无憾，频道归泉得侍姑。"]},{"t":"悼内二绝 其二","f":"七言绝句","c":["回头似得再来身，生死迷关自转轮。","未免钟情惟一事，停眸犹嘱看儿频。"]},{"t":"过石钟绝句","f":"七言绝句","c":["天地同和大乐流，水山依律间镛銶。","清朝洗耳求清奏，肯让苏髯夜半舟。"]},{"t":"立春日风雪如晦漫望有感 其一","f":"七言绝句","c":["颓云江上压山飞，天水相迎入翠微。","春色如丝无着处，凭将六出散初晖。"]},{"t":"立春日风雪如晦漫望有感 其二","f":"七言绝句","c":["东望望春春未舒，孤舟滞客转踟蹰。","欲招屈子为天问，懒向风人赋日居。"]},{"t":"立春日风雪如晦漫望有感 其三","f":"七言绝句","c":["沧江万里尽霜华，一叶虚疑泛月槎。","烂熳春容初淡扫，空明相映自参差。"]},{"t":"立春日风雪如晦漫望有感 其四","f":"七言绝句","c":["何处飞花向水明，客心如水伴孤清。","任教虢国朝天面，空负阳台梦雨情。"]},{"t":"立春日风雪如晦漫望有感 其五","f":"七言绝句","c":["江外诸峰变玉山，林烟半出俟春还。","碧水未解严冬色，青帝依然独闭关。"]},{"t":"上元后二日雪霁得月江舟漫兴 其一","f":"七言绝句","c":["春到人间倩月传，菁华五夜雪为先。","山光半扫寒云色，江影遥涵碧树烟。"]},{"t":"上元后二日雪霁得月江舟漫兴 其二","f":"七言绝句","c":["烟水初分春淡薄，寒峰易令月孤危。","光容未散千红紫，空色齐归一素姿。"]},{"t":"上元后二日雪霁得月江舟漫兴 其三","f":"七言绝句","c":["月趁春来雪共浮，深宵肃景尚疑秋。","寒光拂水纷难定，霜谷飞泉冻不流。"]},{"t":"上元后二日雪霁得月江舟漫兴 其四","f":"七言绝句","c":["冰岩何异蕊珠宫，夜静江虚碧汉通。","沧海无劳誇蜃气，瑶台端不借人工。"]},{"t":"上元后二日雪霁得月江舟漫兴 其五","f":"七言绝句","c":["天花着地自玲珑，绘素谁加太极功。","万象虚明归此际，只宜孤月在寒空。"]},{"t":"客舟两月王春又一矣而凉雱不已诗以懊之 其一","f":"七言绝句","c":["心与长江水并閒，任教风雪赴潺湲。","羁人触忤缘何事，日日愁云闭远山。"]},{"t":"客舟两月王春又一矣而凉雱不已诗以懊之 其二","f":"七言绝句","c":["试借莺花慰客心，羁情犹自费搜寻。","玄冥即便欺春软，平白时光尽夺侵。"]},{"t":"见诸游人诗文戏为二绝 其一","f":"七言绝句","c":["莫来莫往尽诗歌，山费周旋石费磨。","幽谷标名虽自许，丰山真面奈人何。"]},{"t":"见诸游人诗文戏为二绝 其二","f":"七言绝句","c":["不见山心莫诟山，山中禽鸟笑人顽。","何如伛偻相呼应，山暮山朝自往还。"]},{"t":"途中呼从者折杏花口示二绝 其一","f":"七言绝句","c":["花下销魂似渴饥，从来情性被花欺。","长途仆马颠连甚，犹令东园折杏枝。"]},{"t":"途中呼从者折杏花口示二绝 其二","f":"七言绝句","c":["遥看近折总同心，转益相怜意转深。","已见枝头春色减，莫教马上日光侵。"]},{"t":"花枝归客园花似笑似怜又似有所思诗以解之 其一","f":"七言绝句","c":["飞烟满目尽如云，淡扫浓妆总十分。","拘管春风方共处，牵连客意复离群。"]},{"t":"花枝归客园花似笑似怜又似有所思诗以解之 其二","f":"七言绝句","c":["倾盖持携却甚真，莫嫌多事转相嗔。","纵留此地应谁主，五夜微芳独懊春。"]},{"t":"花枝归客园花似笑似怜又似有所思诗以解之 其三","f":"七言绝句","c":["自在诸花莫太狂，无情风雨绝须妨。","春方泛爱难孤倚，客有馀心欲细商。"]},{"t":"孟冬之望乘月溯流至广陵","f":"七言绝句","c":["何处澄波泻客愁，射陂流水趁邗沟。","天连牛斗同分野，地转东南共一州。"]},{"t":"泊广陵偶成 其一","f":"七言绝句","c":["隋堤柳岸旧飞花，零落霜风莫怨嗟。","二十四桥寒月夜，清辉犹映玉钩斜。"]},{"t":"泊广陵偶成 其二","f":"七言绝句","c":["西亭竹影未堪邻，东阁梅花兴转新。","若道琼台天下少，迷楼千载尚飞尘。"]},{"t":"泊广陵偶成 其三","f":"七言绝句","c":["山堂云阁传欧吕，载月题星两得名。","但使今人能古事，龙冈风景自盈盈。"]},{"t":"戊辰殿试后述怀二首 是岁殿试以孟夏一日 其一","f":"五言律诗","c":["怀抱依三策，遭逢此一时。","看花从马背，释褐向龙墀。","事业无穷日，文章有用期。","敢云通国体，亦自许先资。"]},{"t":"戊辰殿试后述怀二首 是岁殿试以孟夏一日 其二","f":"五言律诗","c":["螭头天乐动，洗耳听薰融。","日月流初照，风云及远躬。","幸无安饱志，时出淡宁衷。","马上西山色，朝朝入眼中。"]},{"t":"秋日入馆纪事二首 其一","f":"五言律诗","c":["秋光开秘笈，玉露洗朝烟。","抱策初相向，登瀛亦偶然。","花砖流近影，藜火出新编。","敢不徵诸古，以求性所先。"]},{"t":"秋日入馆纪事二首 其二","f":"五言律诗","c":["当代推名业，百年祇数贤。","趋今迷近轨，汲古得修泉。","气色看前辈，菁华属旧编。","丈夫应有志，从此益贞坚。"]},{"t":"秋馆读书二首 其一","f":"五言律诗","c":["颇怪今非古，安能送复迎。","栖神甘寂寞，守意入空明。","开卷闻声出，逢人见目成。","此时秋露滴，千载共虚清。"]},{"t":"秋馆读书二首 其二","f":"五言律诗","c":["葭露含朝碧，槐光散午华。","时依经雪树，每愧向阳花。","息意甘宁淡，冥思抱远遐。","西来多爽气，长与玉堂赊。"]},{"t":"咏望月","f":"五言古诗","c":["瑶宫太阴元，启镜当天门。","初出情犹敛，映日转黄昏。","须臾飞艳魄，舒心遍乾坤。","妆成锦霞拥，轮动彩云奔。","关河难阻隔，蟾兔岂嚣烦。","我视空明质，如开四照轩。","谁种八衢花，向此不夜园。","玉毫光可数，银汉净无痕。","桂树千年色，婵娟万古魂。","魂以高自洁，色以素常存。","流华安可即，远意正堪论。"]},{"t":"观寒雁","f":"五言古诗","c":["夕氲穷天蔽，寒雁纵声高。","问汝今何适，喈喈视其曹。","回翔若语我，远意日忉忉。","自向回峰北，严霜折大刀。","深秋将邈遰，江汉有馀陶。","所愧中和质，颇因寒暑遭。","衔芦避人缴，司夜命奴号。","独爱主宾礼，岂辞南北劳。","君观前后列，去就安可挠。","感此俯而思，诸怀悉屏韬。","始知烟雾姿，此诚飞类豪。","知几轻万里，秩序本中操。","洲渚千行次，云霄一羽毛。","试看鸿渐陆，何似鹤闻皋。"]},{"t":"己巳读书佳山水王季重禹穴斋名也季重入都徵诗于余即以此意赠之山水果佳应知我言","f":"五言古诗","c":["我闻山阴道，应接靡馀隙。","古之会心人，咸于此躅踯。","每思造物怀，平分流峙脉。","其中应有异，时情安可获。","东游觅山隐，南寻见李白。","禹穴藏书处，实补东南坼。","萧条数百年，此意谁相索。","诗人王季重，山水群徵辟。","水山多幽韵，诗人少俗格。","碧柳垂陶门，青峰归谢宅。","陶谢不复还，水山动其魄。","骚歌有馀地，风雅无偏窄。","诗人欲继之，自许耽佳僻。","身携元化符，手把古刀尺。","中开金简文，上窥垂露迹。","何必嵩高竹，备徵科斗策。","岂俟蜀中桐，一扣临平石。","精灵既默聚，要妙归捃摭。","颇疑会稽来，此称再玄辟。","虚谷罕剩藏，幽泉避刻画。","诗人忽回首，风尘仰飞舄。","朝辞幽桂枝，暮整金台轭。","尽收萝薜颜，大启烟霞癖。","非关情性殊，毋乃盛名迫。","居诸不让人，晚暮徒相逆。","一刺虽灭磨，孤襟犹夙昔。","是时清梦馀，水山诏远客。","未必喧如静，方思损胜益。","春云入画图，秋霜留几席。","归来慎勿迟，岩阿转清碧。"]},{"t":"姚孟长学士睹余前诗谓诸同人曰读水山诏远客之语胜于北山移文感其言复有此作","f":"五言古诗","c":["仕宦多岐途，水山无定位。","幽人肆其怀，水山不可避。","此怀忽中易，水山安能媚。","余亦干进者，安知达隐事。","因思禹穴奇，适与淡衷值。","先生味其言，欲向水山示。","未获水山情，聊求读书意。","此中大有佳，捷径毋相累。"]},{"t":"楼上","f":"七言绝句","c":["一抹轻云护晓吹，盈盈楼上对花时。","春风若解吹红片，愿作东墙第一枝。"]},{"t":"花前","f":"七言绝句","c":["乱入花前共一枝，平分柳色较双眉。","春风不耐罗衣薄，缓步归来听晓鹂。"]},{"t":"赠陈子仪中翰奉使南归","f":"七言古诗","c":["皇华使者束轻装，谁奏骊歌四牡旁。","二载相依同舍客，漳潮咫尺未殊乡。","不谓离群今日意，忽因黯淡暮春肠。","春肠百结难相赠，春色犹堪问一方。","此去湖西春未尽，扁舟宛在湖中央。","千条弱柳垂朝碧，十里娇荷动午光。","游人但撷诗人料，西湖仍为西子妆。","千杯渌酒应时有，一曲清歌何可当。","我亦思归魂梦逐，愿随烟景继途长。","凭君留取春湖色，莫令秋葭结露霜。"]},{"t":"过细柳营","f":"七言律诗","c":["细柳名归重厚儿，棘门霸上尔何为。","备胡但有将军令，开壁宁誇介胄仪。","此日徐行观戒约，他时坚卧识旌旗。","祇今按辔过前垒，天子当年不敢驰。"]},{"t":"开卷有怀书寄方肃之徐九一在馆读书","f":"五言古诗","c":["开笈抚馀篇，嘿坐空叹慨。","譬彼孤飞鸟，日暮失行次。","翻翮自求心，疏林独憔悴。","有朋在远方，念昔同中秘。","满堂见目成，数友称心寄。","徐子誇俊拔，巨手施鸿锤。","方髯索清真，远格标危帜。","谓余怀古僻，相与析疑义。","文章自有神，气声自有类。","披衣联食寝，论述难相避。","安知言笑时，忽睹别离事。","君留白玉堂，我踞幽山位。","玉堂生虚清，幽山多窈异。","当年万古情，此日三秋意。","明月共燕吴，秋风通寤寐。","有梦未辞遥，于心明不二。","束刍念金玉，尔音莫遐弃。","新诗速置邮，枕宝毋终閟。","今人那许窥，古人或可企。","安能必如古，所欲求其至。"]},{"t":"江舟望月书寄宋尔孚辜端伯在都谒选","f":"五言古诗","c":["明月来清照，江流出远吹。","荷风无閒歇，柳色尚参差。","扁舟谁可溯，我友昔同斯。","江月见颜色，明我长相思。","伊人在一水，我友向天逵。","怀挟平生意，裘马共驱驰。","聚首亦何几，各有民社司。","宋子敦其性，辜君迈厥施。","始看发刃日，莫笑小烹时。","盘错应微别，刚柔各互师。","数年成远器，伯仲可肩随。","余怀甘寂寞，所志独何为。","君王借云壑，今古付骚诗。","举目耽幽桂，安能泣素丝。","江月浮清梦，风尘易涅缁。","出世应殊调，归山贵独知。","我心人未识，尔意或相宜。","聊因江月夜，示尔以胸期。"]},{"t":"次广陵过朱章华夜集时章华被言改官中翰","f":"五言古诗","c":["未上龙冈望，先求云水居。","邗江杯酒夜，秋色月桥初。","隋堤旧杨柳，犹照玉钩馀。","哀时抚遗迹，临眺独欷歔。","以此增离索，归怀速共摅。","便令西亭竹，映尔西江庐。","或使东阁梅，随我东山裾。","时心休错料，古意各踌躇。","风波无定所，宦海一污渠。","冥飞远缯缴，弹铗笑车鱼。","避人非避世，何毁复何誉。","且莫攀幽桂，终宜读素书。","身名分久暂，云风诏卷舒。","我欲乘潮去，于尔定何如。"]},{"t":"冒宗起招同王芳洲朱章华小集皆戊辰同人","f":"五言古诗","c":["东南多胜友，如斯复几人。","岂惟才力壮，能令气声亲。","披襟明宿昔，怀抱各清新。","我观时世客，惟思要路津。","世道多荆棘，时心满甲鳞。","何如一樽酒，淘洗令其醇。","以兹咸叹息，当杯莫逡巡。","且勿谦新贵，亦无骄贱贫。","但作平等意，醒醉总相匀。","糟酾共餔歠，此情亦未真。","情钟在我辈，心同是一身。","与尔成三益，何妨有四邻。"]},{"t":"邗江秋月夜","f":"五言古诗","c":["斜日侵疏牖，溯流杨柳隅。","晚风开夕照，转棹觅清酤。","舟人厌其数，安知意所愉。","澄江横素月，焉能独少吾。","秋月临秋水，秋光入画图。","月映秋如玉，水衔月似珠。","珠玉相辉耀，惟当在吾舻。","举目隋堤外，空使碧华趋。","锦缆人何在，迷楼那可呼。","我有紫霞想，不令素容孤。","水月能相载，秋风亦并驱。","皓魄依清景，应得洗心徒。","深宵银汉落，还向此中俱。","千年玄圃色，五夜共冰壶。"]},{"t":"将发广陵书寄李大生时大生奉使归如皋","f":"五言古诗","c":["秋光不可量，客思不可让。","所思在何许，悠悠绪不畼。","当兹露未晞，及此流芳壮。","从人一水中，苍葭或无恙。","忆在长安邸，伊我同微尚。","樽酒辄共倾，寸心时相向。","新诗月满束，和汝谁堪唱。","哀时避锥末，学古鞭独上。","每约还山期，预作远游舫。","务趁广陵涛，一尽江皋状。","洗心探石泉，写意镂幽嶂。","今来既浃旬，朝朝跂予望。","烹鱼未得书，安能悉尔况。","举目念征鸿，霄羽徒虚飏。","所希心异迹，未必今殊向。","已叹龙冈遥，还闻鹤野旷。","何当坐拂郁，使我空惆怅。","晚潮动千楫，晨风催五两。","长跪缄此辞，此词君亦谅。","他日君思我，岭梅春复放。"]},{"t":"林浴元民部邀游虎丘小坐入夜溯流归阊门","f":"五言律诗","c":["松风浮渌蚁，玉露点秋盘。","便许千人石，时为十日欢。","残香留碧草，初月动芳兰。","别后空回首，扁舟溯夜澜。"]},{"t":"杨维斗徐君和朱云子共邀舟游二首 其一","f":"五言律诗","c":["朋聚东南美，游穷日夜欢。","云山多气色，今古动波澜。","游鹿台何在，栖乌树几残。","请看波上月，复已挂幽峦。"]},{"t":"杨维斗徐君和朱云子共邀舟游二首 其二","f":"五言律诗","c":["金风吹碧野，玉露洒长干。","响屐犹堪想，悬晴那忍看。","清歌毋屡奏，高论可盘桓。","不感兴亡事，安知此会难。"]},{"t":"将至嘉兴舟行夜眺","f":"古风","c":["弱缆斜牵渡晚潮，秋风袅袅送轻?。","萧疏林影依云暮，蒙密人烟敛月宵。","来水潺湲如有诉，去山俯仰复相招。","清辉满目谁能数，漫许幽光入画描。"]},{"t":"将至崇德风雷交作大雨如注","f":"古风","c":["殷其雷，在南山侧，熌烁崩腾来自北。","须臾野隘平川迷，片片敲蓬何孔亟。","奔流走岸跃鱼龙，澎湃吞舟欲断纆。","舟子招招奈若何，鲛人泣夜疑昏黑。","声聚鬼神若有闻，势落高深未许息。","孤舟有客正徘徊，闭窗独坐敛颜色。","飞光拂眼悟空华，万点披襟去烦臆。","云风不变岂称奇，天地争回畴堪测。","我有文心寄橐籥，溟涬未穿那可匿。","愿假扶摇上碧霄，且倩滂沱濡砚墨。"]},{"t":"舟行眺听","f":"七言古诗","c":["披衣眺听秋已极，野意川心俱黯默。","回风作意启晨熹，万象凄其感秋力。","远树参差翠欲浮，前峰一带光如拭。","数行白鹭横青湖，几个征鸿收倦翼。","上下徘徊露霭中，弱缆欹斜疑相即。","举头忽见众冥冥，自愧劳人机未息。","会当洗心向石泉，开怀露膈平胸臆。","即见随缘付眼前，我自忘情物自得。","岩壑萧条世岂争，烟霞廓落人谁逼。","偶书此意问秋云，秋云片片生遥色。"]},{"t":"曹允大邀游西湖穷日之力继以夜月","f":"七言古诗","c":["里湖淡淡外湖泓，山光如坠水光平。","水水山山何尽极，清歌妙舞日盈盈。","主人爱湖兼爱客，为余酤酒向湖倾。","买舟携酒竭游力，湖水湖山纷送迎。","一日思穷山水意，西湖笑杀起秋声。","我无歌舞添湖景，聊从山水问湖情。","但使一杯为湖醉，稍迟东月又湖生。","湖生月色千年好，月与湖光一片成。","歌舞人归云尽灭，水山秋至露如英。","此时万籁宜俱寂，湖月偕谁共秋清。"]},{"t":"再寄允大","f":"五言古诗","c":["离心销古道，秋意出长干。","赤叶枫初变，苍葭露始寒。","言归愁碧草，怀尔念幽兰。","面目馀真气，诗歌忆故欢。","清思悬物象，高论起云端。","子建才名大，林宗品藻难。","冥搜空远寄，披沥总齐观。","去去遥相忆，西风动晓澜。"]},{"t":"过钓台","f":"五言古诗","c":["我闻富春叟，名悬霄汉端。","身避云台选，心依水石寒。","玄纁尔何物，纷纷动泽兰。","物色徒相访，结念本如磐。","浮云山外出，客星座上看。","加腹寻常事，那使天象干。","人生各有志，助理亦非难。","举目视周党，犹能薄一官。","以兹长叹息，振衣还故峦。","试看马革裹，何似羊裘安。","滹沱意未报，回溪翼几残。","祇今千馀载，惟传七星滩。","晓日临苍碧，秋烟拂钓竿。","清风不可见，玉露洒朝澜。"]},{"t":"自龙游登陆至衢州","f":"七言古诗","c":["舍棹登途秋逾仲，水意滩声劳远送。","轻云出岫展朝图，作意相从共远途。","无数凉烟下奔壑，几层绿黛秋难薄。","秋去秋来色倍新，不向居人向旅人。","旅人何求莫遑息，举目看云泪沾臆。","黄花无主寄疏篱，玉窖浮清复照谁。","谁人堪持此意说，白云含露光如雪。","云光独见行路难，我家山水久幽寒。"]},{"t":"玉山道中三绝 其一","f":"七言绝句","c":["忆昔行云云有神，今逢山玉玉如人。","当年入梦原非梦，今日疑真亦未真。"]},{"t":"玉山道中三绝 其二","f":"七言绝句","c":["试将玉貌与花评，赢得芳华近远生。","裙妒榴红真妒杀，脸分芙艳实分明。"]},{"t":"玉山道中三绝 其三","f":"七言绝句","c":["此中真意向谁传，未必芳心许世怜。","安得丹青留窈谷，漫将绿绮动幽泉。"]},{"t":"贵溪枉道为邑令所绐也诗以示之","f":"五言古诗","c":["家犹千里望，客动四时心。","白云迷马首，岐路转荒沉。","慇勤贵溪长，归程巧相禁。","令我舍周道，反从他径寻。","我无穷途泪，尔昧指南针。","当年问津者，亦受耦耕侵。","彼惟避世侣，未必附缨簪。","去去何足讶，松竹自有林。","松风甚幽远，竹露颇清深。","生刍在空谷，宁殊玉与金。","我驹我自策，不用劳尔音。"]},{"t":"东乡道中苦雨","f":"五言古诗","c":["我行循秋意，朝朝率西浒。","入山本自深，况复穿林薮。","谁携南浦云，尽作东乡雨。","弥旬见伏阴，每旦风雷怒。","岩阿少剩藏，烟霭相倾吐。","幽壑染黄精，疑是千山乳。","万象纷凄其，历乱谁堪主。","柳懒如欲眠，竹醉犹解舞。","山鸟无一飞，山人多闭户。","谁怜万里客，独行何踽踽。","所嗟行路难，雨行倍辛苦。","目断岭南峰，迷离安可数。"]},{"t":"百山行五十韵繇浙江江山闽山以至潮山","f":"五言古诗","c":["山行尽一月，踰山历万乡。","入山又出山，宛在山中央。","山图所未及，山经或未详。","夏山翠如滴，秋山净若妆。","冬山深如睡，春山远更芳。","不尽山四时，山情那可量。","江山自严厉，溪山转幽凉。","神山未获见，海山意中荒。","我闻山异德，始知山各疆。","朝陟东山巘，山日飞混茫。","午憩南山侧，山风扑面飏。","晚出西山岫，山云尽可囊。","夜倚北山麓，山雨欲浮床。","山岚时结瘴，山露乍凝霜。","何木不山落，何草不山黄。","落木悲山末，黄草敝山旁。","山木犹有枝，山草孰堪纕。","此尽山糟粕，岂见山英芒。","山草非芝瑶，山木愧扶桑。","山樵恣斤斧，山牧自徜徉。","欲穷山变化，久为山低昂。","穿穴看山鼠，扑树突山獐。","伎俩凭山鬼，依倚任山狼。","迁鸟出山谷，雌雄立山梁。","求山仍求友，山集又云翔。","颇怪山中物，未必与山忘。","何人买山隐，何士构山堂。","紫霞依山栋，碧霭吐山房。","山葵供小摘，山竹表幽篁。","山居虽暂许，山意岂堪偿。","山不厌人閒，人莫厌山长。","心能与山静，山亦与人商。","久从山终始，姑使山颉颃。","山朝复山暮，与山俱未遑。","我仆叹山砠，我马鸣山冈。","采山人不见，何处置山筐。","山巅馀鸟道，山径仄羊肠。","崔嵬极山致，屈曲探山藏。","举头问山隐，山书秘何方。","低颜语山客，山桂尔毋戕。","山盘五十馀，惟有泰山当。","山池二十八，或倍华山阳。","彼山标千古，山以名益昌。","此山阻遐僻，名晦山何妨。","山之言产也，不产山无良。","或曰山为宣，非宣山曷扬。","我有家山在，俟我山始彰。","东山与西山，咫尺共山光。","近山情可悉，遥山意可望。","聊以家山绪，先矢百山行。"]},{"t":"入门","f":"七言律诗","c":["入门嘉庆喜光盈，庭菊阶兰亦聚迎。","里党休推新贵客，冰衙不改旧书生。","北山未拟均贤什，东海私宽一乐情。","倖沐皇恩休岁月，谁言子职但温凊。"]},{"t":"循东溪旧书室","f":"七言律诗","c":["黄花一夜已全开，玉水浮光莫浪猜。","水意初欣游子至，花情久忆故人回。","溪山漫许烟霞绕，泉石犹劳笔墨裁。","饶有荒园堪结构，蓬门遍把白云栽。"]},{"t":"杨乐庵年友建慈云寺既成招饮索题二首","f":"七言律诗","c":["西日衔峰待客来，玄堂清酌为谁开。","已飞天镜浮霜树，犹假禅灯照绿苔。","苏晋惟依绣佛袋，陶潜能引白莲杯。","我无焚骨当年表，自许颠僧竟夕陪。"]},{"t":"除夕雨","f":"七言律诗","c":["残年忽使暮云遮，岁雨萧萧送晚华。","颇忆香街闻爆竹，愧无彩笔颂椒花。","和同已觉联天地，优渥仍看尽迩遐。","自是皇仁东渐海，波臣万里沐恩赊。"]},{"t":"庚午元日仍雨","f":"七言律诗","c":["新年仍是旧年人，梦唤春光与日新。","犹记冰衙诸弟子，也同螭陛列词臣。","祇今衫履供幽步，遂有烟霞动远身。","仰望云天歌复旦，却欣雨色润芳辰。"]},{"t":"春日山居即事十首","f":"五言律诗","c":["春秋何局促，今古日来还。","自了非吾事，长勤庶可攀。","希贤须远步，志士多苦颜。","未遂男儿愿，空使一生閒。"]},{"t":"和尔韬悼亡姬月容二作姬葬黄岐已一周矣 其一","f":"七言律诗","c":["娇魂已去落馀香，一度愁吟一断肠。","春去绿云愁远黛，秋来芳草怨斜阳。","祇怜裙断难留燕，长恨箫吹莫引凰。","为问使君他帐里，跚跚可识旧容光。"]},{"t":"和尔韬悼亡姬月容二作姬葬黄岐已一周矣 其二","f":"七言律诗","c":["长有春山守恨眉，泉幽涧冷若相期。","一抔香散新残粉，百丈愁牵不断丝。","须信魂迷江北水，可堪泪染岭南枝。","翻怜如六旧芳冢，同向春风起怨疑。"]},{"t":"追和元诚拊髀思颇牧之作","f":"五言古诗","c":["汉主忧匈奴，每饭意钜鹿。","冯郎垂白首，犹能语推毂。","不知今魏尚，宁问古颇牧。","文吏操法绳，而无宽大目。","漫有拊髀思，谁削功首牍。","千载听其言，壮士多颦蹙。","当日共花砖，此语曾追录。","何当阃外事，长寄书生腹。","喜峰动胡尘，盈庭方肉朒。","内虚邦政堂，外少登坛宿。","忽见金与刘，慷慨螭阶伏。","人目二痴儒，帝命无更仆。","金子监内军，君实司戎轴。","一军惊韩信，二快闻鲁肃。","遂携忠愤麾，往当遵永镞。","一朝酬主恩，四海环相哭。","是时我山居，遥传罢朝粥。","未获信陵车，空念蒲胥辐。","岂忘开路心，永念金台筑。","嗟君发轫初，矢志在沟渎。","何必据鞍人，此意千秋独。","男儿愧手中，安能死岩谷。"]},{"t":"虏儆烽传步谢韶石廉宪约冯尔韬勤王之作","f":"七言律诗","c":["男儿许国意如何，一剑长应十载磨。","每见辕驹皆局促，敢同轩鹤共婆娑。","渑池此日看冯奋，门限他年喜谢过。","自愧单骑安可附，且从棋墅听清歌。"]},{"t":"虏儆已息偕尔韬书怀寄广昌令宋尔孚","f":"七言律诗","c":["天道还应格七旬，徒从事后感时新。","我无竹马酬儿辈，君有梅花付邑人。","长铗歌鱼空太息，角巾折雨倍逡巡。","谁能郁郁终居此，此意惟堪向尔申。"]},{"t":"送澄海令吴斯椒北观斯椒专以文章诱士不任刑政作三十韵诗宠之且以劝之","f":"五言古诗","c":["古人不可见，循吏亦已远。","试为左右容，阿墨何相反。","陵迟叔季日，毁誉俱混混。","岂不贵循良，谁甘露愊悃。","岁计或有馀，背憎多朝噂。","是以巧宦情，趋末不趋本。","时心日竞驰，之子气深稳。","自从海邦来，怀抱终恳恳。","厌操新发硎，时出旧琨琬。","开襟向澄流，须眉明淡婉。","绿水照琴书，春风动襫蓘。","每痛鹰鹯语，惟求损又损。","顑颔事上官，亦未甘肥遁。","携彼仁心质，时垂冰雪幰。","论文款柴扉，耽幽宿蕙畹。","清谈废早衙，苦讽忘昏饭。","枳棘虽暂栖，荪蘅堪偃蹇。","人每颂金锡，尔毋逊赫咺。","吴祐在胶东，冰夫从风偃。","闭阁每自思，布衣终却返。","今人不古如，古意凭今挽。","我畏滔汶流，恃尔为堤堰。","我思恬漠乡，恃尔能终恳。","勖哉之子怀，他心独予忖。","携持共千秋，岂惟时世键。","我闻密令名，非为华貌烜。","行已在清浊，所记胡矛盾。","已浊清何存，去华名未晚。","文翁教可成，太丘声亦焜。","谁道南宫台，不附褒德衮。"]},{"t":"中秋日送尔韬报最同舟至铺前溪泛月言别","f":"五言古诗","c":["每旦情不惬，无那秋光嬲。","忽闻长铗歌，归去当兹晓。","溯流从一方，荷风穆清醥。","漫将郭泰舟，一向冯车绕。","苍蒹拂暮潮，层阴度轻鸟。","余来君意舒，君去余心悄。","何期百载心，暂折秋林杪。","餐鱼厌鳄溪，望鸿思云表。","云表有天逵，金台堪远眺。","忆自金台来，旭日当空皦。","陋彼燕宫筑，独与虞门绍。","嗟予忝骏骨，况君真騕袅。","行矣慎驱驰，勋节咸兹肇。","使君宰天下，亦如烹鲜小。","鸣琴不下堂，百里开纷纠。","逐寇扫千妖，赈饥生万殍。","凡此特两端，口碑垂亿兆。","岂知至化源，所贵能无扰。","黄山日巍峨，玉水时深窈。","颜色留水山，胸期在缥缈。","苦调托长吟，离月今宵皎。"]},{"t":"羊城秋怀十绝 其一 客居嗤任达之幼舆何必乃尔拟閒情于靖节始可言诗","f":"七言绝句","c":["独守长秋六尺床，昏昏非醉亦非狂。","客居误傍霜红树，每夜秋声点客肠。"]},{"t":"羊城秋怀十绝 其二 生平","f":"七言绝句","c":["生平未解市婆娑，种种痴愁自恨多。","简点侬身底事可，问卿何故不飞梭。"]},{"t":"羊城秋怀十绝 其三 错认","f":"七言绝句","c":["错认秋光忽似春，相逢疑假梦疑真。","暗中添得如云侣，翻恨缘深误作邻。"]},{"t":"羊城秋怀十绝 其四 朝容","f":"七言绝句","c":["清朝汲井灌芙蓉，谁捣玄霜擘面逢。","不管羁人消渴甚，尽倾玉露洗朝容。"]},{"t":"羊城秋怀十绝 其五 彤管","f":"七言绝句","c":["叶上题红莫浪猜，愁心一片几成灰。","自贻彤管终难报，怯向词闺露小才。"]},{"t":"羊城秋怀十绝 其六 寄语","f":"七言绝句","c":["须知荷叶避花开，长令清风拂座来。","寄语秋风同爱惜，莫教玉露减红腮。"]},{"t":"羊城秋怀十绝 其七 解语","f":"七言绝句","c":["解语秋花花不如，秋风每夜伴花居。","风寒莫遣花枝瘦，长使秋光护月初。"]},{"t":"羊城秋怀十绝 其八 开缄","f":"七言绝句","c":["小叠红笺压镜台，纱窗低语背人开。","开缄莫道无佳句，恐费香奁竟日裁。"]},{"t":"羊城秋怀十绝 其九 马上","f":"七言绝句","c":["荷气兰光秋更清，看花马上倩花迎。","自怜得意如花意，敢向花前见俗情。"]},{"t":"羊城秋怀十绝 其十 楼上","f":"七言绝句","c":["楼上秋光乍有无，客中心事半荣枯。","朝云暮雨千年梦，明月清风几夜俱。"]},{"t":"赠答诗十绝 其一 楼居","f":"七言绝句","c":["生平少小爱楼居，自倚秦家玉未如。","谁纵西风吹白露，长随落叶绕红裾。"]},{"t":"赠答诗十绝 其二 长恨","f":"七言绝句","c":["长恨秋风似转轮，几番吹却后来人。","清宵漫倚疏桐月，云最堪怜是妾身。"]},{"t":"赠答诗十绝 其三 自怜","f":"七言绝句","c":["自怜十五画长眉，暗壁低头未几时。","此际相逢君莫问，如今正好共箫吹。"]},{"t":"赠答诗十绝 其四 幽窗","f":"七言绝句","c":["荷香欲散菊初华，长与幽窗映碧纱。","自得郎心同似玉，休言妾貌果如花。"]},{"t":"赠答诗十绝 其五 暮风","f":"七言绝句","c":["君言芙艳晓来佳，妾爱荷香暮入怀。","晓露畏同君意竭，暮风长与妾心偕。"]},{"t":"赠答诗十绝 其六 秋华","f":"七言绝句","c":["郎言妾瘦比黄花，玉露凋伤莫怨嗟。","赢得孤身随月照，真成薄命倚秋华。"]},{"t":"赠答诗十绝 其七 半臂","f":"七言绝句","c":["箱裙久褪石榴红，半臂初迎桂子风。","已办双蛾劳綵笔，何须求凤倚焦桐。"]},{"t":"赠答诗十绝 其八 离弦","f":"七言绝句","c":["千载琵琶一恨传，写出幽闺最可怜。","此夜为君翻数曲，月明风细动离弦。"]},{"t":"赠答诗十绝 其九 离月","f":"七言绝句","c":["昨宵离月共花阴，今日行云动碧岑。","云影任随君作伴，月华留与妾当心。"]},{"t":"赠答诗十绝 其十 别梦","f":"七言绝句","c":["别梦馀心犹共锁，愁容何力可相开。","请伊再向西风问，秋恨如今裁未裁。"]},{"t":"张仪舌严光足","f":"古风","c":["张仪舌，梁楚缺。","严子足，富春缩。","缩者还能伸，缺人先自辱。","当年寸舌问妻存，此日两足加帝腹。","终当持钓为客星，何事游谈师鬼谷。"]},{"t":"小儿腰老人履","f":"古风","c":["张良汉帝师，陶潜晋徵士。","万户何足誇，五斗何足耻。","汉晋有废兴，达人毋彼此。","授书逢圯上，束带羞乡里。","先生不折小儿腰，孺子曾取老人履。","归去仍依黄菊篱，功成亦步赤松子。"]},{"t":"邯郸才人嫁为厮养卒妇","f":"五言古诗","c":["少小邯郸宫，春春弄碧柳。","学步未全工，扬蛾那可久。","一朝金阙颓，宿昔朱颜丑。","有梦向黄粱，何心问鲁酒。","厮养尔为谁，曾御赵王否。"]},{"t":"胡无人","f":"古风","c":["长城万里未为长，长缨所系必名王。","尔非我类奚相逼，自恃□□天乃亡。","薄伐长驱今古一，胡如风雨我如日。","圣人举事贵其全，长子贞师必以律。","穷兵黩武又何为，扫穴犁庭自有时。","自有时，胡运竭，编户为州尽穷发。","休屠牵马至，利干煮羊来。","胡无人，敢徘徊。"]},{"t":"鄱阳晓望","f":"五言绝句","c":["湖光初照耀，山意转氤氲。","望望空明合，水天何处分。"]},{"t":"因念昔者寺僧乞诗子瞻有银河谪仙之语古今闻见不同飞流溅沫岂尽为徐诗洗恶哉","f":"七言绝句","c":["银河一派玉江垂，日落天清倍可思。","自得三春增异色，更飞千尺写仙诗。"]},{"t":"池州阻风","f":"五言古诗","c":["天风九万里，直下大江东。","海波十千丈，总令三山濛。","龙螭趋巨壑，蛟鳄舞阴空。","陵谷须臾变，高深那可冯。","此时愁坐客，天水日堪同。","披襟依雪浪，接瞬隐苍穹。","烟云无定色，气势转相雄。","击楫今焉取，垂纶力所穷。","我怀惜阴意，苦遭灵曜懵。","仰看羲辔落，或恐地维汎。","自怜昏与旦，飘摇似转蓬。","寄语布帆人，此际莫匆匆。"]},{"t":"望春峰积雪漫成二作 其一","f":"五言古诗","c":["春风日淡融，春山何凛冽。","青青岭上云，白白峰头雪。","岭云忽去来，峰雪每凝结。","所叹幽而凉，亦惟高始洁。","颇似素心人，潇潇独关闭。","匡居相八寰，缁尘安敢涅。","宁静出孤怀，精神多自悦。","虽与俗情违，亦非人事绝。","馀滋润百荄，光华未可竭。","我思泉下蒙，复念井中渫。","何如此一峰，不受虚名窃。"]},{"t":"望春峰积雪漫成二作 其二","f":"五言古诗","c":["层壁系扁舟，对此春山凸。","远眺出殊光，轻烟似可刷。","误疑峰上云，映日浮晖缀。","稍知寒意侵，始见幽岩雪。","千林拂素华，万壑嘘遥冽。","非惟色在空，庶以清涵洁。","岂如阛阓姿，门多车马辙。","飞飞向华筵，但为歌舞悦。","空嗟谢子盐，枉费陶公屑。","是以静者怀，于兹堪永结。","幸有春风来，得与冰壶撷。","顾盼隐晨昏，悠然世心绝。"]},{"t":"愁二水","f":"楚辞体","c":["江有水兮春有风，水西来兮风自东。","两相遇，各相冯。","岁之朝，吾以同。","日兮杳杳，旬其再中。","睇烟光之怫郁兮，几含思而自蒙。","遭阳侯之泛滥兮，盖为余而造雄。","心靡靡而难竞兮，就欹危之片篷。","迷宵旦以摅方怀兮，绪沉抑而莫汎。","愿寄辞于飘云兮，揖东君而陈衷。","何回汉之浮浮兮，疑鼓浪于丰隆。","望前山兮偃蹇，与极浦兮初终。","伤幽峰之泻绿兮，怨碧渚之流红。","惜吾不及无心之落花兮，依湛湛之露枫。","折琼枝与瑶华兮，护微芳之远丛。","恐时岁之如斯逝者兮，及秋霜而转蓬。","吾且夷犹以自怡兮，观万象之魂熊。","觅渔歌于佪溆兮，悟身外之塞通。","时亦犹其未央兮，进亦无求其太匆。","睹惊波之杳至兮，随游雾以塞充。","接朝容之浩淼兮，下晓气于巃嵷。","道何远而不达兮，志何立而不崇。","万变其情岂可极兮，伫寸进之为功。","吾将过牛渚而燃照兮，依鹭洲而启笼。","藐蟠踞之龙虎兮，羡冥飞之鹄鸿。","盼白门之遥色兮，悲金粉之日空。","曾不知朝之几变兮，孰两江水之可穷。"]},{"t":"望三山","f":"楚辞体","c":["若有人兮溯长干，阻阳侯兮心恻酸。","沿春洲兮采芳杜，循花浪兮结幽兰。","幽兰幽兮聊为佩，芳杜芳兮遗所欢。","欢何在兮在水，水一方兮漫漫。","云容与而独往，雾迷离以众瞒。","谅所思之未达，欲缄志而无翰。","长顑颔兮何益，聊儃佪兮自宽。","朝击汰而欲前兮，延伫乎意中峦。","暮扬舲而反缩兮，归纡轸之旧湍。","悔占风之不早兮，依碧渚且焉止观。","苟直寻而枉尺兮，非余心之所安。","逐轻潮以从鸥泛兮，凭弱橹而问渔竿。","虽迟滞其何畏兮，苟余情其信殚。","心郁坚而弗拔兮，思蹇产而毋残。","俟狂吹之稍杀兮，及天吴之未欢。","人与人其共力兮，日与日而相攒。","忽逍遥以反顾兮，终九万其一弹。","前程各有所至兮，余独婵媛以为端。","虽闷瞀吾犹未变兮，岂余衷之可阑。","噫吁嘻，春弥月兮绪千端。","全销白日兮此春澜，半落青天兮此地看。","岂波臣之骏奔兮敢后，维下风之羽翼兮实难。"]},{"t":"姚永言自维扬至过访","f":"五言古诗","c":["为客羁怀远，遭春幽兴长。","飘泊盈千绪，流洄叹一方。","我友东南俊，逸气表维扬。","相思能命驾，就我春江航。","舟楫寒温外，茶酒出篇章。","手中白缟带，腰下锦奚囊。","双眸含碧水，数语摇轻霜。","是时杨柳岸，停午动烟光。","岂惟七分读，能流百丈芒。","忆共冰天署，生刍束芸香。","词英兼宿辈，同时避雁行。","君才真杰立，我意日徬徨。","相携视冥漠，举世尽茫茫。","离群忽三载，膺背永相将。","不意金陵水，遥分白玉堂。","高谈竟晨夕，薰然耳目张。","独念蓬飞子，每疑素业忘。","非缘今日会，此游空自忙。","相逢姑劝志，焉敢问行藏。","明朝重执手，前期或细商。"]},{"t":"次日访永言于报恩寺","f":"五言古诗","c":["肩舆循柳岸，拂袖尽烟风。","寻幽无近远，闻见莫匆匆。","绵邈钟声外，高人古寺东。","入门值君出，庭花为客公。","命花留我住，独坐使春融。","须臾接谈笑，诗酒复相同。","玄言多绝倒，清绪未能穷。","开怀获素友，焉得不披胸。","我有和氏璞，三年色似蒙。","我有雷生剑，每夜气摩穹。","将携剑与璞，遥献碧霄宫。","因思玄圃际，积光竞魂熊。","更闻欧冶局，纯钩动远空。","我剑方藏匣，我璞俟人攻。","未甘同石弃，终疑跃水中。","以兹长叹息，还向白云笼。","惟君先得我，举酌共溶溶。","术售非吾道，周防宜在躬。","输心逢达者，回首谢时雄。","愿持今日语，常寄百年衷。"]},{"t":"春闺八首 其一","f":"五言律诗","c":["池前君栽柳，君去碧丝长。","丝丝相纠结，叶叶自飞扬。","不解留春住，偏能断妾肠。","妾肠丝叶内，东风莫太狂。"]},{"t":"春闺八首 其二","f":"五言律诗","c":["庭花多作意，红花又白花。","一般春散色，相倚妾为家。","晓来千片落，似欲少春华。","不闻春叹息，惟见妾咨嗟。"]},{"t":"春闺八首 其三","f":"五言律诗","c":["桃花红烂熳，李花白参差。","向日娇同醉，临风懒独吹。","已能分妾面，更欲动君思。","桃李心如此，妾知君未知。"]},{"t":"春闺八首 其四","f":"五言律诗","c":["花落春毋赧，花开春莫矜。","花容徒竞日，妾意浑如冰。","日影须臾变，冰心百岁凝。","使妾同开落，于心诚不能。"]},{"t":"春闺八首 其五","f":"五言律诗","c":["自君之出矣，无意上妆楼。","尽日飞蓬首，朝朝叹白头。","未烦杨柳色，独见深闺愁。","朱颜君错过，何事觅封侯。"]},{"t":"春闺八首 其六","f":"五言律诗","c":["黄莺枝上语，双双出可怜。","衔花咀晓露，入树倚轻烟。","尔来春欲半，人去日逾千。","空将千日绪，啼向半春前。"]},{"t":"春闺八首 其七","f":"五言律诗","c":["朝来云际羽，忽向绮窗飞。","飞飞传锦字，开视动春晖。","是郎手中迹，入袖芳菲菲。","收藏兰麝箧，留芳待郎归。"]},{"t":"春闺八首 其八","f":"五言律诗","c":["深闺无气力，刀尺为君持。","腰带思畴昔，襟怀起怨疑。","裁缝聊如此，熨贴那堪知。","所愁黄里叹，不畏好人嗤。"]},{"t":"柳中人四绝 其一","f":"七言绝句","c":["一苗活影向风前，两叶残愁照水边。","莫是浣纱当日伴，含情敛意就春烟。"]},{"t":"柳中人四绝 其二","f":"七言绝句","c":["水分娇面未全明，柳入双眉共一情。","举目跚跚云里坠，销魂冉冉画中成。"]},{"t":"柳中人四绝 其三","f":"七言绝句","c":["颇疑流水动朝馡，错认荷风上晓衣。","愿借微风风不已，便随芳气达罗帏。"]},{"t":"柳中人四绝 其四","f":"七言绝句","c":["柳岸风开叶叶光，朝来何事断人肠。","前山纵有行云色，春梦惟依水一方。"]},{"t":"月行","f":"五言古诗","c":["幽溪明素色，波月正潆洄。","溯洄当月夜，清影曳高桅。","舟入银河去，人疑雪夜来。","野鹭惊还宿，林乌止复猜。","水山同一照，烟树两难裁。","临流山意落，击楫水光开。","渔歌深入浦，耳外独徘徊。","所谓伊人者，此际亦悠哉。"]},{"t":"中夜声色","f":"五言古诗","c":["深宵索幽异，物象总同同。","溪月光如串，林烟白似通。","清沙流远照，碧渚动虚空。","维舟依绝岸，春色满幽蓬。","澹然心不系，身与波上风。","风动潜鱼窟，春依宿鸟丛。","鸟鱼方向客，虫响莫匆匆。"]},{"t":"晚泊与山对卧","f":"五言古诗","c":["幽溪出素泉，春山留淡薄。","落日挂峰头，我舟系其脚。","轻烟拂翠微，远雾环阴壑。","陵麓势多端，水石何凿凿。","碧渚映黄昏，清沙互隐跃。","高深一钓如，左右双篷若。","仰观星汉联，颇畏天河落。","羁心自抑扬，高枕望寥廓。","衾抱夜流奔，梦从山鬼谑。","愧尔山中云，及此共冥寞。"]},{"t":"阴眺","f":"五言古诗","c":["春色终难了，山情莫漫酣。","风际无宁木，雨馀多滞岚。","谷影虚空外，溪光近远涵。","入眼千峰翠，当心一水蓝。","苍茫供独对，渊嘿启冥探。","使人愁应接，转令客思憨。"]},{"t":"披襟","f":"五言古诗","c":["披襟当远树，悠然共水山。","天籁驱之出，春情不可关。","春光将欲去，春风那得閒。","微凉下苍壁，虚声走碧湾。","烟云相对发，忽向此中还。","清泠动耳目，吾亦散羁颜。"]},{"t":"山情","f":"五言古诗","c":["天意微欲落，山情近远涵。","晴云低岫白，霁霭入溪蓝。","漾楫幽峰麓，孤光隐碧潭。","菰蒲前冉冉，萝薜近毵毵。","敛意供冥索，舒心恣远探。","人与山莫逆，对水亦成三。"]},{"t":"渔樵","f":"五言古诗","c":["积雨漏岩壑，洪波压素流。","巢居倾野聚，穷乡鲜一留。","樵子挥长斧，渔人刺小舟。","纷纷碧渚际，历乱自相雠。","渔人谓樵子，此利固渔收。","溪山应有界，云何出位谋。","诸樵但摇首，连臂歌薪槱。","林峦岂余爱，尔亦缘木求。","我闻斯语辩，永叹世情偷。","满目悲陵谷，伤心畏戟矛。","谁能驱垄断，孰与破侵牟。","解维辞二物，鼓棹向群鸥。"]},{"t":"过皂口舟为巨石顶碎赖前舟回救得脱","f":"古风","c":["水意分下上，故以诸滩级。","谁驱蜀道难，尽使章江拾。","云向石头生，山从波面立。","?崒破微痕，呀吭留众褶。","摆浪出孤篷，逆行势转涩。","弱缆助群篙，咫尺难相及。","得失须臾事，参差介于粒。","汹若动我前，方与奔湍揖。","稍忧众力疲，所畏崩流絷。","森森百剑铓，左右倾棱楫。","岂知伏莽浮，惊涛自中入。","俯观得巨礧，颇怪舟如笠。","颠沛且何为，呼号情所急。","一苇自南来，危魂聊粗集。","三叹此洄从，艰险胡多袭。","恐惧不须辞，愁闻舟子泣。"]},{"t":"泊攸镇","f":"五言古诗","c":["山非溪不润，溪非山不幽。","溪山相曳绕，相得转相求。","绿渚衔青壁，群峰下碧流。","恍疑太虚澹，时将物象收。","轻风来窈谷，兰芷在前洲。","跂远人何似，一苇自悠悠。","心微迎鸟语，意得比鱼游。","灭明村火见，孤缆向昏投。","所思不可遗，采芳为谁留。"]},{"t":"过赣关","f":"五言古诗","c":["舍棹就前峰，停桡依急濑。","举目望巍城，倒影如悬盖。","东西画二流，千桅聚一带。","奔溪忽罢行，飞烟日可绘。","先王措不倾，必求当要害。","相彼粤闽冲，形势此为最。","为关别有心，区区宁计会。","未闻惟正供，独烦中饱嘅。","堂堂半刺客，岂复称牙侩。","我欲副其求，赠以青山霭。","谁能捐有馀，稍足医无赖。","莫使望乡人，神飞东岭外。"]},{"t":"梦醒","f":"五言古诗","c":["春日迟迟下，春山处处青。","春光多懒困，春色未飘零。","窈意留莎草，微芳发渚馨。","双燕飞还语，群鸥去复停。","斜阳粘翠壁，返照及疏棂。","孤清隐顾盼，幽人自渺冥。","披襟初一眺，物象满前汀。","落尽高天日，梦游乍遣醒。"]},{"t":"深睡","f":"五言古诗","c":["雨馀朝梦添，春倦羁云惹。","睡乡未远遐，扁舟颇潇洒。","高枕对青山，侧身依绿野。","千年陶窗北，百世庄园下。","自谓羲皇真，何知蝴蝶假。","古来贤逸人，一一供臂把。","清风卷篷入，怀抱真堪写。","葛天有遗民，惟我或是也。"]},{"t":"舟倦连日得诸山周旋晚泊口占二十韵","f":"五言古诗","c":["久客扁舟倦，春溪百象玄。","溯洄频屈指，山水日齐肩。","中央一明镜，左右双翠钿。","几曲藏深树，随地有村烟。","牧子攀枝过，樵夫倚石穿。","持筐饶野妇，结伴共来还。","山果多盈掬，山花亦自妍。","薄暮归人尽，好鸟独连翩。","虫声时在谷，猿啸必临巅。","嵯峨诸石向，老大百藤牵。","久视心慌忽，遥看意纠缠。","谁能招隐士，吾欲漱飞泉。","深岩存化迹，山情那可专。","菁华山未竭，犹许独裳褰。","相招应有素，暂泊岂非缘。","即见堪延赏，于兹更索诠。","苍茫归结撰，心目几周旋。","翻宜舟楫钝，得使幽佳前。","羁颜聊自适，胜趣颇堪传。","漫持终古意，感叹及千年。"]},{"t":"自汀州下小刀溯流","f":"五言古诗","c":["一舟较掌宽，掀翻付濑速。","碧渚乍分维，青峰已在掬。","游子密惊魂，篙师暗理舳。","谈笑轻波澜，歌讴相趁逐。","左右割巃嵷，抑扬开纠蓼。","崩腾若舍辔，洄漩似转毂。","颇疑惶恐派，十八馀伸缩。","何殊香炉上，九天悬布瀑。","旦昏几何时，千山破含蓄。","谁能尽山情，或恐漂地轴。","高湍忽荡胸，远浪还吹腹。","我思嵌岩际，亦自有幽谷。","自同急涧奔，白云谁敢宿。","前贤足未到，神奇多隐覆。","平生游远意，所至凭心目。","对此欲何言，临深尤蹜蹜。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其一","f":"五言律诗","c":["人言秋气悲，我爱秋光洁。","每当玉露时，复睹黄花节。","清影在东篱，高人心自悦。","含意待冬霜，梅花又可折。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其二","f":"五言律诗","c":["黄山飞晚翠，玉水动秋清。","共传终古意，远出四时情。","始知流峙物，长含元化精。","万象殊多妄，惟此见其诚。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其三","f":"五言古诗","c":["鹏飞几万里，鹪巢但一枝。","赋形分小大，谅非物所为。","至人超象迹，鞭心独在斯。","凌虚上寥廓，时俗安可知。","九州不足步，南北岂云岐。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其四","f":"五言律诗","c":["风度曲江流，文心潮海见。","千里共东粤，犹自称乡县。","步公白玉堂，岂为清华羡。","长吟感遇篇，已觉秋思变。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其五","f":"五言古诗","c":["风云不可定，日月乃如流。","我无烟霜质，亦非波没俦。","但识浮生理，何须不死求。","希贤怀隐愧，入世抱深忧。","圭璧资磨琢，岂不如学脩。","一自高山仰，谁言天路悠。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其六","f":"五言古诗","c":["苔岑自有臭，松竹自有林。","虽异同堂语，应留隔代心。","荷风朝未歇，桂露夕已深。","遐征无远翼，嘿对几幽寻。","举目东西岭，分此白云阴。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其七","f":"五言律诗","c":["兰蕙摇晨风，菲菲不可息。","绿叶垂紫茎，亦自有殊色。","我欲贡瑶台，果值凌风翼。","结佩吾将行，琼爢斯可食。"]},{"t":"秋斋独对阅张曲江集追和感遇诗八作 其八","f":"五言古诗","c":["金鉴千秋皎，阴管一阳溶。","片言铸公鼎，只字起黄钟。","览德来高凤，无首戒群龙。","白衣明反相，城府避深胸。","去去荆州史，冥飞那可从。"]},{"t":"闻陈集生学士编选粤诗赠诗三十韵","f":"五言古诗","c":["东南厚地流，瀛渤迷天宇。","扬马溯归墟，李杜循荒浦。","精魄恐遂沉，日夜奔轩舞。","三山那可凭，五岭犹堪堵。","是以沧海珠，独向文心吐。","祝融司沐浴，百宝生渊府。","珊瑚拂钓竿，离奇难一罟。","鸿裁辉庙廊，逸制藏林薮。","诗骚虽小技，菁华散今古。","古今一快事，人间孰能取。","风度曲江遥，明兴丘霍睹。","其馀别岛间，灭没谁经数。","真儒继白沙，异人产东土。","手持列缺鞭，目送横霄羽。","钩刳岳渎函，倒索岩阿腑。","高深入见闻，动静归仰俯。","词林有柢根，艺苑明标竖。","时胸乱燕玞，汝器先周簠。","朱弦从疏越，球石方一拊。","宫商虽互鸣，淫哇必远拒。","悠悠作者怀，异世同奔鼓。","前人冀目成，后进求心祖。","风雅递相吹，鬼神安敢怒。","如铜君为炉，如木君为斧。","始观嘉量名，乃见从绳柱。","闭门出化工，天下称规矩。","是时我山居，髣髴登玄圃。","拟向白云潨，徐挥玉柄麈。","领袖推英绝，馀佩供编缕。","远近视宗盟，千年定客主。"]},{"t":"答方肃之二十韵","f":"五言古诗","c":["家本青山旁，白云守孤尚。","偶逐春风行，看花玉京上。","连裾尽百豪，中心无所向。","思从高世俦，尽除昏妄相。","方髯同客舍，披胸多古状。","新吟时警策，玄谈日疏放。","片冰置玉壶，满堂自清鬯。","深怀获素友，真堪竭腑脏。","平生意中事，今日为君偿。","携君共寥廓，天宇何悠旷。","舒晴漱晓阳，敛意餐宵沆。","排阊出雾尘，頩颜明始壮。","凌虚有共期，遐举谁堪让。","安知六月息，忽劳千里望。","梅花蔽重岚，苍蒹浮远浪。","每旦视秋光，所思独惆怅。","朝来玉水浮，寂寂黄花飏。","相传云锦书，满照幽轩障。","开缄念空谷，生刍安可忘。","慇勤附夙言，报尔以中贶。"]},{"t":"得肃之近集快读数遍作诗三首 其一","f":"五言律诗","c":["忆共芸香署，时登玄圃丘。","词坛推健笔，天府动清球。","溟涬穿心入，蒙泉刻意求。","祇今霜日照，复令水山收。"]},{"t":"得肃之近集快读数遍作诗三首 其二","f":"五言律诗","c":["纸上声疑出，篇终意有馀。","理于玄引淡，神以静来虚。","幽涧流清澈，高云诏卷舒。","掀髯兼面壁，吾欲问其初。"]},{"t":"得肃之近集快读数遍作诗三首 其三","f":"五言律诗","c":["黄初日已迈，中盛亦微移。","钱柳真同辈，储王是汝师。","不妨今作古，庶与运观时。","离索欣相感，源流尚可思。"]},{"t":"病臂","f":"五言律诗","c":["宓书疑或掣，庄化欲何为。","曲枕看云过，高叉叹日移。","拜稽应有待，舞蹈莫相欺。","聊以攀幽意，权当袖手时。"]},{"t":"食","f":"五言绝句","c":["曹肉终堪鄙，冯鱼那可歌。","三场吃不尽，一饱又如何。"]},{"t":"坐","f":"五言绝句","c":["与世真无事，斋心自可常。","龙雷何处觅，物我竟堪忘。"]},{"t":"季冬立春五绝 其一 故园","f":"五言绝句","c":["敢作故园主，幸当花木春。","东风曾识旧，为我岁华新。"]},{"t":"季冬立春五绝 其二 岭外","f":"五言绝句","c":["岭外春光早，阶前气色多。","庭花知我意，呼类引阳和。"]},{"t":"季冬立春五绝 其三 梅花","f":"五言绝句","c":["近识庭梅意，功成让百花。","芳为一岁敛，色与二阳赊。"]},{"t":"季冬立春五绝 其四 桃花","f":"五言绝句","c":["临风分巧笑，倚日共新妆。","烟景无留色，青春合断肠。"]},{"t":"季冬立春五绝 其五 李花","f":"五言绝句","c":["全身呈素质，满面去红妆。","有意从人淡，何心令蝶忙。"]},{"t":"壬申春晓西园即事五绝 其一","f":"七言绝句","c":["一样烟光共晓华，几般花木日交加。","请君试向西园看，春色人间第几家。"]},{"t":"壬申春晓西园即事五绝 其二","f":"七言绝句","c":["嫩柳池边渐学低，枝头忽见晓莺啼。","请伊再向东风问，春色人间齐未齐。"]},{"t":"壬申春晓西园即事五绝 其三","f":"七言绝句","c":["未许春风日夜忙，全凭晓色护微芳。","水浮花际添重影，山入庭前共一光。"]},{"t":"壬申春晓西园即事五绝 其四","f":"七言绝句","c":["试借风光共剪裁，霞分红艳雪分皑。","含情此日休相妒，同是当年一手栽。"]},{"t":"壬申春晓西园即事五绝 其五","f":"七言绝句","c":["少陵行步为春迷，江上寻花花索题。","我独闭门春在此，漫将玉水当花溪。"]},{"t":"走笔向宋尔孚乞绛桃一种","f":"七言绝句","c":["庭花数种聊当春，不尽春容春笑人。","漫想河阳千树色，敢希溪曲一枝新。"]},{"t":"又乞百叶桃一种","f":"七言绝句","c":["珍重当年禁苑春，助娇曾见倚栏人。","玄都观里千千树，岂似风前叶叶新。"]},{"t":"尔孚复以诗乞余长春花此种固来自尔孚也","f":"七言绝句","c":["长春花发倍添春，春浅春深识故人。","人日看春春日旧，春为人旧令花新。"]},{"t":"种菊","f":"七言绝句","c":["西园亦自有东篱，传语风光次第吹。","为爱霜华秋际满，漫赊春色雨中移。"]},{"t":"树兰","f":"七言绝句","c":["入抱惟应向晓芳，同心为尔日相望。","拟留幽佩偕荷制，肯令琴歌对草伤。"]},{"t":"见柳色桃花忽然有叹","f":"七言绝句","c":["柳色依依成旧绿，桃花冉冉褪新红。","流连有意从宵月，历乱无情任晓风。"]},{"t":"鸠","f":"五言律诗","c":["我观诸物意，惟尔独纯真。","拂羽当虹见，居巢许鹊邻。","春农颁首政，君子念平均。","三复鸤鸠什，其仪叹彼人。"]},{"t":"赏川茶花得行字四首","f":"七言律诗","c":["一枝红艳最分明，百朵飞华欲共荣。","种自峨眉传远色，光迎羯鼓动春情。","嗟君有赋梅何在，念尔为玄草未成。","且向芳菲同一醉，名花笔下易流声。"]},{"t":"步尔孚悠韵之作","f":"七言律诗","c":["春光翻借酒能游，寻得春情向酒搜。","酒在春前春亦在，春浮酒上酒交浮。","人方与酒邀春醉，花复从春散酒愁。","但使人花俱莫负，不妨春酒共悠悠。"]},{"t":"三三偕诸友及弟侄溯流溪北游松岗竹岗二岩兼陟黄岐绝顶薄暮还棹得目字","f":"七言古诗","c":["料理春事复三三，急趁春游偕五六。","春光有意诏游情，指点前山春在目。","一水从流晓溯之，双岩次第归遥蹴。","正当春日惠风和，天气芳新春气淑。","摇曳春心不自由，提携春伴姑相逐。","不须舆从竞开林，独许儿童共骑竹。","或前或后向山驰，不衫不履飘春服。","越陌度阡能几何，折柳穿兰及近麓。","舍车纵步趋前寺，有僧如鸟初出谷。","自言黄山一片春，久俟游踪留芬馥。","我谓山僧汝但行，登临未必惟我独。","山能令我与春迎，我能令人与山熟。","穷山之致必穷巅，探山之藏必探腹。","已陟崔嵬足未艰，欲尽烟霞身倍速。","遥看飞岭似翔鸾，俯瞰桑丘如逐鹿。","青帝留容入画图，祝融司英来沐浴。","此际孤宜定一尊，左右峰峦应伯叔。","冥思久对自沉吟，春云无数春山覆。","心悦春山山不知，春木有枝山有木。","振衣岂必千仞岗，市氛远处孤怀宿。","瑶台偃蹇不亲人，争似故山结缘夙。","从此故山若故人，一任春光作转毂。","毕竟年年春用来，遮莫山山春尽伏。","我今辞山袖春归，斜阳一道光蔌蔌。","眼中兰若蔽轻岚，林外游人并樵牧。","颇疑山鸟罢求声，珍重山花能满掬。","回车一一付轻舠，晚棹回映春溪绿。","简取消愁旧酒杯，起舞中流为春祝。","但愿春酒与春山，同尔春人俱穆穆。","兴言兹会良亦艰，摇笔春前细追录。"]},{"t":"代诸弟侄得斝字","f":"五言古诗","c":["出门无他事，青春有馀暇。","先生命我从，竹马随予驾。","童冠沂雩中，少长崇山下。","古人会心处，复为今人假。","是日惠风和，淑气交参差。","山卉不一名，皋兰可亲炙。","行行忽已疲，芳草犹堪藉。","双岩未易前，游人莫相讶。","循循学步趋，终抵烟霞架。","此身既临高，下视多惊怕。","低语问前山，云梯谁许借。","天路谅非遥，有志安能罢。","洗杯酌流泉，取味如佳蔗。","攀林动飞鸟，每畏松光泻。","薄暮共回裾，举手向山谢。","人多恋馀春，我云未卜夜。","幸从春山游，始识春云化。","何必满三杯，自当浮一斝。","携得山花归，敛意从书舍。","会当时努力，不使春即夏。"]},{"t":"看花饮宋尔孚清斋得脉字","f":"七言古诗","c":["日愁春尽向花索，不谓耽花情已癖。","意中每作俟时思，多方滋树培春脉。","悲秋有友晓相过，似于春事都有责。","徙倚花间聊徘徊，指点春光倍怜惜。","人来乃说载花舟，溯流宛在浮春壁。","携我披衣一观之，君翻为主我为客。","几株芳艳出李桃，数本青青留竹柏。","与君次第共平章，平分春色使君择。","为爱深红爱浅红，可怜瘦白怜肥白。","红白阶前何纷纷，午光欲炽炎光赫。","花容懒惰如吾疲，贤哉主人急张席。","谁能对此不花留，更许同人为春炙。","传杯颇令花欲酡，移樽每见春难却。","北海床头不易空，孟遵门内多藏轭。","花前莫问醉与醒，取醉为君君莫逆。","君赋梅花令客酬，我馀竹马从儿策。","壶奕分曹费黄昏，东墙日影正西掷。","有友狂奔意若何，临桥脱履似飞舄。","举手终当恕醉人，连裾仍向子京宅。","一丘曲折劳跻攀，十武仍须上山屐。","含思转袂觅初筵，天镜溶溶窥岸帻。","忽闻窦外大声呼，把臂登堂相肘掖。","屡舞傞傞向余歌，自誇一饮川吸百。","白眼观天卮未倾，惊座雄谈顿冰释。","独馀子云双鬓皤，主人歌骚扬拟易。","庭花相对寂无言，舍花欲去念花只。","出门不辞主不知，一天明月印归迹。","看花得酒步月归，花月与酒称三益。","閒步幽墀问我花，悠然不觉沁心魄。","叮咛此意寄来春，好留烟景记今夕。"]},{"t":"雨后春归招杨承之小酌待月作留春诗五绝三月十七日也 其一","f":"七言绝句","c":["青帝长门尽日幽，烟光欲去倩人留。","不妨春月平分夏，所畏花时忽近秋。"]},{"t":"雨后春归招杨承之小酌待月作留春诗五绝三月十七日也 其二","f":"七言绝句","c":["一榻经时尘易满，角巾折雨兴难无。","科头尽日愁春尽，满眼酤来为尔酤。"]},{"t":"雨后春归招杨承之小酌待月作留春诗五绝三月十七日也 其三","f":"七言绝句","c":["雕虫小技尔犹烦，宝剑雄篇我自存。","白酒床头初发瓮，苍苔屐齿速临门。"]},{"t":"雨后春归招杨承之小酌待月作留春诗五绝三月十七日也 其四","f":"七言绝句","c":["白眼看人休太憨，青春去我未全甘。","只宜花下吟诗醉，时向樽前纵酒谈。"]},{"t":"雨后春归招杨承之小酌待月作留春诗五绝三月十七日也 其五","f":"七言绝句","c":["红芳欲尽绿空肥，几度风前护落菲。","明月为人犹夜满，青春谁伴此时归。"]},{"t":"三月三十夜偕兄孟尝伯尝与承之小集春去十有三日矣因取平上去入之十三韵为五绝入十三","f":"七言绝句","c":["时光有意同消息，寄语烟风须自力。","即使秋冬促夏来，何须日夜催春亟。"]},{"t":"天中日王子龙招看龙舟得流字","f":"七言律诗","c":["画船声报午薰柔，暑雨初开诏远游。","斗酒何须劳待诏，角巾应自有同舟。","披襟风色微迎野，入眼云光急趁流。","千载骚魂如可见，一杯先酹碧溪头。"]},{"t":"孙蜚莪宋尔孚携酒琴过从得榴字是日夏尽","f":"七言律诗","c":["竹叶青樽满座浮，兰芳入抱暮风柔。","已凭长啸同销夏，莫使悲歌独赋秋。","此际惟堪文字饮，其中那许俗人留。","且从绿绮鸣幽涧，何必红裙妒石榴。"]},{"t":"修邑志成感赋四律","f":"楚辞体","c":["五纪提纲众目舒，内详外略转多馀。","书其重者将为后，心所违兮必问初。","直笔何曾刘五借，秽金总向魏收除。","已惭明镜空中似，或使虚舟夜半如。"]},{"t":"有挟改数字不得者再吟二律 其一","f":"七言律诗","c":["汝南每月顿更题，岭国千年那可齐。","旧墨新朱非偶见，大书小略莫三迷。","吴竞数字终难改，孙盛春秋独自携。","一任时心工射蜮，不妨神鬼共然犀。"]},{"t":"有挟改数字不得者再吟二律 其二","f":"七言律诗","c":["我闻其语昧其颜，贝锦何须费老悭。","肘掣能书安可怒，沙含频射亦惟艰。","鬼神名义千秋上，伯仲埙篪一念閒。","纵使涂黄由尔辈，终馀副稿在名山。"]},{"t":"又讯宋尔孚","f":"古风","c":["正当柳色风吹，独畏荷光雨移。","璞雅犹堪日注，玉骚几向秋悲。"]},{"t":"寄赠冯令君尔韬初擢给谏二首 其一","f":"七言律诗","c":["寒蝉秋至满空枝，鸣凤朝来见羽仪。","五谏方思臣职尽，七争岂为圣朝移。","绘图持节真何日，补牍牵裾又一时。","过署遥看新拊髀，弹车肯作旧歌辞。"]},{"t":"寄赠冯令君尔韬初擢给谏二首 其二","f":"七言律诗","c":["对弹初向赤墀阴，藏副先传碧岭岑。","每念驹遐难絷足，因思鹄举倍怀音。","榕江梧掖三年梦，枫阙蓬门两地心。","一自长安誇日近，几回空谷望云深。"]},{"t":"阿子歌九绝有序 其一","f":"五言绝句","c":["坠地原非汝，分形孰使为。","未芽先委露，那得怨霜吹。"]},{"t":"阿子歌九绝有序 其二","f":"五言绝句","c":["胜无良可慰，如幻亦何思。","谁种伤心业，为渠出腹儿。"]},{"t":"阿子歌九绝有序 其三","f":"五言绝句","c":["汝母生邻死，安能向汝持。","祇今衣裼在，空使血痕吹。"]},{"t":"阿子歌九绝有序 其四","f":"五言绝句","c":["风音来夜叶，雪片挂朝丝。","影响归何处，凄清独在兹。"]},{"t":"阿子歌九绝有序 其五","f":"五言绝句","c":["野马依空见，流星接瞬迷。","不知形所附，孰使气相吹。"]},{"t":"阿子歌九绝有序 其六","f":"五言绝句","c":["初月衔西树，微光寄远枝。","空怜长夜色，难假片华垂。"]},{"t":"阿子歌九绝有序 其七","f":"五言绝句","c":["索索残年绪，伤怀似远思。","霜云一片落，相对转迷离。"]},{"t":"阿子歌九绝有序 其八","f":"五言绝句","c":["我念人间世，同兹一息吹。","彭殇何寿夭，造物祇相欺。"]},{"t":"阿子歌九绝有序 其九","f":"五言绝句","c":["梦回如有失，肠乱不堪知。","阿子汝闻不，灯前百叹辞。"]},{"t":"韩山气象 公讳愈","f":"五言绝句","c":["道心原古圣，佛骨抗时君。","飞檄临潮渚，千秋仰遗文。"]},{"t":"贺监风流 知章","f":"五言绝句","c":["老大称狂客，风流遇谪仙。","解龟同换酒，骑马似乘船。"]},{"t":"辋川画意 王维","f":"五言绝句","c":["竹岭分朝翠，兰柴闭夕阴。","鸟鸣春涧黑，人啸月林深。"]},{"t":"江上花词 杜甫","f":"五言绝句","c":["行步欹危叟，爱花复怕春。","独凭诗酒在，恕此白头人。"]},{"t":"鹿门归兴 孟浩然","f":"五言绝句","c":["松月虚窗夜，幽人独往时。","本无蝉冕意，且赴鹿门期。"]},{"t":"石鱼醉歌 元结","f":"五言绝句","c":["漫翁愁独醒，时向石湖秋。","客醉知鱼乐，鱼欢为客游。"]},{"t":"人日自号三士道人","f":"七言律诗","c":["观我观生莫漫陈，为名为姓岂全真。","自从海内称三士，长愧山中少一人。","少许驱驰思夙志，老犹崛强问馀身。","所求心迹无他扰，何必渔樵是隐沦。"]},{"t":"人日立春浮云蔽日使人愁叹而问春","f":"七言律诗","c":["珠岛新烟百道屯，青阳已至莫逡巡。","寒光入水宜销散，旅绪如云自屈伸。","老去浮生终愧我，春来幽事强撩人。","梅花柳色今何在，辜负东风亦此身。"]},{"t":"听读书有感","f":"七言律诗","c":["嘿识应留万古神，休将疑难强吟呻。","羲经八卦无君子，孔论通篇四圣人。","今古漫随时代纪，往来谁是继开身。","此中糟粕真何用，堂上终须问斲轮。"]},{"t":"中兴一旅文武遗臣欲尽制乙未闻感叹有作","f":"七言律诗","c":["七载空思鹿野芩，九天谁听鹤皋音。","周家八士季为马，鲁国元侯伯是禽。","几见夔龙堪再命，漫言罴虎未全任。","何时一网收麟凤，蝣羽鹈梁莫浪歆。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其一","f":"五言律诗","c":["伐木来幽谷，诛茅获故居。","我怀终惬旧，山意亦留初。","海色林中隐，云光物外舒。","生涯安可说，且复任蘧庐。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其二","f":"五言律诗","c":["山色迷终古，春情自浅深。","此中求素托，何处可真寻。","鸟兽多无礼，林泉别有心。","谁堪携手共，同异问苔岑。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其三","f":"五言律诗","c":["旅绪终谁止，春光亦有初。","剪芜防甲折，植援俟条舒。","曲径微风转，西窗落照徐。","此中容抱膝，何敢问琴书。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其四","f":"五言律诗","c":["独有霞栖客，林峦未许迷。","寻幽同记忆，选胜自标题。","海色衣时卷，岩烟手日携。","颇疑空阔内，若与素心齐。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其五","f":"五言律诗","c":["即事才知止，劳生久息机。","风林时飒飒，云谷转依依。","群跃因潮起，孤鸣俟月飞。","春心徒目极，与物未相违。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其六","f":"五言律诗","c":["竹室团幽白，荆篱漏远光。","春林初照耀，晓岫日微茫。","物外风云淡，山中岁月长。","冥机时坦步，心迹两当忘。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其七","f":"五言律诗","c":["林峦相隐蔽，茅屋自荒深。","未了青春色，难伸白雪吟。","惊翔姑一止，哀啸且为音。","猿鸟人间物，安知物外心。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其八","f":"五言律诗","c":["微尚难矜己，虚荣独让时。","买山聊复尔，浮海亦安之。","止足明孤性，栖寻见夙思。","巢居何代子，不使世人知。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其九","f":"五言律诗","c":["遭人身欲退，适我物皆悠。","岩壑澄朝景，风潮变夕流。","高深时应接，今古日沉浮。","耳目周旋外，馀心尚可求。"]},{"t":"壬辰避地马鞍山治一枝未就兹春闻儆复于前址搆栖感赋十律 其十","f":"五言律诗","c":["世事环千虑，春容出万端。","林泉方滴沥，风雨莫迷漫。","独鸟依深树，群鸥就远澜。","且同尘外物，时向静中看。"]},{"t":"晚眺得初月有怀二首 其一","f":"五言律诗","c":["薄暮来孤眺，春愁强独宽。","轻云归远岫，初月动微澜。","物象宜高广，人心亦静安。","如何羁客绪，复自有千端。"]},{"t":"晚眺得初月有怀二首 其二","f":"五言律诗","c":["翠壁双流界，苍烟一带围。","空山犹作伴，芳草未同归。","往日催春色，回风动落晖。","伤心千里外，魂远莫予违。"]},{"t":"移居蓬罗七绝 其一","f":"七言绝句","c":["三神山在有无中，仙岛人区那可同。","我自耽幽思遁迹，安能逐景望璇宫。"]},{"t":"移居蓬罗七绝 其二","f":"七言绝句","c":["人亦有言松有林，惟予及尔是同岑。","相携物外凌霜质，独抱山中向日心。"]},{"t":"移居蓬罗七绝 其三","f":"七言绝句","c":["冥思已觉生如梦，回首方知色是空。","一室萧然山水内，海涛随意出松风。"]},{"t":"移居蓬罗七绝 其四","f":"七言绝句","c":["风潮每夜送馀音，身在高山意转深。","颇怪松吹多别调，凄凄尽作水龙吟。"]},{"t":"移居蓬罗七绝 其五","f":"七言绝句","c":["不分松声听似海，生增草色望如涛。","山心水意终难定，耳目当前莫漫骚。"]},{"t":"移居蓬罗七绝 其六","f":"七言绝句","c":["一片春山绿似醅，几多烟景白如皑。","为谁悦己时相向，淡扫浓妆百样裁。"]},{"t":"移居蓬罗七绝 其七","f":"七言绝句","c":["入山惟恐未全深，为鹤为猿万古心。","便许兹山留片石，时将真气朗云林。"]},{"t":"伤怀五绝 其一","f":"七言绝句","c":["未了馀生百自劳，伤怀一事若相遭。","无端更作幽山侣，错认松声是海涛。"]},{"t":"伤怀五绝 其二","f":"七言绝句","c":["苍松尽日舞烟风，为爱林栖息意同。","一自秋霜凋露白，懒从春水问溪红。"]},{"t":"伤怀五绝 其三","f":"七言绝句","c":["春思秋怨总相同，一寸柔肠百断中。","春草萋萋秋不见，教人长愧落花风。"]},{"t":"伤怀五绝 其四","f":"七言绝句","c":["朝云已去暮还归，长与山人共落晖。","举目跚跚频立望，空中虚影是耶非。"]},{"t":"伤怀五绝 其五","f":"七言绝句","c":["半载幽思孰共怜，几番愁梦倍凄然。","人间亦有伤怀者，未必钟情似我坚。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其一","f":"五言绝句","c":["禊日休临水，春风合在山。","山光无晓暮，为我独来还。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其二","f":"五言绝句","c":["冥冥天地色，缩缩古今情。","所遇多陈物，谁能郁化精。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其三","f":"五言绝句","c":["春与春相接，风光自发陈。","悲时成既往，适我尽皆新。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其四","f":"五言绝句","c":["玄崿流新润，烟林发旧华。","襟颜姑一寄，涯角且为家。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其五","f":"五言绝句","c":["风月同幽谷，林泉共小园。","只宜招士隐，不足为人言。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其六","f":"五言绝句","c":["山色看看翠，松风听听清。","眼中无俗韵，谷内有禽声。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其七","f":"五言绝句","c":["分风宜密岫，穿月赖疏林。","微照同幽意，轻吹中远心。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其八","f":"五言绝句","c":["西林悬细月，亦爱此松风。","淡扫春蛾黛，含情独向东。"]},{"t":"禊日春雨初宿西月微明思从中来漫成九绝 其九","f":"五言绝句","c":["秋魂无定止，春梦偶相持。","梦断如花落，从风不自知。"]},{"t":"四怨三愁五情诗 其一 一怨","f":"五言绝句","c":["燕丹谋国事，田樊空自戕。","卿匕一何短，王剑一何长。"]},{"t":"四怨三愁五情诗 其二 二怨","f":"楚辞体","c":["鸿沟不可割，乌江不可济。","虞兮从逝骓，幸不为人彘。"]},{"t":"四怨三愁五情诗 其三 三怨","f":"五言绝句","c":["策疲驱远道，偶得憩高林。","不解轩车至，喧阗尽此阴。"]},{"t":"四怨三愁五情诗 其四 四怨","f":"五言绝句","c":["山泉自宜清，海水自宜浊。","高深既已殊，浓淡休相学。"]},{"t":"四怨三愁五情诗 其五 一愁","f":"五言绝句","c":["昭阳迎晓日，长信坐秋风。","岂料诗书意，全为歌舞穷。"]},{"t":"四怨三愁五情诗 其六 二愁","f":"五言绝句","c":["玉露团幽桂，黄英送绿荷。","秋容无间歇，衰鬓独如何。"]},{"t":"四怨三愁五情诗 其七 三愁","f":"五言绝句","c":["花落叹丛孤，随风莫漫徂。","不念枝独处，当念子谁俱。"]},{"t":"四怨三愁五情诗 其八 一情","f":"五言绝句","c":["玉兔衔初景，婵娟又一时。","西林何所妒，不肯让蛾眉。"]}]};